window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s8-225","number":225,"surah":8,"verses":[59],"references":[{"surah":8,"verses":[59]}],"verseLabel":"الأنفال: 59","question":"لماذا ختم بـ﴿إنهم لا يعجزون﴾؟","answer":"﴿لا يعجزون﴾ تقطع توهم سبقهم؛ فهم لا يفوتون قدرة الله ولا يمنعونه من إدراكهم وإن أفلتوا مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص370، تحت عنوان «بلاغة التعبير بالمضارع وحذف مفعول ﴿يعجزون﴾»","url":""}]},{"id":"s8-226","number":226,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعدوا لهم ما استطعتم من قوة﴾، فأجمل القوة؟","answer":"أُجملت القوة لتشمل كل ما تتجدد به القدرة على الردع والقتال في كل عصر، وقُيدت بـ﴿ما استطعتم﴾ لربط التكليف بالطاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص375، تحت عنوان «بلاغة تنكير لفظ قوة»","url":""}]},{"id":"s8-227","number":227,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"لماذا خصّ ﴿رباط الخيل﴾ بعد عموم القوة؟","answer":"ذُكر رباط الخيل بعد عموم القوة لعظم أثره في زمن التنزيل وظهور منزلته في الاستعداد السريع والحراسة والقتال؛ فهو تخصيص لأبرز أفراد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص378، تحت عنوان «سر تخصيص الخيل بالذكر في سياق القرآن الكريم»","url":""}]},{"id":"s8-228","number":228,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما دلالة ﴿ترهبون به﴾ في بيان غاية إعداد القوة؟","answer":"تبين أن ظهور القوة يوقع الخوف في العدو، فيردعه عن الإقدام على قتال المسلمين أو إيذائهم، ويحد من الخيانة والعدوان. فالإعداد له أثر في ردع العدو قبل مباشرة القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص379، تحت «توجيه القراءات في قوله ﴿ترهبون﴾»","url":""}]},{"id":"s8-229","number":229,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرين من دونهم لا تعلمونهم الله يعلمهم﴾؟","answer":"أبهم الآخرون لأنهم خفيون على المؤمنين أو لم يدخلوا في دائرة معرفتهم، ثم قابل جهلهم بعلم الله المحيط ليبين أن الإعداد يردع العدو المعروف والمجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص380، تحت عنوان «فائدة التعبير بشبه الجملة ﴿من دونهم﴾»","url":""}]},{"id":"s8-230","number":230,"surah":8,"verses":[60,61],"references":[{"surah":8,"verses":[60,61]}],"verseLabel":"الأنفال: 60–61","question":"كيف يأمر القرآن بإعداد القوة لإرهاب العدو، ثم يأمر في الآية التالية مباشرة بقبول السلم إذا جنحوا له؟","answer":"الإعداد يحفظ قوة المؤمنين واستعدادهم، ثم بيّن النظم حكم ميل العدو إلى الصلح: يقبل إذا كان فيه مصلحة للمسلمين. فجمع السياق إعداد القوة وقبول السلم بحسب حال كل منهما، مع التوكل على الله وعدم إلغاء الصلح لمجرد احتمال الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «بلاغة المشاكلة في التعبير بالجنوح عن قبول المصالحة»","url":""}]},{"id":"s8-231","number":231,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا عبّر عن طلب السلم بالجنوح؟","answer":"الجنوح هو الميل، فتصور الكلمة انتقالهم الظاهر من جانب الحرب إلى جانب الصلح، وتعديتها للسلم تكشف جهة هذا الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «إيثار لفظ الجنوح ووجه تعديته وتضمينه»","url":""}]},{"id":"s8-287","number":287,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"ما بلاغة تكرار الجنوح في قوله: ﴿وإن جنحوا للسلم فاجنح لها﴾؟","answer":"كرر الفعل للمشاكلة: إن مالوا إلى السلم فمل إليها، فجاء الجواب موازيًا لفعلهم ومناسبًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «بلاغة المشاكلة في التعبير بالجنوح عن قبول المصالحة»","url":""}]},{"id":"s8-232","number":232,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا أُنّث الضمير في ﴿فاجنح لها﴾؟","answer":"أُنث الضمير لأنه يعود إلى ﴿السلم﴾ باعتبار معنى المسالمة أو المصالحة المؤنث، وهي لغة فصيحة في اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص388، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s8-233","number":233,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا ختم بـ﴿إنه هو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب ما يعلنونه من عرض السلم وما يدار من قول، و﴿العليم﴾ يحيط بما يخفونه من صدق أو خداع؛ وضمير الفصل يقوي انفراده بكمال الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص389، تحت عنوان «بلاغة التذييل في نهاية سياق الآية الجليل»","url":""}]},{"id":"s8-234","number":234,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يريدوا أن يخدعوك فإن حسبك الله﴾؟","answer":"جواب احتمال الخداع لم يكن رفض السلم، بل ﴿فإن حسبك الله﴾؛ أي الله كافيك شرهم، فاقبل الظاهر وتوكل على من يعلم الباطن ويحفظك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص396، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s8-235","number":235,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"لماذا جمع بين التأييد بالنصر وبالمؤمنين؟","answer":"جمع بين التأييد بالنصر الخارق للعادة، كإمداد الملائكة، والتأييد بالمؤمنين الذين ينصرونه بالأسباب المعهودة. وإعادة الباء تبرز نوعي التأييد؛ وكلاهما من فضل الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص402–403، تحت «غرض إعادة حرف الجر على المعطوف»","url":""}]},{"id":"s8-236","number":236,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿وألف بين قلوبهم﴾، دون أن يقال: جمعهم؟","answer":"التأليف إيجاد الألفة والمحبة بعد التفرق والعداوة، وهو أعمق من جمع الأجساد في مكان واحد؛ إذ يتعلق بوحدة القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص404، تحت «دلالة استعمال مفردة ﴿وألف﴾»","url":""}]},{"id":"s8-237","number":237,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿لو أنفقت ما في الأرض جميعًا ما ألفت بين قلوبهم﴾؟","answer":"الشرط يصور عجز كل مال الأرض عن صنع الألفة الحقيقية بين قلوب متعادية، فيظهر أن اجتماعهم آية من تدبير الله لا ثمرة شراء أو مصلحة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص406، تحت عنوان «سر التعبير بلو دون غيرها من أدوات الشرط»","url":""}]},{"id":"s8-238","number":238,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير في قوله تعالى: ﴿يا أيها النبي حسبك الله ومن اتبعك﴾؟","answer":"المعنى أن الله كافيك وكافي من اتبعك من المؤمنين، أو أن الله والمؤمنين حسبك على جهة أن الله أصل الكفاية وهم من أسبابها؛ والسياق يثبت للنبي ﷺ الطمأنينة بالجماعة المؤمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص418، تحت عنوان «سر استعمال مفردة الاتباع»","url":""}]},{"id":"s8-239","number":239,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير في قوله تعالى: ﴿حرض المؤمنين على القتال﴾ لا «أمرهم»؟","answer":"التحريض حث بالغ يوقظ الهمة ويقوي الدافع إلى الفعل، مع التنبيه إلى خطر تركه. فناسب مقام القتال الذي يحتاج إلى ترغيب وإقناع يزيلان التردد ويقيان الجماعة عاقبة التفريط.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص420–421، تحت «سر اختيار مفردة ﴿حرض﴾»","url":""}]},{"id":"s8-240","number":240,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"لماذا وصف الحكم الثاني بأنه تخفيف؟","answer":"لأن التكليف الأول ألزم الصابرين بالثبات أمام عشرة أمثالهم، ثم رحمهم الله فجعل الواجب الثبات أمام المثلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص427، تحت عنوان «نكتة التعبير بالتخفيف»","url":""}]},{"id":"s8-288","number":288,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما دلالة قوله: ﴿وعلم أن فيكم ضعفًا﴾؟","answer":"يبين الضعف علة التخفيف ومراعاة طاقتهم، ولا يعني أن علم الله بضعفهم حدث بعد خفاء؛ فعلمه محيط بهم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص429، تحت عنوان «سر التعبير بمفردة ضعفًا»","url":""}]},{"id":"s8-241","number":241,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"لماذا علل تفوق المؤمنين بأن الكافرين ﴿قوم لا يفقهون﴾؟","answer":"الفقه فهم نافذ يقدّر حقائق الأمور وعواقبها؛ والكافرون يقاتلون بلا بصيرة بالغاية ولا رجاء فيما عند الله، أما المؤمن فيضاعف فهمه وصبره قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص436، تحت عنوان «الفقه والعلم»","url":""}]},{"id":"s8-242","number":242,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾؟","answer":"صيغة ﴿ما كان لنبي﴾ تنفي ملاءمة اتخاذ الأسرى قبل الإثخان لسنة النبوة؛ لأن تثبيت سلطان الحق وكسر قوة العدو مقدم في بداية المواجهة على منفعة الفداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص444، تحت عنوان «غرض تنكير كلمة نبي»","url":""}]},{"id":"s8-243","number":243,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"لماذا قابل ﴿عرض الدنيا﴾ بـ﴿والله يريد الآخرة﴾؟","answer":"﴿عرض الدنيا﴾ شيء زائل قريب يُنال من الفداء، وقوبل بالآخرة الباقية التي يريد الله لهم ثوابها وإعزاز الدين الموصل إليها؛ فظهر تفاوت الإرادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص447، تحت عنوان «سر التعبير بعرض الدنيا عن المال»","url":""}]},{"id":"s8-244","number":244,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"ما فائدة الأمر في قوله: ﴿فكلوا مما غنمتم﴾؟","answer":"يؤكد الأمر حل الغنيمة ويزيل ما بقي في نفوسهم من التحرج بعد العتاب السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص453، تحت عنوان «غرض الأمر وفائدته»","url":""}]},{"id":"s8-289","number":289,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"لماذا وصف الغنيمة بأنها ﴿حلالًا طيبًا﴾؟","answer":"يزيد وصفها بالطيب طمأنتهم إلى نقاء الانتفاع بها، مع بقائه منضبطًا بتقوى الله وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص454، تحت عنوان «فائدة وصف الحال بالطيب»","url":""}]},{"id":"s8-245","number":245,"surah":8,"verses":[67],"references":[{"surah":8,"verses":[67]}],"verseLabel":"الأنفال: 67","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾، وقوله في سورة محمد: ﴿فإما منًّا بعد وإما فداء﴾؟","answer":"تلتقي الآيتان على تقديم الإثخان على الأسر والفداء؛ فالأنفال تنهى عن اتخاذ الأسرى قبل الإثخان، وآية محمد نفسها تقول: ﴿حتى إذا أثخنتموهم فشدوا الوثاق فإما منًّا بعد وإما فداء﴾. فذكر المن والفداء متعلق بما بعد الإثخان وإحكام الأسر، فلا تعارض بين ترتيب المرحلتين في الآيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص439، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s8-246","number":246,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا وُجّه خطاب الأسرى بواسطة النبي ﷺ؟","answer":"في توجيه القول إلى النبي ﷺ تشريف له وتثبيت لوظيفته في تبليغ الأسرى وعد الله وفتح باب الرجاء لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص463، تحت عنوان «سر خطاب الأسرى بواسطة النبي الأكرم»","url":""}]},{"id":"s8-290","number":290,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"ما الصورة في قوله: ﴿لمن في أيديكم من الأسرى﴾؟","answer":"تصور العبارة تمكن المسلمين من الأسرى وإحاطتهم بهم كأنهم في أيديهم، مع أن باب الخير والمغفرة ما زال مفتوحًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص464، تحت عنوان «براعة الاستعارة في جعل الأسرى في أيديهم»","url":""}]},{"id":"s8-247","number":247,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"هل يفيد قوله: ﴿إن يعلم الله في قلوبكم خيرًا﴾ شكًا في علم الله؟","answer":"لا؛ فالشرط متعلق بتحقق الخير في قلوب الأسرى، لا بعلم الله المحيط بهم، فكأن الوعد معلق بصدق تحولهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص467، تحت عنوان «دلالة عبارة ﴿إن يعلم الله﴾»","url":""}]},{"id":"s8-291","number":291,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا عبّر عن الإيمان بالخير في قوله: ﴿في قلوبكم خيرًا﴾؟","answer":"لأن صدق الإيمان أصل الخير الذي تتفرع عنه النية الصالحة والعمل، فجمعه اللفظ الواسع من مبدئه في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص469، تحت عنوان «سر التعبير بلفظ الخير عن الإيمان»","url":""}]},{"id":"s8-292","number":292,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"ما دلالة تكرار ﴿خيرًا﴾ في الآية؟","answer":"قابل خير القلوب بخير الجزاء، ووعدهم عوضًا يفوق ما أُخذ منهم ويشمل خير الدنيا وثواب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص470، تحت عنوان «دلالة تكرار لفظ خيرًا»","url":""}]},{"id":"s8-248","number":248,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا جمع بين التعويض والمغفرة؟","answer":"التعويض يجبر خسارة الدنيا، والمغفرة تزيل تبعة الماضي وتحقق خير الآخرة؛ فجمع لهم النفع العاجل والنجاة الآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص473، تحت عنوان «سر اختيار المغفرة في ﴿ويغفر لكم﴾»","url":""}]},{"id":"s8-249","number":249,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"ما دلالة تذكير الأسرى بخيانتهم لله من قبل؟","answer":"يذكرهم بأن كفرهم ونقضهم للعهد كانا سببًا في هزيمتهم، ويحذرهم من تكرار الخيانة بعد فتح باب الخير لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص482، تحت عنوان «دلالة الإخبار بخيانتهم لله»","url":""}]},{"id":"s8-293","number":293,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"لماذا قال: ﴿فأمكن منهم﴾ ولم يقل على المقابلة: «فخانهم»؟","answer":"لأن الخيانة وصف نقص لا ينسب إلى الله؛ فعبر عن جزائهم العادل بتمكين المؤمنين منهم، وهو قدرة وعدل لا خيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص483، تحت عنوان «نكتة العدول في ﴿فأمكن منهم﴾»","url":""}]},{"id":"s8-250","number":250,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"لماذا حذف مفعول ﴿فأمكن منهم﴾؟","answer":"حذف مفعول ﴿أمكن﴾ للإيجاز، لأن سياق الكلام يدل عليه؛ والتقدير: فأمكنكم الله منهم، أي جعلهم تحت قدرتكم. فالعمدة في الحذف ظهور المفعول من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص484، تحت «دلالة من في ﴿فأمكن منهم﴾»","url":""}]},{"id":"s8-252","number":252,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"ما دلالة ترتيب الإيمان ثم الهجرة ثم الجهاد؟","answer":"بدأ بأصل الاعتقاد، ثم أتبعَه بمفارقة موطن الكفر ونصرة الجماعة، ثم ببذل الوسع في حمايتها؛ فترقى من الأصل إلى آثاره العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص494، تحت عنوان «بلاغة ترتيب الصفات الإيمان والهجرة والجهاد»","url":""}]},{"id":"s8-294","number":294,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا قُدّم الجهاد بالمال على الجهاد بالنفس؟","answer":"لأن بذل المال أوسع وقوعًا وأكثر استمرارًا، وبه تجهز النفوس وأسباب القتال، ثم ذُكر بذل النفس وهو غاية التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص496، تحت عنوان «نكتة تقديم المال على النفس»","url":""}]},{"id":"s8-253","number":253,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم أولياء بعض﴾ تقرر ولاية متبادلة بين المهاجرين والأنصار تشمل النصرة والتعاون وما كان من أحكام الجماعة، فجعلتهم كتلة متكافلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص502، تحت «سر التعبير بالولاية من بعضهم لبعض»","url":""}]},{"id":"s8-254","number":254,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا نفى الولاية عن المؤمنين الذين لم يهاجروا مع بقاء إيمانهم؟","answer":"فرّق السياق بين تمام الولاية المرتبط بالهجرة وبين أصل الإيمان الذي أثبته لهم. ومن تفسير الولاية المنفية هنا التوارث والأحكام الخاصة بجماعة المهاجرين والأنصار، وليست نفيًا لكل نصرة دينية؛ إذ قال بعدها: ﴿وإن استنصروكم في الدين فعليكم النصر﴾. وجعل الهجرة غاية لهذا النفي وحثّهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص504، تحت عنوان «دلالة نفي الولاية»","url":""}]},{"id":"s8-255","number":255,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا استثنى النصرة عند وجود ميثاق مع قوم آخرين؟","answer":"استثنى القوم الذين بينهم وبين المسلمين ميثاقًا لوجوب الوفاء بالعهد؛ فلا تنقض المعاهدة استجابة لطلب النصرة. وجاء ختام الآية تذكيرًا برقابة الله على الوفاء بمواثيقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص510، تحت عنوان «بلاغة التذييل في آخر الآية الكريمة»","url":""}]},{"id":"s8-256","number":256,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]},{"surah":9,"verses":[20]}],"verseLabel":"الأنفال: 72؛ التوبة: 20","question":"ما سرّ التعبير في قوله تعالى في التوبة: ﴿وجاهدوا في سبيل الله بأموالهم وأنفسهم﴾، بينما قدم في الأنفال: ﴿بأموالهم وأنفسهم في سبيل الله﴾؟","answer":"من توجيه ذلك أن الأنفال سبق فيها ذكر الفداء والغنيمة و﴿عرض الدنيا﴾، فناسب تقديم ﴿بأموالهم وأنفسهم﴾ في وصف بذلهم. أما التوبة فسبق فيها ذكر الجهاد في سبيل الله، فناسب تقديمه. ويذكر المصدر أيضًا أن سياق الأنفال يعظم تضحية المهاجرين بأموالهم وأنفسهم، بينما سياق التوبة يقارن الجهاد بالسقاية وعمارة المسجد الحرام، فاختير لكل مقام ما يبرز فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص498–499، تحت «توجيه التشابه اللفظي في هذه الآية قيد التفسير»","url":""}]},{"id":"s8-257","number":257,"surah":8,"verses":[72,74,75],"references":[{"surah":8,"verses":[72,74,75]}],"verseLabel":"الأنفال: 72؛ الأنفال: 74–75","question":"لماذا حُذف قيدا المال والنفس بعد أن ذُكرا أولًا؟","answer":"اكتفى الموضع اللاحق بما سبق تفصيله؛ فصار إطلاق الجهاد حاملًا معنى البذل بالمال والنفس من غير حاجة إلى تكرارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص526، تحت عنوان «سر حذف ذكر المال والنفس»","url":""}]},{"id":"s8-295","number":295,"surah":8,"verses":[72,74,75],"references":[{"surah":8,"verses":[72,74,75]}],"verseLabel":"الأنفال: 72؛ الأنفال: 74–75","question":"ما دلالة قوله: ﴿وجاهدوا معكم﴾؟","answer":"تفيد المعية إلحاق المتأخرين بالسابقين ومشاركتهم الفعلية في جهاد الجماعة، لا مجرد ادعاء الانتساب إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص539، تحت عنوان «دلالة معكم»","url":""}]},{"id":"s8-258","number":258,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين كفروا بعضهم أولياء بعض﴾ في مقابلة ولاية المؤمنين؟","answer":"كما يتناصر المؤمنون، يتناصر الكافرون بحكم اجتماعهم على الكفر والمصلحة؛ فالمقابلة تحذر المؤمنين من ترك ولايتهم التي تحفظ جماعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص514، تحت عنوان «دلالة الواو في الجملة المبدوءة بالموصول»","url":""}]},{"id":"s8-259","number":259,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"لماذا أبهم الفعل في قوله: ﴿إلا تفعلوه﴾؟","answer":"يتسع الفعل المبهم لمجموع ما تقدم من أحكام الولاية والنصرة والوفاء، فيحذر من تعطيل هذا النظام كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص516، تحت عنوان «سر التعبير بقوله إلا تفعلوه»","url":""}]},{"id":"s8-296","number":296,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"إلى ماذا يعود الضمير في قوله: ﴿إلا تفعلوه﴾؟","answer":"يحتمل أن يعود إلى النصرة أو حفظ الميثاق أو مجموع أحكام الولاية المتقدمة، وتتسع العبارة لهذه المعاني المتكاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص516، تحت عنوان «تعدد مرجع الضمير في سياق الآية»","url":""}]},{"id":"s8-297","number":297,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"لماذا سُمّيت عاقبة ترك الولاية والنصرة فتنة؟","answer":"لأن ترك المؤمنين بلا نصرة يعرضهم للاضطهاد والاضطراب، ويفتن الناس عن دينهم، ثم يفضي إلى فساد واسع في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص517، تحت عنوان «سر اختيار التعبير بالفتنة»","url":""}]},{"id":"s8-260","number":260,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا أعاد وصف المهاجرين والأنصار ثم قال: ﴿أولئك هم المؤمنون حقًا﴾؟","answer":"أعيد وصفهم بعد تفصيل أحكام الولاية تثبيتًا لفضل الهجرة والنصرة والجهاد، ثم أكد بـ﴿أولئك هم المؤمنون حقًا﴾ أن أعمالهم حققت دعوى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص528، تحت عنوان «نفي التكرار بين الآيات قيد التفسير»","url":""}]},{"id":"s8-261","number":261,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا قُدمت المغفرة على الرزق الكريم؟","answer":"لأن المغفرة تزيل تبعة التقصير أولًا، ثم يأتي الرزق الكريم تتميمًا للنعمة بعد صفاء الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص533، تحت عنوان «سر تقديم المغفرة على الرزق الكريم»","url":""}]},{"id":"s8-298","number":298,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا ذُكرت الدرجات في أول السورة ولم تُذكر هنا مع المغفرة والرزق الكريم؟","answer":"زاد الموضع الأول الدرجات لأنه يعدد مراتب صفات الإيمان، أما هنا فالمقام للشهادة بصدق الهجرة والجهاد والإيواء والنصرة، فناسبه الوعد بالمغفرة والرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص533، تحت عنوان «سر اختلاف فاصلة هذه الآية عن سابقتها»","url":""}]},{"id":"s8-262","number":262,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"لماذا أُلحق المتأخرون في الهجرة بقوله: ﴿فأولئك منكم﴾؟","answer":"تقرر ﴿منكم﴾ دخول من تأخر ثم هاجر وجاهد في جماعة السابقين وولايتهم وأحكامهم. وفي التعبير تشريف لهم وإلحاق بالمتقدمين، مع بقاء فضل السبق؛ فالمشاركة في الولاية لا تستلزم تساوي المراتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص540، تحت عنوان «دلالة من في قوله منكم»","url":""}]},{"id":"s8-263","number":263,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"ما سرّ تقديم أولو الأرحام في الحكم بعد تقرير أخوة الإيمان؟","answer":"أخوة الإيمان أصل الولاية والنصرة، أما أولو الأرحام فأولى في الحكم الخاص بالميراث وسائر الحقوق التي خصها الشرع بالقرابة؛ فلا تعارض لاختلاف المجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص541، تحت عنوان «سر التعبير بصيغة التفضيل أولى»","url":""}]},{"id":"s8-264","number":264,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿في كتاب الله﴾؟","answer":"﴿في كتاب الله﴾ تثبت أن أولوية الأرحام حكم مكتوب مقرر في شرع الله وعلمه، لا ترتيبًا ناشئًا من عرف الناس أو مصالحهم المؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص542، تحت عنوان «سر تقييد أولوية أولي الأرحام في كتاب الله»","url":""}]},{"id":"s8-265","number":265,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"لماذا ختمت السورة بـ﴿إن الله بكل شيء عليم﴾؟","answer":"خُتمت السورة بالعلم المحيط لأنه أساس دقة أحكام الأنفال والعهود والولاية والمواريث؛ فالله يعلم المصالح والنيات والصلات، ويضع لكل منها حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص544، تحت عنوان «براعة ختم السورة»","url":""}]},{"id":"s9-1","number":1,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا بدأت سورة التوبة من غير بسملة، بخلاف سائر سور القرآن؟","answer":"يذكر المؤلف في تفسير اسم «القرينة» خبرًا عن عثمان يربط ترك البسملة بقرن الأنفال والتوبة معًا في المصحف. فهذا الوجه يربط تلك الخصوصية باقتران السورتين وترتيبهما في المصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص548–550، تحت «أسماؤها المذكورة وسبب تسميتها: القرينة»","url":""}]},{"id":"s9-2","number":2,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما براعة افتتاح السورة بالمصدر: ﴿براءة﴾؟","answer":"جعل المصدر قطع العهد عنوانًا للسورة وأول ما يقرع السمع، فبدأ الحكم بقوة ووضوح قبل تفصيل أسبابه وآثاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «براعة الاستهلال بالمصدر براءة»","url":""}]},{"id":"s9-697","number":697,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما دلالة تنكير كلمة ﴿براءة﴾؟","answer":"يفيد التنكير التفخيم: إنها براءة عظيمة الشأن تترتب عليها أحكام عامة في العهود والمواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص563، تحت عنوان «دلالة التنكير في براءة»","url":""}]},{"id":"s9-3","number":3,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿براءة﴾، دون أن يقال: «تبرؤ» أو «نقض عهد»؟","answer":"البراءة خلاص وانفصال مما يوجب الضرر أو الالتزام؛ فاختيرت لتعلن رفع تبعة العهد وقطع رابطته بعد ما وقع من نقضه. ويبين اللفظ أن المقصود فسخ المعاهدة والإذن بزوال التزامها، لا مجرد انقضائها الطبيعي بانتهاء الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «براعة الاستهلال بالمصدر براءة»","url":""}]},{"id":"s9-4","number":4,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما موقع ﴿براءة﴾ من الإعراب، وما أثر افتتاح السورة بالجملة الاسمية؟","answer":"يجوز أن تكون خبرًا لمبتدأ محذوف، أي هذه براءة، أو مبتدأ تخصص بوصفه وخبره متعلق بما بعده. والجملة الاسمية تقرر ثبوت البراءة وتحققها عند الله، مع إفادة أمر المخاطبين بإجرائها؛ فاجتمع تثبيت الحكم ومعنى الإنشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «دلالة الافتتاح بالجملة الاسمية»","url":""}]},{"id":"s9-5","number":5,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا نُسبت البراءة إلى الله ورسوله في ﴿براءة من الله ورسوله﴾؟","answer":"لأن الله هو الذي حكم بالبراءة وأذن فيها، والرسول ﷺ يبلغ حكمه ويباشر تنفيذه. فنسبت إليهما مع اختلاف الجهة: تشريع وإذن من الله، وتبليغ وإجراء من رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص565، تحت عنوان «معنى العطف بين الله ورسوله»","url":""}]},{"id":"s9-6","number":6,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿من الله ورسوله﴾، ولم يكرر حرف الجر فيقول: «من الله ومن رسوله»؟","answer":"جمعهما حرف جر واحد لأن البراءة الصادرة حكم واحد، ولإظهار اتصال تبليغ الرسول بأمر الله، مع بقاء الله مصدر الحكم ورسوله مبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص566، تحت «دلالة عدم تكرار من مع الرسول»","url":""}]},{"id":"s9-7","number":7,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا اختير حرف الابتداء ﴿من﴾ في ﴿براءة من الله﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ أي إن منشأ هذا الحكم ومصدر صدوره من عند الله ورسوله، فليست البراءة رأيًا بشريًا أو تصرفًا منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص564، تحت «دلالة تعدية المصدر بالحرف»","url":""}]},{"id":"s9-8","number":8,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا عُبر عن المعاهدة بالماضي: ﴿عاهدتم﴾؟","answer":"الماضي ﴿عاهدتم﴾ يقرر وقوع العهد وثبوته قبل إعلان البراءة، فيبني الحكم على عقد سبق وجوده لا على احتمال مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «نكتة التعبير بالماضي في عاهدتم»","url":""}]},{"id":"s9-9","number":9,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿عاهدتم من المشركين﴾، فأدخل ﴿من﴾ على المشركين؟","answer":"﴿من﴾ بيانية تبين صنف المعاهدين؛ لأن العهد قد يكون مع أهل الكتاب أو غيرهم، فجاء ﴿من المشركين﴾ ليزيل هذا الاحتمال ويحدد المقصود. ثم تبين الآيات التالية حكم من بقي منهم وفيًا بعهده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «دلالة من»","url":""}]},{"id":"s9-10","number":10,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا نسب المعاهدة إلى المسلمين: ﴿عاهدتم﴾، مع أن النبي ﷺ هو الذي عقدها؟","answer":"أسندت المعاهدة إلى المؤمنين لأنهم طرفها الملزم بمراعاتها وتنفيذ حكمها، وإن تولى الرسول ﷺ عقدها. وفي الإسناد تشريف لهم بوفائهم، وتنبيه إلى أن الإخلال جاء من الجهة الأخرى وأنهم أهل خطاب التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «دلالة إسناد فعل المعاهدة في عاهدتم»","url":""}]},{"id":"s9-11","number":11,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما الذي أفاده قوله تعالى ﴿فسيحوا في الأرض أربعة أشهر﴾؟","answer":"أفاد تمكينهم من السير آمنين في الأرض خلال مهلة محددة قبل انتهاء الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص571، تحت عنوان «اصطفاء لفظ فسيحوا»","url":""}]},{"id":"s9-12","number":12,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيحوا﴾، دون أن يقال: «فسيروا» أو «اذهبوا»؟","answer":"السياحة هي السير الممتد في سعة وأمن وتصرّف، فناسبت المهلة الممنوحة لهم، وهي أوسع دلالة من مجرد الذهاب أو السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص571، تحت عنوان «اصطفاء لفظ فسيحوا»","url":""}]},{"id":"s9-13","number":13,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا قيد السياحة بقوله: ﴿في الأرض﴾؟","answer":"يفيد القيد تعميم الإذن بالسير الآمن في جهات الأرض خلال المهلة. كما يحدد المقصود بالسياحة هنا بأنه السير في الأرض، لأن لفظ السياحة قد يستعمل في غيره؛ ولا يمنع ذلك ما يذكره المصدر من أصلها التصويري المشبه بجريان الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص572–573، تحت «دلالة التقييد في الأرض»","url":""}]},{"id":"s9-14","number":14,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما الحكمة من منحهم مهلة في قوله: ﴿فسيحوا في الأرض أربعة أشهر﴾؟","answer":"أعطتهم المهلة أمانًا وفرصة للنظر في أمرهم قبل انتهاء العهد، ليعلموا ما سيؤول إليه موقفهم ويختاروا على بينة. وتحديد المدة يبين أن الإمهال مضبوط بأجل، فيتحقق الإنذار دون مباغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص570، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-15","number":15,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما أثر ذكر ﴿أربعة أشهر﴾ بعد قوله: ﴿في الأرض﴾؟","answer":"أتبع القيد المكاني بقيد زماني ليضبط مهلة البراءة من جهتي المكان والزمان؛ فالإذن بالسياحة ليس مطلق المدة، بل ينتهي عند أجل معلوم. وفي هذا البيان إظهار عدل الحكم وإزالة ما قد يلتبس في حدود الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص573، تحت «فائدة التقييد بالظرف أربعة أشهر»","url":""}]},{"id":"s9-16","number":16,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنكم غير معجزي الله﴾، دون أن يقال: «لن تعجزوا الله»؟","answer":"يجمع التركيب نفي الإعجاز وتثبيت ذلك في حقهم، وجاء اسم الفاعل دالًا على ثبوت عجزهم عن الإفلات في الحال والاستقبال. و﴿غير﴾ تنفي عنهم القدرة على الإعجاز مهما اختلفت أحوالهم؛ فلا يغترون بالإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574، تحت عنوان «دلالة غير»","url":""}]},{"id":"s9-17","number":17,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا اختير وصف ﴿غير معجزي الله﴾ بدل «مغلوبون»؟","answer":"﴿غير معجزي الله﴾ ينفي قدرتهم على السبق والإفلات، وهو أدق من «مغلوبون»؛ فقد يتأخر أخذهم لكنهم لا يعجزون الله بحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574–575، تحت «اصطفاء لفظ معجزين»","url":""}]},{"id":"s9-18","number":18,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا انتقل من خطاب المشركين إلى الغيبة في قوله: ﴿وأن الله مخزي الكافرين﴾؟","answer":"انتقل من مواجهتهم في ﴿أنكم﴾ إلى وصف جنسهم بـ﴿الكافرين﴾؛ ليجعل الخزي سنة عامة في كل من ثبت على الكفر، لا خبرًا خاصًا بالحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص576، تحت عنوان «بلاغة الإظهار في مقام الإضمار وأن الله»","url":""}]},{"id":"s9-19","number":19,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿مخزي الكافرين﴾ بصيغة اسم الفاعل؟","answer":"اسم الفاعل ﴿مخزي﴾ يفيد ثبوت الخزي وتحققه واستمراره، فكأن وقوعه وصف قائم لا مجرد فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص576، تحت «إيثار التعبير باسم الفاعل»","url":""}]},{"id":"s9-20","number":20,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا وصفهم في الخاتمة بالكافرين بعد تسميتهم أولًا بالمشركين؟","answer":"وصف الشرك أخص، ثم جاء وصف الكفر الأعم ليشمل الوعيد كل من استمر على الكفر. فانتقل السياق من بيان شأن المعاهدين المشركين إلى تعميم التحذير وتقوية سبب الخزي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص577، تحت «التعبير بوصف الكفر ومجيئه مفعولا للإخزاء»","url":""}]},{"id":"s9-21","number":21,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا أعاد إعلان البراءة في قوله: ﴿وأذان من الله ورسوله﴾ بعد قوله في الآية الأولى: ﴿براءة من الله ورسوله﴾؟","answer":"البراءة في الآية الأولى نفس الحكم، و﴿أذان﴾ هنا إعلان ذلك الحكم وتبليغه إلى الناس في يوم مشهود؛ فالثانية ليست إعادة للأولى بل إشهار لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص585، تحت عنوان «حكمة التكرار في صيغة البراءة»","url":""}]},{"id":"s9-22","number":22,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أذان﴾، دون أن يقال: «إعلام»؟","answer":"الأذان إعلام مرتفع يبلغ الأسماع ويشيع، فناسب الإعلان العام في الحج أكثر من لفظ «إعلام» الذي لا يفيد قوة النداء وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص593، تحت «الأذان والإعلام»","url":""}]},{"id":"s9-23","number":23,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما أثر التعبير بالاسم ﴿أذان﴾ بدل الاقتصار على فعل يدل على الإعلام؟","answer":"التعبير بالاسم يثبت الإعلان ويقرره، ويجعل البلاغ أمرًا قائمًا يتناوله الناس، لا حدثًا عابرًا مقيدًا بزمن. والجملة خبرية تتضمن طلب تبليغ هذا الحكم وإشاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص581، تحت عنوان «بلاغة التعبير بالاسمية دون الفعل»","url":""}]},{"id":"s9-24","number":24,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الناس﴾، مع أن البراءة متعلقة بالمشركين؟","answer":"وُجه الأذان إلى الناس جميعًا لأن أحكام العهود والحج والأمان تمس المجتمع كله، وليشهد المؤمن والمشرك الإعلان فلا تبقى جهالة أو شبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص581، تحت عنوان «سر التقييد بـإلى الناس»","url":""}]},{"id":"s9-25","number":25,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا وصف يوم الحج بأنه ﴿الأكبر﴾؟","answer":"من تفسير ﴿يوم الحج الأكبر﴾ أنه يوم النحر لاجتماع أكثر أعمال الحج فيه، وقيل المراد زمن الحج عمومًا. ووصف الحج بالأكبر يميزه من العمرة المسماة الحج الأصغر، ويناسب عموم الاجتماع الذي يبلغ فيه الإعلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص582–583، تحت «حكمة الوصف في الحج الأكبر»","url":""}]},{"id":"s9-26","number":26,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا صُرّح باسم الله ورسوله مرة أخرى في ﴿أن الله بريء من المشركين ورسوله﴾؟","answer":"لزيادة البيان في إعلان موجه إلى جمهور متنوع، ولقطع المعاذير، فكان التصريح أوضح من الإضمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص587، تحت «نكتة التصريح بفعل البراءة مرة ثانية»","url":""}]},{"id":"s9-27","number":27,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أن الله بريء من المشركين ورسوله﴾، دون أن يقال: «أن الله ورسوله بريئان»؟","answer":"أثبتت الجملة براءة الله أولًا، ثم براءة رسوله ﷺ على جهة مستقلة في التعبير، فكأن البراءة معلنة من جهتين لتقوية الوعيد وتقريره. ويراعي هذا النظم عموم الإعلان للناس، ويؤكد أن الله ورسوله بريئان من المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص586–587، تحت «علة تأخير لفظ الرسول»","url":""}]},{"id":"s9-28","number":28,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا رُفع ﴿ورسوله﴾ بعد قوله: ﴿من المشركين﴾، مع احتمال التباس السامع؟","answer":"رُفع ﴿ورسوله﴾ لأنه معطوف على محل اسم الجلالة أو مبتدأ خبره محذوف تقديره «بريء»، فلا يجوز جره عطفًا على المشركين؛ والرفع يمنع المعنى الفاسد عند تمام التركيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص586، تحت «موقع جملة ورسوله مما قبله»","url":""}]},{"id":"s9-29","number":29,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا جاء بعد إعلان البراءة مباشرة: ﴿فإن تبتم فهو خير لكم﴾؟","answer":"عقب إعلان البراءة ببيان حال التوبة، إظهارًا للرغبة في رجوعهم وفتحًا لباب الخير لهم. فالحكم ليس إغلاقًا لطريق الهداية؛ بل إن تابوا من الشرك كان ذلك خيرًا لهم، ورحمهم الله وغفر لهم ما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص587، تحت عنوان «دلالة تبتم»","url":""}]},{"id":"s9-30","number":30,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فهو خير لكم﴾، ولم يصرح بما في التوبة من النجاة والمغفرة؟","answer":"﴿خير لكم﴾ عبارة جامعة لكل خير التوبة في الدنيا والآخرة، وترك التفصيل يطلق الذهن لاستحضار أنواع النجاة والمغفرة والأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص588، تحت عنوان «إيثار اصطفاء خير»","url":""}]},{"id":"s9-31","number":31,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا قابل التوبة بقوله: ﴿وإن توليتم فاعلموا أنكم غير معجزي الله﴾؟","answer":"قوبلت التوبة بالتولي لإظهار الطريقين وعاقبتيهما: الرجوع خير، والإعراض لا يحقق نجاة؛ لأنهم لا يفوتون قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص590، تحت عنوان «دلالة تكرار نفي إعجازهم والفرق بينه وبين السابق قبله»","url":""}]},{"id":"s9-32","number":32,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿وبشر الذين كفروا بعذاب أليم﴾، واستعمل البشارة في العذاب؟","answer":"من وجوه التعبير استعمال البشارة تهكمًا: ينتظر السامع منها خبرًا سارًا، فإذا الذي يبلغه عذاب أليم، فيشتد التحسر والوعيد. ويذكر المصدر أيضًا وجه حملها على أصل الإخبار بما يظهر أثره على البشرة، خيرًا كان أو شرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص591–592، تحت «دلالة الحقيقة والمجاز في البشارة المذكورة»","url":""}]},{"id":"s9-33","number":33,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا استثنى من البراءة المشركين الذين لم ينقصوا المسلمين شيئًا ولم يظاهروا عليهم أحدًا؟","answer":"استُثني الموفون لأن البراءة من الناقضين لا تبيح خيانة من حفظ عهده؛ فالعدل يوجب إتمام مدته لمن لم ينقص ولم يعن عدوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص596، تحت عنوان «دلالة مفهوم الوصف بنفي النقص عنهم»","url":""}]},{"id":"s9-34","number":34,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينقصوكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم كل نقص، قليلًا أو كثيرًا، فتؤكد كمال وفائهم وعدم إخلالهم بأي حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص597، تحت «إيثار كلمة شيئًا وتنكيرها»","url":""}]},{"id":"s9-35","number":35,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا عبّر عن إعانة العدو بقوله: ﴿ولم يظاهروا عليكم أحدًا﴾؟","answer":"المظاهرة المعاونة؛ وأصلها أن يجعل المعين نفسه ظهرًا يقوي صاحبه، فالتعبير يصور اتحادهم مع العدو في القوة والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص597، تحت عنوان «دلالة اشتقاق يظاهروا»","url":""}]},{"id":"s9-36","number":36,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتموا إليهم عهدهم﴾، دون أن يقال: «فاحفظوا عهدهم»؟","answer":"الإتمام إيصال العهد إلى نهاية مدته كاملًا غير منقوص، وهو أدق من «الحفظ» الذي قد يدل على مجرد عدم النقض دون استيفاء الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص599، تحت عنوان «دلالة حرف الانتهاء إليهم»","url":""}]},{"id":"s9-37","number":37,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا أضاف العهد إليهم: ﴿عهدهم﴾، مع أنه عهد بين طرفين؟","answer":"إضافة العهد إليهم تذكّر بأنهم حفظوه والتزموا حدوده، فاستحقوا أن يتم لهم. وفيها إبراز لحقهم في الوفاء، مع أن العهد قائم بين الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص599، تحت «دلالة الإضافة إلى الضمير»","url":""}]},{"id":"s9-38","number":38,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا ختم الأمر بالوفاء بقوله: ﴿إن الله يحب المتقين﴾؟","answer":"ختم بمحبة المتقين لأن الوفاء للمعاهد المخالف مع القدرة عليه من التقوى؛ فالخاتمة تعلل الإتمام وتجعله طاعة لله لا مجرد مصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص601، تحت عنوان «علة الفصل في إن الله يحب المتقين»","url":""}]},{"id":"s9-39","number":39,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا علّق الأمر بقتال المشركين على انسلاخ الأشهر الحرم؟","answer":"عُلّق القتال بانتهاء المهلة صيانة للأمان الذي مُنح لهم، فلا يبدأ الحكم قبل تمام الأجل وبلوغ الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص603، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-40","number":40,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿انسلخ الأشهر الحرم﴾، فشبّه الزمن بشيء ينسلخ؟","answer":"استعير الانسلاخ لانقضاء الأشهر وزوال ما فيها من وقاية وأمان، كما ينفصل الجلد عن الجسد. فتبرز الصورة الانتقال من زمن تحميهم فيه المهلة إلى ما بعدها، وتناسب حركة الأحداث والأحكام في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص605، تحت عنوان «اصطفاء لفظ انسلخ»","url":""}]},{"id":"s9-41","number":41,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا جاءت الأوامر متتابعة: ﴿فاقتلوا... وخذوهم واحصروهم واقعدوا لهم﴾؟","answer":"جمعت الأوامر أنواع الإذن في مواجهة المعنيين بالحكم بعد انقضاء المهلة: القتل والأخذ والحصر والترصد. ولا يلزم جمع هذه الأفعال في كل شخص؛ بل يختلف الإجراء بحسب الإمكان والقدرة والمصلحة، فيشمل النظم صورًا متعددة من المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص608–609، تحت «معنى العطف بالواو»","url":""}]},{"id":"s9-42","number":42,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿حيث وجدتموهم﴾ مع وجود استثناءات العهود والأمان في السياق؟","answer":"العموم مقيد بالسياق: فهو في المشركين الناقضين بعد انقضاء مهلتهم، لا أهل العهد المستقيم ولا طالب الأمان المذكور في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص607، تحت عنوان «دلالة اصطفاء المشركين»","url":""}]},{"id":"s9-43","number":43,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وخذوهم﴾ بعد ذكر القتل؟","answer":"ذُكر الأخذ بعد القتل ليشمل الأسر والقبض على من لم يقع عليه القتل؛ فليس الأمر مقصورًا على صورة واحدة من المعاملة الحربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص615، تحت عنوان «الأخذ والأسر»","url":""}]},{"id":"s9-44","number":44,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما الصورة في قوله: ﴿واقعدوا لهم كل مرصد﴾؟","answer":"صوّرهم مترقبين في طرق العدو ومداخله، حتى كأن كل موضع ترصد قد صار مجلسًا ثابتًا لهم يمنع الحركة المعادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص609، تحت عنوان «نكتة التعبير بلفظ القعود»","url":""}]},{"id":"s9-45","number":45,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿كل مرصد﴾، فنصب المرصد، دون أن يقال: «في كل مرصد»؟","answer":"وصل الفعل إلى ﴿كل مرصد﴾ مباشرة على الظرفية، فدل على استغراق مواقع الرصد وأجزائها بحسب القدرة. ويذكر المصدر أن توسيط حرف الجر قد يحتمل الوقوف في موضع من المرصد، فجاء التعبير المباشر أوضح في الاستيعاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص611، تحت «وجه إيصال الفعل للظرف بنفسه»","url":""}]},{"id":"s9-46","number":46,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا فتح باب النجاة بعد هذه الشدة بقوله: ﴿فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلوا سبيلهم﴾؟","answer":"جعلت التوبة وإقامة الصلاة وإيتاء الزكاة دليلًا ظاهرًا على الدخول في جماعة المسلمين، فيترتب عليها تخلية السبيل ورفع التعرض. فالأوامر السابقة يتغير حكمها في حق من تحقق فيه هذا الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص611، تحت عنوان «نكتة تعيين الصلاة والزكاة بعد التوبة»","url":""}]},{"id":"s9-47","number":47,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا عبّر عن تركهم بقوله: ﴿فخلوا سبيلهم﴾؟","answer":"تخلية السبيل كناية عن رفع كل تعرض ومنع، كأن طريقهم كان محبوسًا فأطلق؛ وهي أوسع من مجرد «اتركوهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص612، تحت عنوان «اصطفاء لفظ سبيلهم»","url":""}]},{"id":"s9-48","number":48,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا ختمت آية القتال بـ﴿إن الله غفور رحيم﴾؟","answer":"ناسب ﴿غفور رحيم﴾ قبول التوبة بعد الكفر والعداء؛ فالمغفرة تمحو الماضي والرحمة تفتح لهم حياة جديدة بين المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص614، تحت عنوان «تضمن الجملة الخبرية معنى الإنشاء»","url":""}]},{"id":"s9-49","number":49,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن أحد من المشركين استجارك﴾، فأفرد ﴿أحد﴾ بعد الحكم العام؟","answer":"﴿أحد﴾ تعم من يطلب الأمان، ولا تقتصر على جماعة بأكملها. ويبين المصدر أنها تتناول الفرد والجماعة، وأن التقييد بـ﴿من المشركين﴾ يدخل المستجير من القوم الذين سبق ذكر حكمهم؛ فالحكم العام لا يسقط حق المستجير في الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص618–619، تحت «بلاغة التعبير بلفظ أحد»","url":""}]},{"id":"s9-50","number":50,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا تقدّم ﴿أحد﴾ على فعله في قوله: ﴿وإن أحد من المشركين استجارك﴾؟","answer":"تقدم ﴿أحد﴾، مع تقدير فعل يفسره ﴿استجارك﴾، للعناية بذات المستجير. فالمقصود الحرص عليه بإجارته وإسماعه القرآن رجاء هدايته، لا الاقتصار على ذكر فعل الاستجارة مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص619، تحت «سر تقديم المسند إليه أحد»","url":""}]},{"id":"s9-51","number":51,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿فأجره﴾، ولم يكتف بالنهي عن قتله؟","answer":"﴿فأجره﴾ أمر إيجابي بمنحه الحماية، وهو أبلغ من مجرد عدم قتله؛ إذ يوجب صونه وتمكينه من سماع الحق في أمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص619، تحت عنوان «دلالة أسلوب الخطاب في قوله استجارك»","url":""}]},{"id":"s9-52","number":52,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا جُعلت غاية الأمان أن ﴿يسمع كلام الله﴾؟","answer":"جُعل سماع كلام الله غاية الأمان ليعرف حقيقة الدعوة من مصدرها قبل الحكم عليها، فتقام الحجة في جو خالٍ من الإكراه والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص623، تحت «وجه جعل سماع كلام الله غاية للإجارة»","url":""}]},{"id":"s9-53","number":53,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿كلام الله﴾، دون أن يقال: «القرآن»؟","answer":"﴿كلام الله﴾ يبرز مصدر القرآن وشرفه وحجيته؛ فالمستجير لا يسمع كلام بشر بل الوحي الذي دُعي إلى الإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص621، تحت «دلالة إضافة الكلام إلى الاسم الجليل»","url":""}]},{"id":"s9-54","number":54,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما مناسبة قوله تعالى بعد إسماع المستجير القرآن: ﴿ثم أبلغه مأمنه﴾؟","answer":"إبلاغه مأمنه وفاء بالأمان حتى بعد سماع القرآن؛ فلا يترك عرضة للقتل في طريق العودة، سواء آمن أم اختار الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص622، تحت عنوان «معنى ثم في قوله ثم أبلغه مأمنه»","url":""}]},{"id":"s9-55","number":55,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا لم يُلزم المستجير بالإسلام بعد سماع كلام الله؟","answer":"لأن الإجارة تمتد إلى مدة سماع القرآن والنظر فيه، ثم إلى الرجوع الآمن إن لم يسلم. فالأمر بإبلاغه مأمنه يحفظ له الأمان بعد السماع، ويمنع أن تتحول فرصة البيان إلى تعرض له في طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص622، تحت عنوان «معنى ثم في قوله ثم أبلغه مأمنه»","url":""}]},{"id":"s9-56","number":56,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا علّل حمايته بقوله: ﴿ذلك بأنهم قوم لا يعلمون﴾؟","answer":"عللت الآية الإجارة وإسماع القرآن وتبليغ المأمن بجهلهم، لإتاحة العلم والبيان لهم قبل اتخاذ موقفهم. وفي التعليل بيان للرفق بهم والعناية بإزالة سبب الجهل، حتى يفهموا ما دُعوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص624، تحت عنوان «دلالة الإشارة في ذلك بأنهم وعلة الفصل»","url":""}]},{"id":"s9-57","number":57,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا بدأ بالاستفهام: ﴿كيف يكون للمشركين عهد عند الله وعند رسوله﴾؟","answer":"الاستفهام إنكاري يستبعد ثبوت عهد عام لمن ظهرت خيانتهم، ويمهد لاستثناء من استقام على عهده؛ فلا ينفي كل عهد بلا تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص627، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s9-58","number":58,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا كرر ﴿عند﴾ في ﴿عند الله وعند رسوله﴾؟","answer":"يكرر الظرف تقرير الإنكار من كل جهة: لا عهد محفوظ لهم عند الله ولا عند رسوله مع خيانتهم. وفيه تقوية استبعاد بقاء عهد من لا يراعي العهد، وتأكيد صدور البراءة من الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص632–633، تحت «دلالة تكرار الظرف عند»","url":""}]},{"id":"s9-59","number":59,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا استثنى مرة أخرى أهل العهد عند المسجد الحرام؟","answer":"أعيد الاستثناء لأن السياق بعد الإنكار العام يحتاج إلى إخراج الموفين صراحة، لئلا يحمل ذم الناقضين على نقض عهد المستقيمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص634، تحت عنوان «براعة الاستدراك بقوله إلا الذين عاهدتم»","url":""}]},{"id":"s9-60","number":60,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا جعل وفاء المسلمين تابعًا لاستقامتهم: ﴿فما استقاموا لكم فاستقيموا لهم﴾؟","answer":"جعل الوفاء مقابل وفائهم تحقيقًا للعدل؛ فمدة استقامتهم هي مدة لزوم الاستقامة لهم، فإذا نقضوا زال موجب استمرار العهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص635، تحت عنوان «دلالة الفاء في قوله فما استقاموا»","url":""}]},{"id":"s9-61","number":61,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"ما دلالة ﴿لكم﴾ و﴿لهم﴾ في قوله: ﴿فما استقاموا لكم فاستقيموا لهم﴾؟","answer":"تخصص الجملتان الاستقامة بعلاقة الطرفين وعهدهما، وتربطان وفاء المسلمين بوفاء المعاهدين لهم. وفي مقابلة ﴿لكم﴾ بـ﴿لهم﴾ تأكيد أن الاستقامة المطلوبة وفاء متبادل منضبط بالعهد، وليست التزامًا مطلقًا يستمر مع نقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص638، تحت عنوان «بديع المقابلة في قوله لكم ولهم»","url":""}]},{"id":"s9-62","number":62,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا تكررت مادة الاستقامة في الشرط والجواب؟","answer":"تكررت الاستقامة ليقابل الوفاءُ الوفاءَ، ويجيء الجزاء من جنس الشرط. وفي مادة الاستقامة تصوير للثبات على العهد بلزوم الطريق المستقيم دون انحراف؛ فأكد تكرارها هذا المعنى في الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص638، تحت عنوان «بديع المقابلة في قوله لكم ولهم»","url":""}]},{"id":"s9-63","number":63,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا ختم مرة أخرى بـ﴿إن الله يحب المتقين﴾؟","answer":"كرر الختم لأن الوفاء في هذا الموضع أيضًا امتحان للتقوى، ولتأكيد أن الاستقامة للمعاهدين محبوبة لله وليست ضعفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص639، تحت عنوان «دلالة إن في قوله إن الله يحب المتقين»","url":""}]},{"id":"s9-64","number":64,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا أعاد الاستفهام بكلمة واحدة: ﴿كيف﴾؟","answer":"أعادت ﴿كيف﴾ وحدها إنكار إمكان بقاء العهد، ثم فصلت علة الإنكار: أنهم إن يظفروا لا يراعوا قرابة ولا عهدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص644، تحت عنوان «سر تكرار اسم الاستفهام كيف»","url":""}]},{"id":"s9-65","number":65,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يظهروا عليكم﴾، دون أن يقال: «وإن ينتصروا»؟","answer":"الظهور هو العلو والغلبة والتمكن، وهو أوسع من مجرد الانتصار في واقعة؛ إذ يصور صيرورتهم فوق المسلمين قادرين عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص647، تحت عنوان «بلاغة قوله يظهروا عليكم»","url":""}]},{"id":"s9-66","number":66,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا جمع بين ﴿إلًّا ولا ذمة﴾؟","answer":"﴿الإل﴾ يشمل القرابة أو العهد والحلف، و﴿الذمة﴾ حرمة الأمان والالتزام؛ فالجمع ينفي مراعاتهم للرابطة الطبيعية والحق التعاقدي معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص656، تحت عنوان «الإل والذمة والعهد والميثاق واليمين»","url":""}]},{"id":"s9-67","number":67,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿يرضونكم بأفواههم وتأبى قلوبهم﴾؟","answer":"الصورة تقابل بين ظاهر الكلام وباطن الاعتقاد: أفواه تنطق بما يرضي، وقلوب ترفض الوفاء؛ فتفضح التناقض والنفاق في معاملتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص650، تحت عنوان «براعة الاستئناف البياني في يرضونكم»","url":""}]},{"id":"s9-68","number":68,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا نُسب الإرضاء إلى الأفواه والإباء إلى القلوب؟","answer":"نُسب الإرضاء للأفواه لأنه قول سطحي لا يجاوز اللسان، ونُسب الإباء للقلوب لأنها محل النية والعزم الحقيقي؛ فظهر انفصال القول عن الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص653، تحت عنوان «براعة تعليق الإرضاء بقوله بأفواههم»","url":""}]},{"id":"s9-69","number":69,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا عبّر عن رفض القلوب بـ﴿تأبى﴾ لا «تكره»؟","answer":"الإباء يدل على شدة الامتناع ورفض ما تدعو إليه الأقوال الظاهرة، مع القدرة على الامتثال. فهو يكشف أن المشكلة ليست عجزًا عن الوفاء، بل رفضًا يعزمون عليه في قلوبهم، فيؤكد زيف ما يظهرونه بأفواههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص654، تحت «نكتة التعبير بلفظ وتأبى»","url":""}]},{"id":"s9-70","number":70,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وأكثرهم فاسقون﴾، ولم يعمم الفسق عليهم جميعًا؟","answer":"الفسق هنا نقض العهد والخروج عما توجبه المروءة والوفاء، لا مجرد الكفر الذي سبق وصفهم به. فنسب إلى أكثرهم لأن فيهم من يحفظ العهد أو يتعفف عن بعض صور الغدر، فجاء التقييد دقيقًا في تحديد الصفة المرادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص655–656، تحت «سبب الحكم بالفسق على الأكثرين»","url":""}]},{"id":"s9-71","number":71,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا صوّر استبدالهم بآيات الله بقوله: ﴿اشتروا بآيات الله ثمنًا قليلًا﴾؟","answer":"استعير الشراء لاستبدالهم آيات الله ومقتضاها بمصلحة عاجلة؛ فصوروا كتاجر باع النفيس الباقي بثمن حقير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص660، تحت عنوان «بلاغة الاستعارة في ثمنًا قليلًا»","url":""}]},{"id":"s9-72","number":72,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا وصف الثمن بـ﴿قليلًا﴾ مهما عظم في أعينهم؟","answer":"كل عرض دنيوي قليل إذا قيس بآيات الله وثوابها، ولو عظم في أعينهم؛ فالقلة نسبية إلى ما تركوه وإلى سرعة زواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص661، تحت عنوان «سبب وصف الثمن بالقليل»","url":""}]},{"id":"s9-73","number":73,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة الفاء في قوله: ﴿فصدوا عن سبيله﴾؟","answer":"تفيد أن الصد نتيجة مباشرة لصفقتهم الخاسرة؛ فلما آثروا الثمن القليل ترتب عليه إعراضهم وإعراض غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص662، تحت عنوان «دلالة الفاء في فصدوا»","url":""}]},{"id":"s9-698","number":698,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة حذف مفعول ﴿فصدوا﴾؟","answer":"يتسع الحذف لأن يشمل صدهم أنفسهم وصدهم غيرهم عن سبيل الله، فيكشف عموم أثر فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص663، تحت عنوان «دلالة حذف مفعول فصدوا»","url":""}]},{"id":"s9-74","number":74,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة إضافة السبيل إلى الله في قوله: ﴿فصدوا عن سبيله﴾؟","answer":"الإضافة تشرف السبيل وتبين أنه الطريق الموصل إلى الله ورضوانه، فيعظم قبح الصد عنه. كما تربط الضمير بذكر آيات الله قبله، فتظهر أن الإعراض عن الآيات يفضي إلى الصد عن سبيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص663، تحت عنوان «فائدة الإضافة في قوله سبيله»","url":""}]},{"id":"s9-75","number":75,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا ختم بـ﴿إنهم ساء ما كانوا يعملون﴾، ولم يقل: «ساء عملهم»؟","answer":"﴿ما كانوا يعملون﴾ تجعل الذم واقعًا على جنس عملهم المتجدد المستمر، لا على عمل مفرد، وتبرز رسوخ السوء في عادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص665، تحت عنوان «دلالة ما في ما كانوا يعملون»","url":""}]},{"id":"s9-76","number":76,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا كرر: ﴿لا يرقبون في مؤمن إلًّا ولا ذمة﴾ بعد وروده في الآية 8؟","answer":"الموضع الأول يعلل استبعاد عهدهم عند التمكن، والثاني يقرر الصفة نفسها في حق كل مؤمن ويمهد للحكم عليهم بالاعتداء؛ فزاد السياق الثاني تقريرًا وتعميمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص669، تحت «مناسبة مجيء الآية بطريق الفصل دون الوصل»","url":""}]},{"id":"s9-77","number":77,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"ما فائدة تقديم ﴿في مؤمن﴾؟","answer":"يوجه النظر إلى أن عداوتهم متعلقة بالمؤمن من حيث إيمانه، لا بخصومة عارضة مع جماعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص670، تحت عنوان «فائدة التقديم في قوله في مؤمن»","url":""}]},{"id":"s9-699","number":699,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا عبّر بوصف ﴿مؤمن﴾ بدل ضمير الجماعة؟","answer":"يجعل الوصف الإيماني نفسه سبب عداوتهم، ويعمم الحكم ليشمل كل فرد تحققت فيه صفة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص671، تحت عنوان «سر صيغة المشتق في قوله مؤمن»","url":""}]},{"id":"s9-78","number":78,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا أفرد ﴿مؤمن﴾ مع أن الحديث عن جماعة؟","answer":"أُفرد ﴿مؤمن﴾ في سياق النفي ليعم كل مؤمن واحدًا واحدًا؛ فهم لا يراعون الحرمة في أي فرد متصف بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص671، تحت «فائدة التنكير في لفظ ﴿مؤمن﴾»","url":""}]},{"id":"s9-79","number":79,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا قال: ﴿وأولئك﴾؟","answer":"يشير اسم الإشارة إلى أصحاب الصفات المتقدمة، فيربط الحكم بما ظهر منهم من نكث وطعن وعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص672، تحت عنوان «سبب إيثار التعبير باسم الإشارة»","url":""}]},{"id":"s9-700","number":700,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"ما دلالة ضمير الفصل في قوله: ﴿هم المعتدون﴾؟","answer":"يقوي إثبات الاعتداء لهم ويحصره فيهم على سبيل المبالغة أو رد دعواهم أن المسلمين هم المعتدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص672، تحت عنوان «دلالة القصر بضمير الفصل في هم المعتدون»","url":""}]},{"id":"s9-701","number":701,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا وصفهم بالمعتدين؟","answer":"لأن صفاتهم السابقة تجاوزت حد العهد والحق، فجمع الوصف نكثهم وطعنهم وبدءهم بالعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص673، تحت عنوان «سبب إيثار الإخبار عنهم بلفظ المعتدون»","url":""}]},{"id":"s9-80","number":80,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا كرر شروط التوبة والصلاة والزكاة بعد ذكرها في الآية 5؟","answer":"في الآية الخامسة كانت الشروط سببًا لتخلية سبيلهم ووقف القتال، وهنا هي أساس دخولهم في أخوة الدين؛ فتكرر اللفظ واختلف الأثر المبني عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-81","number":81,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فإخوانكم في الدين﴾، وقال في الآية 5: ﴿فخلوا سبيلهم﴾؟","answer":"﴿فخلوا سبيلهم﴾ يبين زوال حكم القتال، أما ﴿فإخوانكم في الدين﴾ فيرتقي بهم إلى العضوية الكاملة في جماعة المؤمنين؛ فالثاني أبلغ في بيان أثر التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-82","number":82,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا قُيدت الأخوة بقوله: ﴿في الدين﴾؟","answer":"أضيفت الأخوة إلى الدين لتحديد أساسها الجديد: العقيدة الجامعة، لا النسب أو الحلف، ولتقرير ما يترتب عليها من حقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص680، تحت عنوان «دلالة التقييد في الدين»","url":""}]},{"id":"s9-83","number":83,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا خُص تفصيل الآيات بقوم يعلمون؟","answer":"لأنهم الذين يتدبرون الفروق بين أحكام العهد والتوبة والقتال، ثم يعملون بما كشفه هذا التفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص682، تحت عنوان «فائدة التقييد بقوله لقوم يعلمون»","url":""}]},{"id":"s9-702","number":702,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"ما دلالة المضارع في ﴿نفصل﴾ و﴿يعلمون﴾؟","answer":"يفيد تجدد البيان واستمرار انتفاع أهل العلم به، فكلما تدبروا الآيات ازداد انكشاف الأحكام لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683، تحت عنوان «دلالة المضارع نفصل ويعلمون»","url":""}]},{"id":"s9-84","number":84,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن نكثوا أيمانهم﴾، فشبّه نقض العهد بنكث الحبل؟","answer":"النكث في الأصل حل فتل الحبل، فاستعير لنقض الأيمان بعد إحكامها؛ إذ يصير العهد المحكم كحبل فُكّت قواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص688، تحت عنوان «بلاغة الاستعارة في نكثوا أيمانهم»","url":""}]},{"id":"s9-85","number":85,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد عهدهم﴾ مع أن النكث لا يكون إلا بعد العهد؟","answer":"﴿من بعد عهدهم﴾ تؤكد شناعة النكث؛ فقد وقع بعد ميثاق ثابت مخصوص، لا قبل انعقاده أو عن جهل بوجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص689، تحت عنوان «دلالة الإضافة في عهدهم»","url":""}]},{"id":"s9-86","number":86,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا جمع بين نكث الأيمان والطعن في الدين؟","answer":"جمع بين خيانة العهد والقدح في الدين، فزاد ذكر الطعن بيانًا لعداوتهم. ومن توجيهات العطف أن الطعن صورة من النكث خُصت بالذكر لشناعتها، ومن توجيهاته اعتبارهما وصفين اجتمعا فيهم؛ فلا يختزل المعنى في مخالفة عملية وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص689–690، تحت «دلالة الواو في وطعنوا»","url":""}]},{"id":"s9-87","number":87,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا عبّر عن الإساءة إلى الدين بـ﴿طعنوا في دينكم﴾؟","answer":"الطعن حقيقته الضرب بآلة نافذة، فاستعير للقدح الشديد في الدين؛ لما يحدثه من أذى ومحاولة تمزيق حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص690، تحت عنوان «دلالة لفظ وطعنوا»","url":""}]},{"id":"s9-88","number":88,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا وصفهم بأنهم ﴿أئمة الكفر﴾؟","answer":"لرسوخهم في الكفر وتقدمهم في النكث والطعن حتى صاروا قادة يقتدي بهم غيرهم في العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص692، تحت عنوان «دلالة التعبير بلفظ أئمة»","url":""}]},{"id":"s9-703","number":703,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا خُص أئمة الكفر بالأمر بالقتال؟","answer":"لأن كف قادة العدوان يضعف أثرهم في أتباعهم ويوقف التحريض والنكث من منبعهما الأشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص693، تحت عنوان «مناسبة الأمر بقتال أئمة الكفر دون غيرهم»","url":""}]},{"id":"s9-89","number":89,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لا أيمان لهم﴾ بعد ذكر أيمانهم التي نكثوها؟","answer":"أثبتت لهم الأيمان من حيث صدورها بألسنتهم، ثم نفت الاعتداد بها لعدم الوفاء. فالأيمان التي لا يحفظونها نُزلت منزلة المعدوم، وفي ذلك تعليل للأمر بقتال الناكثين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص696، تحت عنوان «دلالة النفي في لا أيمان لهم لما أثبت»","url":""}]},{"id":"s9-90","number":90,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا خُتم القتال بقوله: ﴿لعلهم ينتهون﴾؟","answer":"غاية القتال أن ينتهوا عن النكث والطعن والعدوان، لا أن يكون القتل مطلوبًا لذاته؛ و﴿لعل﴾ تفتح إمكان رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص697، تحت عنوان «سر التعبير بقوله لعلهم ينتهون»","url":""}]},{"id":"s9-91","number":91,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا افتتحت الآية بالتحضيض: ﴿ألا تقاتلون قومًا﴾؟","answer":"﴿ألا﴾ للتحضيض الشديد؛ تستنكر التردد في قتال قوم اجتمعت منهم أسباب القتال، وتحرك همة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص702–703، تحت «بلاغة التحضيض في ألا تقاتلون»","url":""}]},{"id":"s9-92","number":92,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا سُردت جرائمهم: نكث الأيمان، والهم بإخراج الرسول، والبدء بالقتال؟","answer":"سرد الجرائم يبني الحجة من ثلاث جهات: نقض الحق، والعدوان على الرسول، والبدء بالحرب؛ فلا يبقى للتردد مسوغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص704، تحت عنوان «سبب إيثار وصف القوم بثلاث جمل متعاطفة»","url":""}]},{"id":"s9-93","number":93,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿هموا بإخراج الرسول﴾، دون أن يقال: «هموا بإخراج محمد»؟","answer":"التعريف بالعهد يستحضر الرسول المعروف في قلوب المخاطبين بما له من الهيبة والتعظيم. وذكره بوصف الرسالة أبلغ هنا في تهويل جرأتهم على إخراجه واستنهاض المؤمنين لنصرته من الاقتصار على اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707، تحت «دلالة أل في لفظ الرسول»","url":""}]},{"id":"s9-94","number":94,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ تقديم الضمير في ﴿وهم بدءوكم أول مرة﴾؟","answer":"تصدير الجملة بالضمير وبناؤها بناءً اسميًا يؤكد نسبة المبادأة إليهم، فيقرر أنهم بدأوا بالعدوان، ويقوي التحريض على دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707، تحت «براعة التعبير بقوله وهم بدءوكم أول مرة»","url":""}]},{"id":"s9-95","number":95,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿أول مرة﴾ مع أن البدء لا يكون إلا أولًا؟","answer":"يؤكد القيد أنهم أصحاب المبادأة بالعدوان منذ بدايته، فيزيد تقرير موجب قتالهم وذمهم، وإن كان معنى الابتداء مفهومًا من الفعل نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707–708، تحت «دلالة النصب والإضافة في قوله أول مرة»","url":""}]},{"id":"s9-96","number":96,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا انتقل فجأة إلى السؤال: ﴿أتخشونهم﴾؟","answer":"انتقل إلى ﴿أتخشونهم﴾ لكشف علة التردد بعد ثبوت موجبات القتال؛ فالذي قد يبقى ليس نقص الحجة بل خوف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص708، تحت عنوان «براعة الحث على القتال»","url":""}]},{"id":"s9-97","number":97,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فالله أحق أن تخشوه﴾، فجاء باسم التفضيل؟","answer":"ليس المقصود إثبات استحقاق الطرفين لخشية التعظيم ثم ترجيح أحدهما، بل تقرير أن الله وحده المستحق لها. فجاء اسم التفضيل لرد ما عرض لهم من خشية العدو، وحملهم على تقديم أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص709، تحت عنوان «دلالة اسم التفضيل أحق»","url":""}]},{"id":"s9-98","number":98,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا ختم بقوله: ﴿إن كنتم مؤمنين﴾؟","answer":"التعليق بالإيمان يستنهض مقتضاه؛ فالإيمان الحق يجعل خشية الله مقدمة ويمنع التخاذل عن أمره، وليس المراد نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص710، تحت عنوان «بلاغة التعبير بأسلوب الشرط»","url":""}]},{"id":"s9-99","number":99,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿قاتلوهم يعذبهم الله بأيديكم﴾، فنسب الفعل إلى المؤمنين والعذاب إلى الله؟","answer":"المؤمنون يباشرون القتال بأيديهم، والله يجعله عذابًا مستحقًا وينفذ به حكمه؛ فنسبت المباشرة إليهم والتقدير والجزاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص718، تحت «بلاغة المجاز العقلي»","url":""}]},{"id":"s9-100","number":100,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا اختير ﴿يعذبهم﴾ لا «يهزمهم»؟","answer":"اختير ﴿يعذبهم﴾ لأن الهزيمة تصف النتيجة العسكرية فقط، أما التعذيب فيجعل ما ينزل بهم جزاءً على كفرهم وعدوانهم، ويشمل القتل والأسر والذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص717، تحت «سر اختيار لفظ يعذبهم»","url":""}]},{"id":"s9-101","number":101,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما سر تقييد العذاب بقوله: ﴿بأيديكم﴾؟","answer":"فيه تشريف للمؤمنين بأن يجعلهم الله سببًا في تعذيب أعدائهم، وبشارة بإقدارهم عليهم. ووقوع ذلك بأيديهم أبلغ في شفاء صدورهم، وأشد على العدو من عذاب لا يكون المؤمنون وسيلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص718، تحت «سر تعليق العذاب بأيدي المؤمنين»","url":""}]},{"id":"s9-102","number":102,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا جمع أربعة آثار للقتال: تعذيبهم، وإخزاؤهم، ونصر المؤمنين، وشفاء الصدور؟","answer":"جمعت الآثار استيفاءً لوجهي الجزاء: ما يصيب العدو من عذاب وخزي، وما يناله المؤمنون من نصر وشفاء؛ فظهر أثر القتال في الخارج والنفس معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص716–717، تحت «براعة التعبير بتتابع الجزاء ودلالتها على التأييد الإلهي»","url":""}]},{"id":"s9-103","number":103,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا عبّر عن إزالة الألم بقوله: ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"شُبه زوال ألم المؤمنين وغيظهم بشفاء المريض؛ لأن أذى المشركين استقر في صدورهم كالداء، فجاء النصر علاجًا يزيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص720–721، تحت «بلاغة الاستعارة التصريحية التبعية»","url":""}]},{"id":"s9-104","number":104,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما دلالة الانتقال من خطاب المقاتلين إلى الغيبة في قوله: ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"ينوه الانتقال بالمؤمنين بوصف الإيمان، ويجعل شفاء صدورهم ثمرة ظاهرة ينظر إليها المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص720، تحت عنوان «مناسبة الخطاب في التعذيب والنصر والغيبة في سواهما»","url":""}]},{"id":"s9-704","number":704,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا قال: ﴿قوم مؤمنين﴾ ولم يقل: «صدوركم»؟","answer":"يتسع لفظ القوم لكل من آذاه المعتدون من المؤمنين، ولو لم يكن من المخاطبين الذين باشروا القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص721، تحت عنوان «نكتة التعبير بلفظ قوم»","url":""}]},{"id":"s9-105","number":105,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"ما وجه عطف ﴿ويذهب غيظ قلوبهم﴾ على ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"من توجيهاته اختلاف الأثرين: شفاء الصدور يرفع ألم الأذى، وذهاب الغيظ يزيل ما بقي من حرارته. وذُكر أيضًا أن العطف يؤكد تمام الشفاء، أو يترقى من حصول السرور بالنصر إلى زوال الغيظ؛ فالمعنيان متكاملان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص722–723، تحت «مناسبة العطف»","url":""}]},{"id":"s9-106","number":106,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿غيظ قلوبهم﴾ بعد قوله: ﴿صدور قوم مؤمنين﴾؟","answer":"الغيظ حرارة شديدة محلها القلب، والقلب أخص من الصدر. أما الهم والألم الناشئان عن الأذى فيناسبهما التعبير بالصدور؛ فجيء بالقلوب عند بيان زوال الغيظ خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص721، تحت عنوان «مناسبة التعبير بلفظ الصدور دون القلوب»","url":""}]},{"id":"s9-107","number":107,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا جاء بعد القتال قوله: ﴿ويتوب الله على من يشاء﴾؟","answer":"يبين ذكر التوبة أن بابها مفتوح لمن رجع من المشركين، وأن القتال لا يقتضي تعذيب كل فرد منهم. فقد يكون ما يرونه من النصر وكسر شوكة الكفر سببًا في رجوع بعضهم إلى الإيمان، فيتوب الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص724، تحت عنوان «مناسبة مجيء قوله ويتوب الله بالوصل دون الفصل»","url":""}]},{"id":"s9-108","number":108,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا عُلقت التوبة بالمشيئة؟","answer":"تعليقها بالمشيئة يبين أن التوفيق للتوبة بيد الله، لا نتيجة لازمة لكل من وقع عليه القتال. وحذف مفعول ﴿يشاء﴾ يوجه إلى عموم قدرته وفضله، دون تقييد قبول التوبة بسبب مخصوص مذكور في اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص726، تحت عنوان «دلالة التعبير بالموصول من»","url":""}]},{"id":"s9-109","number":109,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بمن يستحق الهداية وبما في القلوب، و﴿حكيم﴾ في النصر والتعذيب والتوبة؛ فكل حكم موضوع في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص727، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-110","number":110,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تتركوا﴾ بعد أوامر القتال؟","answer":"﴿أم حسبتم﴾ تنكر ظن أن يتركوا بلا اختبار بعد أمر القتال؛ فالدعوى لا تكفي حتى يظهر صدق الجهاد والولاء بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص729، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-111","number":111,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم﴾ مع أن الله يعلمهم قبل الجهاد؟","answer":"ليس المراد حدوث علم بعد جهل، بل ظهور المعلوم في عالم العمل ليتميز المجاهد المخلص وتقوم عليه الحجة ويترتب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص734، تحت عنوان «دلالة العلم في قوله ولما يعلم الله»","url":""}]},{"id":"s9-112","number":112,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا اختيرت ﴿لما﴾ بدل «لم»؟","answer":"﴿لما﴾ تنفي وقوع العلم المتعلق بظهور العمل إلى زمن الكلام مع توقع وقوعه بعد الاختبار، بخلاف ﴿لم﴾ التي لا تتضمن هذا التوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص732–733، تحت «دلالة التعبير بحرف الجزم ولما»","url":""}]},{"id":"s9-113","number":113,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا جمع بين الجهاد وعدم اتخاذ الوليجة؟","answer":"الجهاد يختبر العمل الظاهر، وترك الوليجة يختبر الولاء الباطن؛ فجمعهما لاستكمال صدق المؤمن في فعله وسره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص734، تحت عنوان «فائدة مجيء صلتين للاسم الموصول»","url":""}]},{"id":"s9-114","number":114,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما الصورة في قوله: ﴿ولم يتخذوا... وليجة﴾؟","answer":"الوليجة من الولوج والدخول؛ فصُوّر الخليل الذي يدخل في أسرار القوم ويستبطن شؤونهم كمن يدخل مكانًا مستورًا. والمراد هنا نفي اتخاذ بطانة من خارج جماعة الإيمان يُطلعها المرء على خفايا المسلمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص738، تحت عنوان «بلاغة الاستعارة في لفظ وليجة»","url":""}]},{"id":"s9-115","number":115,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما دلالة ترتيب الله ثم رسوله ثم المؤمنين في الآية؟","answer":"يراعي الترتيب جلال الله أولًا، ثم مقام رسوله، ثم شرف المؤمنين بانتسابهم إلى الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص736، تحت عنوان «دلالة الترتيب بين لفظ الجلالة وما بعده من معطوفات»","url":""}]},{"id":"s9-705","number":705,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا تكررت ﴿لا﴾ في قوله: ﴿ولا رسوله ولا المؤمنين﴾؟","answer":"يؤكد التكرار النفي ويجعل كل جهة مستقلة بالحكم، فلا يصح ولاء يدعي صاحبه واحدة ويهدر الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص737، تحت عنوان «مناسبة تكرار ولا في الآية»","url":""}]},{"id":"s9-116","number":116,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما مناسبة ختم الآية بقوله: ﴿والله خبير بما تعملون﴾؟","answer":"المقام يختبر إخلاص الجهاد والولاء، وهما متصلان بباطن الإنسان وسره؛ فناسبه وصف ﴿خبير﴾ الدال على الإحاطة بالخفايا. وفي التذييل تنبيه إلى أن الله يعلم الأعمال ودوافعها، ويجازي عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص738، تحت عنوان «بلاغة التعبير بجملة التذييل»","url":""}]},{"id":"s9-117","number":117,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان للمشركين أن يعمروا مساجد الله﴾، دون أن يقال: «لا يعمر المشركون»؟","answer":"صيغة ﴿ما كان لهم أن﴾ تنفي استحقاقهم وصلاحيتهم للعمارة، لا مجرد وقوع الفعل؛ فالشرك يناقض عمارة مسجد بني لعبادة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص743، تحت عنوان «مناسبة التعبير بما كان»","url":""}]},{"id":"s9-118","number":118,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا نُفيت عمارة المشركين لمساجد الله مع قيامهم بالبناء والخدمة؟","answer":"النفي متوجه إلى صحة عمارتهم والاعتداد بها عند الله، لا إلى إنكار وقوع البناء والخدمة حسًا. فالعمارة تشمل البناء والعبادة، وقد نزل ما فعلوه منزلة العدم من جهة القبول بسبب شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص743، تحت عنوان «دلالة ما كان في الآية»","url":""}]},{"id":"s9-119","number":119,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا وصفهم بأنهم ﴿شاهدين على أنفسهم بالكفر﴾؟","answer":"إظهارهم آثار الشرك، كنصب الأوثان والعبادة لها، بمنزلة شهادة ظاهرة على كفرهم، وهي أدل من دعوى مجردة. ووقوع هذه الشهادة حالًا من عمارتهم يبرز التناقض بين شركهم وعمارة بيوت التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص748، تحت عنوان «نكتة التعبير بلفظ شاهدين»","url":""}]},{"id":"s9-120","number":120,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾ مع وجود أعمال نافعة ظاهرًا؟","answer":"حبطت أعمالهم أي بطل ثوابها وآثارها الأخروية بسبب الكفر، وإن ظهر لبعضها نفع دنيوي؛ فالعمل لا يقبل دون أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص749، تحت عنوان «سبب إيثار صيغة الجمع في قوله أعمالهم»","url":""}]},{"id":"s9-121","number":121,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا انتقل من حبوط الأعمال إلى الخلود في النار؟","answer":"الحبوط يبين بطلان ما ظنوه رصيدًا من الأعمال، والخلود يبين العاقبة المقابلة؛ فلا ثواب لهم بل إقامة دائمة في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص750، تحت عنوان «دلالة الواو في الآية»","url":""}]},{"id":"s9-122","number":122,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"لماذا قصر عمارة المساجد بقوله: ﴿إنما يعمر مساجد الله من آمن بالله﴾؟","answer":"القصر يرد دعوى المشركين في استحقاق العمارة، ويثبتها لمن جمع الإيمان والعبادة والخشية؛ فليست العمارة مجرد خدمة مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص753، تحت عنوان «دلالة القصر بأداة الحصر إنما»","url":""}]},{"id":"s9-123","number":123,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"لماذا جمع في عُمّار المساجد بين الإيمان والصلاة والزكاة والخشية؟","answer":"الإيمان أصل صحة العمل، والصلاة عمارة المسجد بالعبادة، والزكاة برهان البذل، والخشية تحفظ الإخلاص؛ فاجتمعت أصول الاعتقاد والعمل الباطن والظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص755، تحت عنوان «سبب عدم ذكر الإيمان بالرسول في الآية»","url":""}]},{"id":"s9-124","number":124,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يخش إلا الله﴾ مع أن الخوف الطبيعي من الناس واقع؟","answer":"المنفي خشية العبادة والطاعة التي تحمل على مخالفة الله، لا الخوف الجبلي من ضرر محسوس؛ فالقصر متعلق بخشية التعظيم والانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص759، تحت عنوان «دلالة الحصر»","url":""}]},{"id":"s9-125","number":125,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿فعسى أولئك أن يكونوا من المهتدين﴾ مع تحقق صفاتهم؟","answer":"من توجيهات ﴿عسى﴾ هنا أنها وعد من الله، وصيغت بصيغة الرجاء لئلا يغتر المؤمن بعمله ويتكل عليه. وفيها أيضًا قطع لطمع المشركين في الاهتداء مع فقد هذه الصفات، وحث للمؤمن على رجاء الهداية والأخذ بأسبابها دون الجزم لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص760–761، تحت «دلالة عسى»","url":""}]},{"id":"s9-126","number":126,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"ما غرض الاستفهام في قوله: ﴿أجعلتم سقاية الحاج...﴾؟","answer":"ينكر الاستفهام التسوية ويوبخ عليها؛ فلا يستوي عمل ظاهر مع الإيمان بالله والجهاد في سبيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص767، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s9-706","number":706,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"إلى من وُجه الخطاب في قوله: ﴿أجعلتم سقاية الحاج﴾؟","answer":"إن وُجه إلى المشركين أبطل مساواة الخدمة مع الشرك بالإيمان والجهاد، وإن وُجه إلى مؤمنين افتخروا بها بيّن أنها لا تبلغ منزلتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص767، تحت عنوان «دلالة الخطاب بين الالتفات أو الدلالة على مقتضى الظاهر»","url":""}]},{"id":"s9-127","number":127,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا قورنت أعمال مادية بأشخاص مؤمنين، لا بأعمالهم؟","answer":"من توجيهات التعبير تقدير مضاف: أجعلتم أهل السقاية والعمارة كمن آمن، أو تقدير عمل في الطرف الآخر: كإيمان من آمن. ووجه آخر أنه احتباك، حُذف صاحب العمل من جانب والعمل من الآخر لدلالة المذكور عليهما؛ فالمقارنة مفهومة دون تطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص768–769، تحت «براعة التشبيه»","url":""}]},{"id":"s9-128","number":128,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا ذُكر الإيمان بالله واليوم الآخر مع الجهاد في الطرف المقابل للسقاية والعمارة؟","answer":"تذكر الصلة صفات العاملين، لتبين أن مناط تميزهم هو الإيمان والجهاد في سبيل الله، لا صورة العمل وحدها. وفي جمعها تعظيم لهذه الأوصاف وحث عليها، وبيان منزلة الجهاد بالقياس إلى الأعمال المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص770، تحت عنوان «مناسبة ذكر الجهاد لرد العدوان دون غيره من الأعمال»","url":""}]},{"id":"s9-129","number":129,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا قُيد نفي الاستواء بقوله: ﴿عند الله﴾؟","answer":"ليبين أن الميزان المعتبر هو حكم الله وجزاؤه، لا ما يعتقده الناس من المفاخرة والتسوية. فعدم الاستواء ثابت في ميزانه سبحانه، ولو زعموا لأنفسهم منزلة مساوية أو أفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص771، تحت «فائدة تقييد لا يستوون بقوله عند الله»","url":""}]},{"id":"s9-130","number":130,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"من سوّى بين الشرك والإيمان ووضع العمل في غير منزلته فقد ظلم، وعدم هدايته جزاء إصراره ويؤكد بطلان هذه التسوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص772، تحت عنوان «دلالة نفي الهداية على عدم وصولهم إلى المطلوب»","url":""}]},{"id":"s9-131","number":131,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"لماذا أعاد ذكر الإيمان والجهاد وأضاف الهجرة بعد نفي المساواة في الآية السابقة؟","answer":"الآية السابقة نفت المساواة، ثم جاء التصريح بالطرف الراجح وبيان صفاته ودرجته. فذُكرت الهجرة مع الإيمان والجهاد لاستيفاء صفات هؤلاء المؤمنين والثناء عليهم، والانتقال من المقارنة إلى تقرير فضلهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص774، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-132","number":132,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس؟","answer":"من وجوه التقديم أن بذل المال أخف من بذل النفس، فترقى من الأدنى إلى الأعلى. والمال أيضًا قوام الإنفاق والتجهيز للجهاد، وقد يحتاج إليه المجاهد حتى يصل إلى ميدان القتال؛ فقدم ما هو من أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص779–780، تحت «مناسبة تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-133","number":133,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿أعظم درجة عند الله﴾ ولم يذكر الطرف الآخر؟","answer":"من توجيهاته أن المقصود بيان علو منزلة هؤلاء المؤمنين على الإطلاق، لا تخصيص فضلهم بالمقارنة بأهل السقاية والعمارة وحدهم. وعلى حمل المقارنة على المشركين، فليس لهم عند الله درجة معتبرة أصلًا؛ فجاء التعبير ردًا لما توهموه لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص781، تحت «سبب عدم ذكر الطرف المرجوح في آية أعظمية الدرجة»","url":""}]},{"id":"s9-134","number":134,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما دلالة تنكير ﴿درجة﴾ في قوله: ﴿أعظم درجة عند الله﴾؟","answer":"التنكير للتعظيم والتفخيم؛ فيبرز علو منزلتهم ورفعة مقامهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص780، تحت «دلالة تنكير درجة»","url":""}]},{"id":"s9-135","number":135,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"لماذا جاء القصر: ﴿وأولئك هم الفائزون﴾؟","answer":"اسم الإشارة وضمير الفصل يقصران الفوز الحقيقي عليهم؛ لأنهم جمعوا الإيمان والهجرة والجهاد، لا أصحاب المفاخر الظاهرة الخالية من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص782، تحت عنوان «بلاغة الحصر»","url":""}]},{"id":"s9-137","number":137,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يبشرهم ربهم﴾، فاختار اسم الرب؟","answer":"اختير ﴿ربهم﴾ لاستحضار الرعاية والتربية والإنعام؛ فهو الذي تولى أمرهم حتى بلغهم منازل البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص790، تحت عنوان «دلالة الإضافة في لفظ ربهم»","url":""}]},{"id":"s9-138","number":138,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"لماذا بدأت البشارة برحمة من الله؟","answer":"لأن الرحمة أصل ما يتلقاه المؤمنون من الإنعام، ومنها رضوان الله وجزاء الجنات الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «إيثار التعبير بلفظ رحمة ومناسبته للسياق»","url":""}]},{"id":"s9-707","number":707,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سر ترتيب الرحمة ثم الرضوان ثم الجنات؟","answer":"بدأ بالرحمة العامة، ثم بالرضوان الذي يخصهم بالقبول، ثم فصل الجزاء المحسوس في الجنات؛ فشمل أسباب النعيم وصوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص792، تحت عنوان «سر تقديم الرحمة على الرضوان»","url":""}]},{"id":"s9-139","number":139,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿برحمة منه﴾ مع أن كل رحمة منه؟","answer":"﴿منه﴾ تؤكد أن الرحمة عطاء خاص صادر من عنده لا سبب مستقل عنه، وفيها تعظيم لقرب المنحة وشرف مصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «سر تنكير لفظ رحمة»","url":""}]},{"id":"s9-140","number":140,"surah":9,"verses":[21,72],"references":[{"surah":9,"verses":[21,72]}],"verseLabel":"التوبة: 21؛ التوبة: 72","question":"ما سر تنكير ﴿رحمة﴾ في قوله: ﴿يبشرهم ربهم برحمة منه﴾؟","answer":"يفيد التنكير التعظيم والتفخيم: فهي رحمة عظيمة صادرة من ربهم لا يحيط الوصف بقدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «سر تنكير لفظ رحمة»","url":""}]},{"id":"s9-708","number":708,"surah":9,"verses":[21,72],"references":[{"surah":9,"verses":[21,72]}],"verseLabel":"التوبة: 21؛ التوبة: 72","question":"ما نكتة تنكير ﴿رضوان﴾؟","answer":"يشير التنكير إلى عظم رضوان الله وتنوع آثاره، ثم يبين السياق أنه أكبر من النعيم المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «نكتة تنكير رضوان»","url":""}]},{"id":"s9-141","number":141,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"لماذا وصف النعيم بأنه ﴿مقيم﴾؟","answer":"وُصف النعيم بالمقيم لأنه ثابت لا يزول ولا ينتقل عن صاحبه، خلاف نعيم الدنيا العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص794، تحت عنوان «دلالة وصف النعيم بكونه مقيمًا»","url":""}]},{"id":"s9-143","number":143,"surah":9,"verses":[22],"references":[{"surah":9,"verses":[22]}],"verseLabel":"التوبة: 22","question":"لماذا فُصل قوله: ﴿إن الله عنده أجر عظيم﴾ عما قبله؟","answer":"جاءت الجملة استئنافًا يعلل البشارة السابقة ويقرر أن ما عند الله هو الجزاء الجدير بطلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص797، تحت عنوان «علة فصل قوله إن الله عنده أجر عظيم عما قبله»","url":""}]},{"id":"s9-709","number":709,"surah":9,"verses":[22],"references":[{"surah":9,"verses":[22]}],"verseLabel":"التوبة: 22","question":"لماذا وُصف الأجر بأنه عظيم؟","answer":"لأنه يجمع رحمة الله ورضوانه والجنة، وهو عظيم في قدره ودائم لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص798، تحت عنوان «سر وصف الأجر بالعظمة»","url":""}]},{"id":"s9-144","number":144,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا خُص الآباء والإخوان بالنهي عن اتخاذهم أولياء إذا استحبوا الكفر؟","answer":"لأنهما من أقرب القرابات وأقواها أثرًا في النصرة والمشورة، فإذا نُهي عن موالاتهما على هذه الحال كان من دونهما أولى. ويذكر المصدر أن الأبناء والأزواج يتبعون المخاطبين في هذا المقام، بخلاف الآباء والإخوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص14–15، تحت «نكتة تخصيص الآباء والإخوان بالذكر»","url":""}]},{"id":"s9-145","number":145,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿استحبوا الكفر على الإيمان﴾، دون أن يقال: «اختاروا الكفر»؟","answer":"تدل الصيغة على إيثار الكفر على الإيمان وطلب محبته. ومن نكتها أن الإيمان محبوب بظهور محاسنه وأدلته، فترجيح الكفر عليه يصور انحراف الاختيار وشدة تعلقهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص16، تحت «دلالة السين والتاء في استحبوا»","url":""}]},{"id":"s9-146","number":146,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا عُدي ﴿استحبوا﴾ بـ﴿على﴾؟","answer":"عدي بـ﴿على﴾ لتضمين الاستحباب معنى الإيثار والتفضيل؛ أي قدموا الكفر ورفعوه فوق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص16–17، تحت «دلالة التضمين»","url":""}]},{"id":"s9-147","number":147,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا أُفرد الضمير في ﴿يتولهم﴾ ثم جُمع الجزاء في ﴿فأولئك﴾؟","answer":"رُوعي لفظ ﴿من﴾ في إفراد الضمير في ﴿يتولهم﴾، ثم رُوعي عموم معناها في جمع الجزاء؛ ليشمل الحكم كل من وقع منه التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص17، تحت «نكتة إفراد الضمير في يتولهم»","url":""}]},{"id":"s9-710","number":710,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما وجه القصر في قوله تعالى: ﴿فأولئك هم الظالمون﴾؟","answer":"يفيد ضمير الفصل مع تعريف الخبر المبالغة في إثبات الظلم لهم وتهويل شناعة موالاتهم لأعداء الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص19، تحت «بلاغة القصر»","url":""}]},{"id":"s9-148","number":148,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما دلالة التعريف في لفظ ﴿الظالمون﴾؟","answer":"يفيد التعريف المبالغة في شناعة ظلمهم، مع تعميم الوعيد على من يضع الولاية في غير موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص19، تحت «دلالة أل في لفظ الظالمون»","url":""}]},{"id":"s9-711","number":711,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما وجه براعة التذييل في قوله تعالى: ﴿فأولئك هم الظالمون﴾؟","answer":"جاء التذييل حكمًا جامعًا يقرر أن موالاة أعداء الإيمان وضع للولاية في غير موضعها، ولذلك سُمّيت ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص20، تحت «براعة التذييل»","url":""}]},{"id":"s9-149","number":149,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا عدّد الآباء والأبناء والإخوان والأزواج والعشيرة والأموال والتجارة والمساكن؟","answer":"عُددت لتستوعب أهم محبوبات الإنسان: أصوله وفروعه وإخوته وأزواجه وعشيرته وماله وكسبه ومسكنه، فلا يبقى محبوب يتذرع به لتقديمه على أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص27، تحت «بلاغة مراعاة النظير»","url":""}]},{"id":"s9-150","number":150,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا انتقل من القرابات إلى الأموال ثم التجارة ثم المساكن؟","answer":"انتقل من الروابط البشرية إلى المال المملوك، ثم إلى نمائه المتوقع في التجارة، ثم إلى محل الاستقرار؛ فتدرج في دوائر التعلق من الأشخاص إلى أسباب العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29–30، تحت «براعة الترتيب والترقي في المعاني»","url":""}]},{"id":"s9-151","number":151,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا وصف الأموال بـ﴿اقترفتموها﴾؟","answer":"الاقتراف هو الاكتساب، ووصف الأموال به يبرز تعلق النفس بما حصّلته بسعيها وجهدها. فإذا لم يجز تقديم هذا المال العزيز عليها على محبة الله ورسوله، كان غيره من الأموال أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص28، تحت «دلالة وصف الأموال بالاقتراف»","url":""}]},{"id":"s9-152","number":152,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا وُصفت التجارة بقوله: ﴿تخشون كسادها﴾؟","answer":"لأن التجارة متعلقة بتقلبات السوق بين الرواج والكساد؛ فذكر خشية كسادها يصور موطن التعلق والقلق لدى أصحابها. والسياق ينبه إلى ألا يحملهم هذا الخوف على تقديمها على طاعة الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29، تحت «دلالة الأوصاف للأموال والتجارة والمساكن»","url":""}]},{"id":"s9-153","number":153,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما مناسبة وصف المساكن بقوله: ﴿ترضونها﴾؟","answer":"لأن المسكن تتحقق به غاية الاطمئنان والاستقرار، فيرضى به صاحبه إذا لبى حاجته. وذكر هذا الرضا يستحضر قوة تعلقه به، لينبه إلى ألا يشغله عن الطاعة ومقتضى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29، تحت «دلالة الأوصاف للأموال والتجارة والمساكن»","url":""}]},{"id":"s9-154","number":154,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما سرّ ذكر النفير مع محبة الله ورسوله؟","answer":"من توجيهات الآية أن المحبة تظهر في امتثال أمر الله ورسوله، فخُص الجهاد بالذكر تعظيمًا لشأنه وبيانًا لما فيه من بذل المال والنفس. وعلى إبقاء المحبة على ظاهرها، يكون الجهاد من ثمراتها ودلائل صدقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص32، تحت «سر ذكر النفير مع محبة الله ورسوله»","url":""}]},{"id":"s9-155","number":155,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿فتربصوا حتى يأتي الله بأمره﴾، ولم يصرح بالعقوبة؟","answer":"﴿فتربصوا﴾ تهديد يترك العقوبة مبهمة، فيذهب الوهم في صورها ويزيد هول انتظار أمر الله الذي لا يرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص33، تحت «دلالة الأمر في قوله فتربصوا»","url":""}]},{"id":"s9-156","number":156,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا ختم بـ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"تقديم المحبوبات على الله ورسوله والجهاد خروج عن مقتضى الطاعة، فناسب وصف الفسق، وعدم الهداية نتيجة الإصرار عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص35، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-157","number":157,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد نصركم الله في مواطن كثيرة﴾ قبل ذكر هزيمة أول المعركة في حنين؟","answer":"قُدمت المواطن الكثيرة لتذكيرهم بأن النصر عادة فضل من الله لا ثمرة العدد، ثم ذكرت عثرة حنين لتصحح لحظة الاغترار بالكثرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص36، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-158","number":158,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما وجه التنويع بين ذكر المكان في ﴿مواطن كثيرة﴾ والزمان في ﴿يوم حنين﴾؟","answer":"ذُكر المكان أولًا والزمان ثانيًا، وكل منهما يدل على الآخر؛ فالمواطن تستلزم أيام القتال، ويوم حنين يستحضر موطنه. وفي هذا التنويع إيجاز، وإيماء إلى ما وقع في ذلك اليوم من هزيمة في أول الأمر ثم نصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص40، تحت «براعة تلوين الكلام»","url":""}]},{"id":"s9-159","number":159,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا خُص يوم حنين بالذكر بعد إجمال المواطن الكثيرة؟","answer":"خُص حنين لأن بدايته كشفت عجز الكثرة حين أعجبتهم، ثم أظهر نهايته عودة النصر بإنزال السكينة؛ فهو شاهد عملي على المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص40–41، تحت «سر عطف الخاص على العام»","url":""}]},{"id":"s9-160","number":160,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا أُضيف الإعجاب بالكثرة إلى الجماعة كلها؟","answer":"أُضيف الإعجاب إلى الجماعة مع صدوره من بعضهم تعظيمًا لشأنهم، وتنبيهًا إلى أن مثل هذا الاغترار لا ينبغي أن يصدر منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص41، تحت «نكتة إضافة الإعجاب إلى الجميع»","url":""}]},{"id":"s9-712","number":712,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما دلالة موقع قوله تعالى: ﴿إذ أعجبتكم كثرتكم﴾؟","answer":"يحدد الظرف لحظة الخطأ في الاغترار بالقوة العددية ونسيان عون الله، فيجعلها موضع العبرة من قصة حنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص41، تحت «دلالة موقع قوله إذ أعجبتكم كثرتكم»","url":""}]},{"id":"s9-161","number":161,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿فلم تغن عنكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم أقل إغناء؛ فلم تدفع الكثرة عنهم ضررًا ولا حققت نصرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص42، تحت «دلالة تنكير لفظ شيئًا»","url":""}]},{"id":"s9-162","number":162,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما الصورة في قوله: ﴿وضاقت عليكم الأرض بما رحبت﴾؟","answer":"صوّر شدة الحيرة والخوف بأن الأرض الواسعة ضاقت بهم فلم يجدوا مهربًا؛ فجمع بين حقيقة سعتها وشعورهم بانغلاقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص43، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s9-163","number":163,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا جمع بين ﴿وليتم﴾ و﴿مدبرين﴾؟","answer":"﴿وليتم﴾ يثبت فعل الانصراف، و﴿مدبرين﴾ يصور هيئتهم وهم يعطون العدو أدبارهم؛ فالثاني يؤكد الأول ويجسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص44، تحت «سر التعبير بالإدبار بعد ذكر التولي»","url":""}]},{"id":"s9-164","number":164,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة إسناد إنزال السكينة إلى اسم الله صراحة؟","answer":"يبين إسناد إنزال السكينة إلى الله أنها عطية منه، خارجة عما يستقل به تدبير الناس وأسبابهم الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص47، تحت «دلالة تعريف المسند إليه بالعلمية»","url":""}]},{"id":"s9-713","number":713,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة إضافة السكينة إلى الله في قوله تعالى: ﴿سكينته﴾؟","answer":"تشرف الإضافة السكينة وتعظم شأنها، وتبين أنها طمأنينة خاصة يهبها الله لتثبيت القلوب في الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص48، تحت «دلالة الإضافة في سكينته»","url":""}]},{"id":"s9-165","number":165,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"لماذا قيل: ﴿على رسوله وعلى المؤمنين﴾ ولم يقل: «عليكم»؟","answer":"لأن الجماعة المخاطبة قد خالطها منافقون؛ فعدل عن الضمير إلى الاسمين الظاهرين حتى لا يدخل في الثناء كل من شمله الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص48، تحت «بلاغة الإظهار في محل الإضمار»","url":""}]},{"id":"s9-714","number":714,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما نكتة ذكر الرسول صراحة عند إنزال السكينة؟","answer":"ذُكر الرسول تعظيمًا لمنزلته وزيادة في الامتنان بتثبيته بالسكينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص49، تحت «نكتة ذكر الرسول»","url":""}]},{"id":"s9-715","number":715,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة وصف من نزلت عليهم السكينة بالمؤمنين؟","answer":"في وصفهم بالإيمان تنويه بما يقتضيه الإيمان من الثبات وقبول الطمأنينة، وتمييز لهم ممن خالط الصف من المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص50، تحت «دلالة التعبير بوصف الإيمان»","url":""}]},{"id":"s9-166","number":166,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة تنكير ﴿جنودًا﴾ وجمعها؟","answer":"يفيد تنكير الجنود وجمعها تعظيم شأنها وتكثيرها، ويوسع ما يدخل في جنود الله من أسباب النصر الغيبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص51، تحت «دلالة تنكير جنودًا وجمعها»","url":""}]},{"id":"s9-716","number":716,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة تقييد الجنود بقوله تعالى: ﴿لم تروها﴾؟","answer":"يبرز القيد أن النصر جاء بمدد غيبي لم تقع عليه أبصار المؤمنين، فالمقصود أثر القوة التي أيدهم الله بها لا مجرد تسميتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص51، تحت «دلالة جملة لم تروها»","url":""}]},{"id":"s9-167","number":167,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما مناسبة الجمع بين إنزال السكينة وإنزال الجنود؟","answer":"السكينة مدد للقلوب من الداخل، والجنود مدد للموقف من الخارج؛ فجمع تثبيت النفس وتقوية الصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص45، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-168","number":168,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما سرّ التعبير بقوله تعالى: ﴿وعذب الذين كفروا﴾؟","answer":"تجعل صلة الكفر علة ظاهرة لاستحقاق العذاب، وتبين أن النصر لم يكن نجاة للمؤمنين فقط، بل جزاءً للعدو على كفره وعدوانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص52، تحت «سر التعبير بالاسم الموصول»","url":""}]},{"id":"s9-169","number":169,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما سرّ الإشارة إلى العذاب في قوله تعالى: ﴿وذلك جزاء الكافرين﴾؟","answer":"يربط اسم الإشارة الجزاء بالعذاب المتقدم، ويستحضره مشاهدًا مع تعظيم شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص53، تحت «سر تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s9-717","number":717,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما وجه التذييل في قوله تعالى: ﴿وذلك جزاء الكافرين﴾؟","answer":"يقرر التذييل أن العذاب جزاء جنس الكافرين، لا حادثة عارضة بلا حكم أو علة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص53، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-170","number":170,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا جاء بعد عذاب الكافرين مباشرة: ﴿ثم يتوب الله من بعد ذلك على من يشاء﴾؟","answer":"جاءت التوبة بعد العذاب لتبين أن الجزاء الدنيوي لا يغلق باب الهداية، وأن من بقي منهم قد يرجع فيقبله الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص55، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-171","number":171,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا استُعملت ﴿ثم﴾ قبل التوبة؟","answer":"﴿ثم﴾ تفيد تراخي رتبة التوبة عن مشهد القتال والعذاب وانتقال السياق إلى طور جديد، وقد يقع أثر الهداية بعد انكشاف الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص56، تحت «دلالة ثم في الآية»","url":""}]},{"id":"s9-172","number":172,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من بعد ذلك﴾؟","answer":"تؤكد ﴿من﴾ ابتداء إمكان التوبة بعد تلك الأحداث الشديدة، فلا يغلق العذاب الدنيوي باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص58، تحت «دلالة من في الآية»","url":""}]},{"id":"s9-718","number":718,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما نكتة التعبير باسم الإشارة ﴿ذلك﴾ عن العذاب؟","answer":"يستحضر اسم الإشارة العذاب المتقدم كاملًا قبل فتح باب التوبة بعده، فيبرز سعة الرحمة مع شدة ما سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص59، تحت «نكتة التعبير باسم الإشارة ذلك عن العذاب»","url":""}]},{"id":"s9-173","number":173,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا ختم بـ﴿والله غفور رحيم﴾؟","answer":"﴿غفور﴾ يمحو ما سبق من الكفر والعداء، و﴿رحيم﴾ يتفضل على التائب بعد المغفرة؛ فناسبا فتح الباب بعد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص62، تحت «دلالة ختم الآية باسمي غفور رحيم»","url":""}]},{"id":"s9-719","number":719,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما الفرق بين المغفرة والرحمة في ختام الآية؟","answer":"المغفرة تمحو ما سبق من الكفر والعداء، والرحمة تتفضل على التائب بعد محو ذنبه؛ فاجتمع رفع الضرر وإيصال الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص62، تحت «الفروق المعجمية: المغفرة والرحمة»","url":""}]},{"id":"s9-174","number":174,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا وصف المشركين بأنهم ﴿نجس﴾ بالمصدر المفرد، لا «أنجاس»؟","answer":"أخبر بالمصدر المفرد ﴿نجس﴾ للمبالغة، كأن حقيقتهم عين النجاسة المعنوية، والمصدر لا يثنى ولا يجمع فاستوى فيه الجمع والمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص72، تحت «دلالة التعبير بالمصدر نجس بصيغة المفرد»","url":""}]},{"id":"s9-175","number":175,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا رُتّب منعهم من المسجد الحرام على وصف النجاسة بالفاء؟","answer":"الفاء تفيد أن منعهم مترتب على وصف الشرك والنجاسة المعنوية، فالحكم ليس لمجرد جنس أو قومية بل لعلة مذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص74–75، تحت «دلالة الفاء في قوله فلا يقربوا»","url":""}]},{"id":"s9-176","number":176,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يقربوا المسجد الحرام﴾، دون أن يقال: «فلا يدخلوه»؟","answer":"النهي عن القرب أبلغ، ويوافق سياق منعهم من الحج والعمرة. فبعض المناسك يقع خارج بناء المسجد، كالوقوف بعرفة؛ ولذلك يتسع التعبير بالمقاربة لما لا يؤديه الاقتصار على دخول البناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص74، تحت «سر التعبير بلفظ فلا يقربوا دون فلا يدخلوا»","url":""}]},{"id":"s9-177","number":177,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما دلالة إضافة العام إلى المشركين في قوله تعالى: ﴿بعد عامهم هذا﴾؟","answer":"تستحضر الإضافة اختصاص ذلك العام بهم بوصفه آخر عهدهم بالمشاركة في موسم الحج، مع استمرار المنع بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص78، تحت «دلالة إضافة لفظ عام إلى الضمير العائد على المشركين»","url":""}]},{"id":"s9-178","number":178,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا واجه خوف الفقر صراحة: ﴿وإن خفتم عيلة﴾؟","answer":"صرح بالخوف لأنه كان شبهة واقعية: انقطاع تجارة المشركين قد يسبب الفقر؛ فواجهها الوحي بوعد يحرر الطاعة من ضغط المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص79، تحت «سر التعبير بالخوف»","url":""}]},{"id":"s9-179","number":179,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا جاء الوعد بالإغناء بلفظ ﴿فسوف يغنيكم الله﴾؟","answer":"تربط الفاء الجواب بالشرط، وتؤكد ﴿سوف﴾ حصول الإغناء في المستقبل. وفي اختيارها مناسبة لما يتحقق من أسبابه مع الزمن، فيطمئن المؤمن إلى الوعد دون اشتراط وقوعه في اللحظة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص80، تحت «سر اقتران الجواب بلفظة فسوف»","url":""}]},{"id":"s9-180","number":180,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا قيد الإغناء بقوله: ﴿إن شاء﴾؟","answer":"قُيد بالمشيئة لتبقى القلوب معلقة بالله لا بالوعد المادي وحده، ولأن كيفية الغنى وزمانه ومقداره تابعة لحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص84، تحت «نكتة تعليق الإغناء بالمشيئة»","url":""}]},{"id":"s9-181","number":181,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما مناسبة ختم وعد الإغناء بقوله: ﴿إن الله عليم حكيم﴾؟","answer":"يثبت الختام سعة علم الله بأحوال عباده ومصالحهم، وحكمته في تدبير أرزاقهم ووضع الأمور مواضعها. وفيه تقوية لليقين بوعد الإغناء بعد انقطاع بعض أسبابه الظاهرة، وإزالة لما قد يعرض في القلوب من تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص86، تحت «براعة التذييل»","url":""}]},{"id":"s9-182","number":182,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا عُبر بالموصول ثم فُصّلت صلته في أوصاف المقاتَلين؟","answer":"فصل الأوصاف لإظهار تعدد أصول مخالفتهم التي تبرر الحكم: خلل الاعتقاد بالبدء والمعاد، وخلل التشريع، وخلل الانقياد لدين الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص91، تحت «نكتة التعبير بالموصول وصلته»","url":""}]},{"id":"s9-183","number":183,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما دلالة إضافة الرسول إلى الله في قوله تعالى: ﴿ما حرم الله ورسوله﴾؟","answer":"تفيد الإضافة تشريف الرسول وتأكيد صدقه في التبليغ، وتقرر أن ما يحرمه مأذون فيه من الله، فتكون طاعته من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص98، تحت «دلالة الإضافة»","url":""}]},{"id":"s9-184","number":184,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿ولا يدينون﴾؟","answer":"الدين هنا بمعنى الانقياد والطاعة؛ فالتعبير يكشف أنهم لا يخضعون للمنهج الحق اعتقادًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص99، تحت «سر التعبير بقوله لا يدينون»","url":""}]},{"id":"s9-720","number":720,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما نكتة إضافة الدين إلى الحق في قوله تعالى: ﴿دين الحق﴾؟","answer":"تصف الإضافة المنهج بأنه الحق الثابت الذي يجب أن يخضع له الإنسان، فلا يكون المراد مجرد اسم طائفة أو شعار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص100، تحت «نكتة إضافة الدين إلى الحق»","url":""}]},{"id":"s9-186","number":186,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا عبّر عن أداء الجزية بـ﴿يعطوا﴾ دون «يؤتوا»؟","answer":"يبين المصدر أن الإعطاء قد يكون عن طيب نفس وقد يكون عن غير رضا، فناسب وصف أداء الجزية في هذا السياق. أما الإيتاء فيستعمل في المقامات التي يكون فيها المعطى ذا شأن وتظهر معه دلالة العطاء عن رغبة، كالزكاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص103، تحت «سر التعبير بلفظ الإعطاء دون الإيتاء»","url":""}]},{"id":"s9-187","number":187,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما وجه المجاز المرسل في قوله تعالى: ﴿عن يد﴾؟","answer":"من توجيهاته أن اليد مجاز عن القوة، أي يؤدون الجزية عن انقياد للسلطان، أو عن النعمة بما يترتب على قبولها من حقن الدماء والحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص104، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s9-721","number":721,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما وجه الكناية في قوله تعالى: ﴿عن يد﴾؟","answer":"كُنّي باليد عن مباشرة الأداء بأنفسهم وما يصاحبها من الانقياد، بدل الاكتفاء بذكر دفع الجزية مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص104، تحت «بلاغة الكناية في قوله عن يد»","url":""}]},{"id":"s9-188","number":188,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا ختم بـ﴿وهم صاغرون﴾؟","answer":"﴿وهم صاغرون﴾ تبين خضوعهم لحكم الدولة وامتناعهم عن محاربتها، فلا تكون الجزية مالًا بلا اعتراف بسلطان النظام العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص105، تحت «دلالة إيراد جملة الحال اسمية»","url":""}]},{"id":"s9-189","number":189,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا عبّر عن قول طائفة من اليهود بصيغة الجنس: ﴿وقالت اليهود عزير ابن الله﴾؟","answer":"يذكر المصدر وجهين: أن يكون الإسناد إلى الجماعة والمراد القائلون منهم، من إطلاق العام وإرادة بعض أفراده؛ أو أن القائل بعضهم والباقين لم ينكروا مقالته فجرى الإسناد عليهم. فالعبارة لا تقتضي أن كل فرد قالها بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص110، تحت «دلالة إسناد القول إلى عموم اليهود»","url":""}]},{"id":"s9-190","number":190,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما دلالة الواو في قوله تعالى: ﴿وقالت اليهود﴾؟","answer":"تجمع الواو قول اليهود في عزير وقول النصارى في المسيح؛ لأنهما يشتركان في رفع بشر إلى البنوة الإلهية مع اختلاف الشخص والطائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص109، تحت «دلالة الواو في قوله وقالت اليهود»","url":""}]},{"id":"s9-191","number":191,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك قولهم بأفواههم﴾ مع أن كل قول يكون بالفم؟","answer":"﴿بأفواههم﴾ يقرر أنه قول لا يقوم عليه برهان ولا حقيقة وراء الألفاظ، ويشعر بأنه مجرد جرأة لسانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص114، تحت «دلالة التعبير بالأفواه»","url":""}]},{"id":"s9-192","number":192,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿يضاهئون قول الذين كفروا من قبل﴾؟","answer":"المضاهاة المشابهة؛ فقولهم يحاكي مقالات من سبقهم في نسبة الولد إلى الله أو إشراك غيره في العبادة. وفيه بيان أنهم اتبعوا أقوالًا موروثة من الضلال، وتركوا ما جاء به الهدى من توحيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص115، تحت «سر التعبير بقوله يضاهئون قول الذين»","url":""}]},{"id":"s9-193","number":193,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا جاء الدعاء عليهم بصيغة الخبر: ﴿قاتلهم الله﴾؟","answer":"الجملة خبرية في صورتها، واستعملت للدعاء عليهم والتعجيب من شناعة مقالتهم. وصيغة المفاعلة للمبالغة في هذا الدعاء، فهي تقوي الذم والإنكار ولا يراد بها الإخبار عن قتال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص117–118، تحت «دلالة الخبر في قوله قاتلهم الله»","url":""}]},{"id":"s9-194","number":194,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أنى يؤفكون﴾؟","answer":"خرج الاستفهام للتعجب والإنكار من الجهة التي يصرفون إليها عن الحق مع وضوح بطلان قولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص118، تحت «دلالة الاستفهام»","url":""}]},{"id":"s9-722","number":722,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا قيل: ﴿يؤفكون﴾ دون «يصرفون»؟","answer":"يصور ﴿يؤفكون﴾ شدة انقلابهم عن الدليل وصرفهم عن الحق، فهو أبلغ من مجرد ذكر الصرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص118، تحت «سر التعبير بلفظ يؤفكون دون يصرفون»","url":""}]},{"id":"s9-195","number":195,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"كيف اتخذ أهل الكتاب أحبارهم ورهبانهم أربابًا مع أنهم لم يسجدوا لهم؟","answer":"اتخذوهم أربابًا بطاعتهم في تحليل الحرام وتحريم الحلال وتقديم أقوالهم على حكم الله، لا بالسجود لهم؛ فالربوبية هنا ربوبية تشريع وطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص126، تحت «سر التعبير بلفظ أربابًا»","url":""}]},{"id":"s9-196","number":196,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا جمع بين ﴿أحبارهم ورهبانهم﴾؟","answer":"الأحبار علماء اليهود، والرهبان عباد النصارى؛ فالجمع يستوعب القيادات الدينية العلمية والتعبدية التي مُنحت حق التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص124، تحت «بلاغة اللف والنشر»","url":""}]},{"id":"s9-197","number":197,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"ما وجه التعبير عن الأحبار والرهبان بلفظ ﴿أربابًا﴾؟","answer":"لأن أتباعهم منحوا أقوالهم سلطة التحليل والتحريم، وقدموها على ما أنزل الله؛ فشُبهت منزلتهم في هذا الاتباع بمنزلة الأرباب. والتعبير يصور غلو الأتباع في تعظيمهم وتسليمهم أمر الدين إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص126، تحت «سر التعبير بلفظ أربابًا»","url":""}]},{"id":"s9-198","number":198,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا عطف ﴿والمسيح ابن مريم﴾ على الأحبار والرهبان مع اختلاف طريقة اتخاذه ربًّا؟","answer":"عُطف المسيح لأنه اتخذ ربًا بالاعتقاد في ذاته وعبادته، بينما اتخذ الأحبار والرهبان أربابًا بالطاعة التشريعية؛ فجمع صورتي الانحراف مع اختلافهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص127، تحت «دلالة تخصيص عيسى بالذكر»","url":""}]},{"id":"s9-199","number":199,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا وصف المسيح بـ﴿ابن مريم﴾ في مقام إنكار ألوهيته؟","answer":"﴿ابن مريم﴾ يذكر بنسبه البشري وولادته من أم، فينقض دعوى الألوهية من داخل الوصف ويؤكد عبوديته وبشريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص127–128، تحت «دلالة نسبة عيسى إلى أمه»","url":""}]},{"id":"s9-200","number":200,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أمروا إلا ليعبدوا إلهًا واحدًا﴾؟","answer":"القصر بـ﴿ما... إلا﴾ يرد اتخاذ الأرباب المتعددة، ويقرر أن أصل الأمر المنزل عليهم عبادة معبود واحد لا شريك له؛ فناقض فعلهم حقيقة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص128، تحت «دلالة القصر»","url":""}]},{"id":"s9-201","number":201,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا ختم بـ﴿سبحانه عما يشركون﴾؟","answer":"التسبيح تنزيه لله عن الشركاء والبنوة وعن أن يشاركه بشر في حق التشريع والعبادة، فجاء خاتمة تبطل ما سبق من اتخاذ الأرباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص130، تحت «علة فصل قوله سبحانه عما قبله»","url":""}]},{"id":"s9-202","number":202,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"ما غرض استعارة النور للدين في قوله تعالى: ﴿نور الله﴾؟","answer":"شُبه الدين بالنور لما فيه من هداية وظهور وكشف لطريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص135، تحت «غرض الاستعارة التصريحية»","url":""}]},{"id":"s9-723","number":723,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"ما وجه براعة الاستعارة في تصوير إطفاء نور الله بالأفواه؟","answer":"شُبه طعنهم في الدين بالنفخ لإطفاء النور؛ فالصورة تسخر من ضعف وسيلتهم أمام نور الله الذي لا يطفأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص136، تحت «براعة الاستعارة في مجموع التركيب»","url":""}]},{"id":"s9-203","number":203,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا خص الأفواه وسيلةً لإطفاء النور؟","answer":"خُصت الأفواه لأن حربهم قائمة على الأقوال المفتراة والطعن والتكذيب، ولتصوير عجزها: أفواه تنفخ في نور لا تطفئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص137، تحت «دلالة تقييد الإطفاء بالأفواه»","url":""}]},{"id":"s9-204","number":204,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"كيف جاء الاستثناء في قوله: ﴿ويأبى الله إلا أن يتم نوره﴾ مع أن ظاهر الكلام مثبت؟","answer":"الإباء يتضمن معنى النفي والمنع؛ فالمعنى أن الله لا يرضى في هذا المقام إلا إتمام نوره. لذلك صح الاستثناء، وجاء الفعل ﴿يأبى﴾ أقوى من مجرد نفي الإرادة في تصوير الامتناع القاطع عما يريدونه من الإطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص138، تحت «براعة التعبير بالإباء دون نفي الإرادة»","url":""}]},{"id":"s9-205","number":205,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا اختير ﴿يتم نوره﴾ لا «يحفظ نوره»؟","answer":"الإتمام أبلغ من مجرد الإبقاء؛ لأنه يتضمن زيادة ظهور النور وانتشاره وعلو شأنه. والمراد هنا إظهار الدين وتأييده، لا أن نور الله كان ناقصًا في نفسه فاحتاج إلى استكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص140، تحت «دلالة التعبير بالإتمام دون الإبقاء»","url":""}]},{"id":"s9-206","number":206,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا ختم بـ﴿ولو كره الكافرون﴾؟","answer":"الخاتمة تقرر أن كراهة الكافرين لا تغير وعد الله ولا تمنع إتمام نوره، وفيها مقابلة بين إرادتهم العاجزة وإرادته النافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص143–144، تحت «دلالة الشرط بـ«لو» وأثرها في ربط الكلام؛ معنى الواو ودلالته»","url":""}]},{"id":"s9-207","number":207,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿هو الذي أرسل رسوله﴾ بعد ذكر محاولة إطفاء النور؟","answer":"بعد تصوير محاولة الإطفاء، بين أن صاحب النور هو الذي أرسل رسوله بالهدى؛ فالإرسال الإلهي ضمان بقاء الرسالة وظهورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص147، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-208","number":208,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"لماذا جمع بين ﴿الهدى ودين الحق﴾؟","answer":"الهدى ما جاء به الرسول من علم ودلالة، ودين الحق هو المنهج العملي والاعتقادي الثابت؛ فجمع نور المعرفة ونظام الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص151، تحت «معنى العطف»","url":""}]},{"id":"s9-209","number":209,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما دلالة التعريف والإفراد في قوله تعالى: ﴿الدين كله﴾؟","answer":"أُفرد الدين وعُرّف باعتبار جنس الملل كلها أو حقيقة الدين المخالف، فشمل كل ما عدا دين الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص155، تحت «دلالة أل في قوله الدين كله»","url":""}]},{"id":"s9-724","number":724,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما دلالة التوكيد بلفظ ﴿كله﴾؟","answer":"يؤكد لفظ ﴿كله﴾ استغراق كل ما عدا دين الحق في حكم الظهور والغلبة، فلا يترك بعض الجنس خارجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص155، تحت «دلالة التوكيد وأثره في المعنى»","url":""}]},{"id":"s9-210","number":210,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿ولو كره المشركون﴾، وقال في الآية السابقة: ﴿ولو كره الكافرون﴾؟","answer":"من وجوه المناسبة أن الكفر يتصل بمعنى الستر والإطفاء، فناسب محاولة إطفاء النور وإتمامه رغم معارضته. أما الشرك فذُكر عند إظهار دين التوحيد، مع استحضار من نازعوا الرسول في إعلانه؛ فجاء كل وصف ملائمًا لسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص157، تحت «علة ذكر المشركين واختصاص الآية السابقة بذكر الكافرين»","url":""}]},{"id":"s9-211","number":211,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما موقع نداء المؤمنين قبل التحذير من الأحبار والرهبان؟","answer":"ينقل النداء الكلام من كشف انحراف أهل الكتاب إلى تحذير المؤمنين منه، فيوقظهم قبل بيان استغلال القيادات الدينية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص160، تحت «موقع جملة النداء مما قبلها»","url":""}]},{"id":"s9-725","number":725,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما نكتة تخصيص المؤمنين بالخطاب؟","answer":"يستنهض وصف الإيمان مقتضى العقيدة في حماية الدين من الاستغلال، ويميز المخاطبين عن أصحاب الانحراف المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص162، تحت «نكتة تخصيص المؤمنين بالخطاب»","url":""}]},{"id":"s9-212","number":212,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كثيرًا من الأحبار والرهبان﴾ ولم يعمم؟","answer":"قال ﴿كثيرًا﴾ إنصافًا ومنعًا لتعميم الذم على الجميع؛ فالفساد وقع من عدد كبير لا من كل حبر وراهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص163–164، تحت «علة إسناد الحكم إلى كثير من الأحبار والرهبان دون جميعهم»","url":""}]},{"id":"s9-213","number":213,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا عبّر عن أخذ الأموال بالباطل بقوله: ﴿ليأكلون أموال الناس﴾؟","answer":"عُبر بالأكل عن الأخذ والاستيلاء والانتفاع؛ لأن الأكل من أبرز مقاصد المال، فهو مجاز مرسل على أحد التوجيهات. وفيه أيضًا تصوير لشدة حرصهم وابتلاعهم حقوق الناس، وذكر المصدر وجهًا تمثيليًا يشبه أخذهم الحرام بمن يأكل ما لا يميز نفعه من ضرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص165، تحت «بلاغة الإخبار عنهم بلفظ الأكل»","url":""}]},{"id":"s9-214","number":214,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا جمع بين أكل الأموال والصد عن سبيل الله؟","answer":"جمعا لأن فسادهم مزدوج: يستغلون الدين لتحصيل المال لأنفسهم، ثم يمنعون الناس من طريق الله حفاظًا على نفوذهم ومكاسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص169، تحت «دلالة عطف ويصدون على ما قبلها»","url":""}]},{"id":"s9-215","number":215,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا جمع الذهب والفضة ثم أعاد عليهما ضمير المفرد في ﴿ولا ينفقونها﴾؟","answer":"من توجيهاته أن الضمير يعود إلى الفضة لقربها، ويُفهم حكم الذهب معها؛ أو يعود إلى الأموال والكنوز أو أصناف الذهب والفضة المفهومة من السياق. وعدم تثنيته يدفع توهم أن الوعيد لا يقع إلا على من جمع كِلا النوعين وحبس حقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص173، تحت «مرجع الضمير في ولا ينفقونها وأثره في المعنى»","url":""}]},{"id":"s9-216","number":216,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا عُبر بـ﴿يكنزون﴾ دون «يجمعون»؟","answer":"الكنز جمع المال وضم بعضه إلى بعض مع إبقائه مدخرًا، فلفظه أدل على صورة الحبس من مطلق الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص171، تحت «وجه التعبير بيكنزون دون غيره»","url":""}]},{"id":"s9-726","number":726,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما دلالة قوله تعالى: ﴿ولا ينفقونها في سبيل الله﴾ على مفهوم المخالفة؟","answer":"تدل الفاصلة على أن الذم متعلق بحبس حق الله وترك الإنفاق الواجب، لا بمجرد الادخار المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص175، تحت «بلاغة جملة الفاصلة في دلالتها على مفهوم المخالفة»","url":""}]},{"id":"s9-217","number":217,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا استعمل ﴿فبشرهم بعذاب أليم﴾ في مقام الوعيد؟","answer":"على الوجه المجازي، هي بشارة تهكمية وُضع فيها خبر العذاب موضع ما يسر، لتأكيد الذم وزيادة الوعيد. فتصير عاقبة الكنوز التي تعلقوا بها ضد ما رجوه منها من النفع والسرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص176، تحت «وجه إجراء البشارة على المجاز والحقيقة»","url":""}]},{"id":"s9-218","number":218,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة حرف ﴿على﴾ في قوله تعالى: ﴿يوم يحمى عليها﴾؟","answer":"يصور حرف ﴿على﴾ استعلاء الإحماء على الكنوز وشدة حرارتها، فلا يكون المعنى مجرد وجودها في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص181، تحت «معنى الجار والمجرور ودلالته»","url":""}]},{"id":"s9-727","number":727,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة حرف الوعاء ﴿في﴾ في قوله تعالى: ﴿في نار جهنم﴾؟","answer":"يصور حرف ﴿في﴾ استغراق الكنوز في نار جهنم وإحاطة النار بها من كل جانب، فيكمل صورة اشتداد حرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص182، تحت «دلالة حرف الوعاء في»","url":""}]},{"id":"s9-219","number":219,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"لماذا خُصت الجباه والجنوب والظهور بالكي؟","answer":"خُصت الجباه والجنوب والظهور لأنها مواضع الإعراض والبخل والتقلب في النعيم؛ أو لاستيعاب جهات البدن أمامًا وجنبًا وخلفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص183، تحت «نكتة إسناد الكي إلى الأعضاء المذكورة دون غيرها»","url":""}]},{"id":"s9-220","number":220,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما موقع جملة ﴿فتكوى بها﴾ مما قبلها؟","answer":"تتفرع الجملة على إحماء الذهب والفضة: فالكنوز المحماة نفسها تصير أداة كي لأصحابها، جزاءً من جنس ما أحبوه ومنعوا حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص183، تحت «موقع جملة فتكوى بها مما قبلها»","url":""}]},{"id":"s9-221","number":221,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة القول لأصحاب الكنوز: ﴿هذا ما كنزتم لأنفسكم﴾؟","answer":"يواجههم القول بأن ما جمعوه رجاء نفع أنفسهم صار سبب عذابها؛ فالمشار إليه هو الكنز الذي انقلبت عاقبته عليهم، وفي ذلك توبيخ يضاعف ألم الجزاء بالحسرة النفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص186، تحت «موقع جملة هذا ما كنزتم لأنفسكم»","url":""}]},{"id":"s9-728","number":728,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما بلاغة ذكر المتعلَّق ﴿لأنفسكم﴾ في قوله: ﴿هذا ما كنزتم لأنفسكم﴾؟","answer":"يكشف المتعلَّق أنهم قصدوا بالكنز نفع أنفسهم، ثم جاءت العاقبة بعكس قصدهم فصار وبالًا عليها. واللام تحتمل تعليل قصدهم إلى النفع، وتحتمل معنى العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص187، تحت «بلاغة الإطناب بذكر المتعلق»","url":""}]},{"id":"s9-222","number":222,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا ما كنتم تكنزون﴾، فجعل المكنوز شيئًا يذاق؟","answer":"استعير الذوق لمباشرة ألم الجزاء، وجُعل المكنوز مذوقًا لأن عاقبة الكنز وعذابه صارت كأنها عين ما يذوقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص188، تحت «براعة الاستعارة»","url":""}]},{"id":"s9-223","number":223,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة التعبير بلفظ ﴿عِدَّة﴾ دون «عدد» في قوله: ﴿إن عدة الشهور عند الله اثنا عشر شهرًا﴾؟","answer":"جاء لفظ ﴿عِدَّة﴾ في مقام إحصاء الشهور وتثبيت نظامها الشرعي؛ فليس المراد معلومة حسابية مجردة، بل عدد مقرر عند الله لا يتغير بأهواء الناس ولا بعبث النسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص193، تحت «وجه التعبير بلفظ العدة دون العدد»","url":""}]},{"id":"s9-224","number":224,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة توالي القيود في قوله: ﴿في كتاب الله يوم خلق السماوات والأرض﴾؟","answer":"يربط القيد الأول عدد الشهور بكتاب الله وتقديره، ثم يردفه الظرف الزمني ليثبت أن هذا النظام مقرر منذ خلق الكون؛ فلا تملكه أعراف الجاهلية بالتبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص195، تحت «دلالة توالي الجار والمجرور»","url":""}]},{"id":"s9-225","number":225,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما الأشهر الأربعة الحرم في قوله تعالى: ﴿منها أربعة حرم﴾؟","answer":"ذو القعدة وذو الحجة والمحرم ورجب؛ ثلاثة متتابعة وواحد فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص192، تحت «المعنى الإجمالي»","url":""}]},{"id":"s9-226","number":226,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"لماذا أشار إلى نظام الشهور بقوله: ﴿ذلك الدين القيم﴾؟","answer":"ذلك الحساب والتحريم هو النظام المستقيم الذي لا اعوجاج فيه، والالتزام به من الدين لأنه حكم الله في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص197، تحت «دلالة اسم الإشارة ومعنى مرجعه»","url":""}]},{"id":"s9-227","number":227,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة تقييد النهي بقوله: ﴿فلا تظلموا فيهن أنفسكم﴾ مع أن الظلم محرم دائمًا؟","answer":"إذا عاد الضمير إلى الأشهر الحرم كان التقييد لعظم حرمتها وشدة تبعة الظلم فيها، من غير أن يبيح الظلم في غيرها؛ فالتخصيص لزيادة التحذير والتغليظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص197، تحت «دلالة التقييد»","url":""}]},{"id":"s9-228","number":228,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"لماذا تكرر لفظ ﴿كافة﴾ في ﴿وقاتلوا المشركين كافة كما يقاتلونكم كافة﴾؟","answer":"يصرح التكرار بأن المماثلة تتعلق بهيئة الاجتماع في القتال أيضًا، لا بمجرد وقوع القتال من الطرفين. وفيه حث على اجتماع المؤمنين وعدم تفرقهم أمام من يجتمعون على قتالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص202، تحت «براعة الإطناب»","url":""}]},{"id":"s9-229","number":229,"surah":9,"verses":[36,123],"references":[{"surah":9,"verses":[36,123]}],"verseLabel":"التوبة: 36؛ التوبة: 123","question":"ما دلالة إطلاق معية الله للمتقين في قوله: ﴿واعلموا أن الله مع المتقين﴾؟","answer":"أُطلقت المعية لتشمل ما يحتاجه المتقون من تثبيت ونصر وتأييد، وتربط ذلك بحفظ حدود الله حتى في القتال؛ فهي وعد جامع لا يضيقه مجال واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص204، تحت «دلالة إطلاق المعية وعدم تعيين مجالها»","url":""}]},{"id":"s9-230","number":230,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"لماذا وصف النسيء بأنه ﴿زيادة في الكفر﴾ لا كفر مستقل؟","answer":"النسيء أضيف إلى كفرهم الأصلي؛ فهو زيادة لأنهم لم يكتفوا بالشرك، بل بدلوا تشريع الله وأحلوا وحرموا بحسب المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص214، تحت «وجوه أخرى من كون النسيء زيادة في الكفر»","url":""}]},{"id":"s9-231","number":231,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة البناء للمجهول في قراءة ﴿يُضَلّ به الذين كفروا﴾؟","answer":"تركز هذه القراءة على وقوع الضلال بهم وانصرافهم عن الحق، مع عدم التصريح بالمضلِّل في الفعل. ويذكر المصدر مقابلها قراءة ﴿يَضِلّ﴾ التي تبرز وقوع الضلال منهم؛ فتتكامل الدلالتان في كشف حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص217–218، تحت «تنوع القراءات في يضل وأثره في المعنى»","url":""}]},{"id":"s9-232","number":232,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما بلاغة الطباق في قوله: ﴿يحلونه عامًا ويحرمونه عامًا﴾؟","answer":"الطباق بين التحليل والتحريم يكشف تناقض صنيعهم في الشهر نفسه، ويصور خضوع حكمه لأهوائهم لا لشرع الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص220، تحت «بلاغة التعبير بالطباق»","url":""}]},{"id":"s9-729","number":729,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة تنكير ﴿عامًا﴾ في قوله: ﴿يحلونه عامًا ويحرمونه عامًا﴾؟","answer":"يفيد التنكير أن ذلك يقع في بعض الأعوام، فلا يلزم أنهم كانوا يبدلون الحكم على نسق ثابت في كل عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص221، تحت «سر تنكير المفعول فيه عامًا»","url":""}]},{"id":"s9-233","number":233,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"كيف أكد قوله: ﴿ليواطئوا عدة ما حرم الله﴾ الذم بما يشبه المدح؟","answer":"يبدو محافظتهم على عدد أربعة أشهر حرم موافقة محمودة في الظاهر، لكنها تزيد ذمهم؛ لأنهم وافقوا العدد وأهدروا حرمة الأشهر المعينة التي حرمها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص223، تحت «بلاغة تأكيد الذم بما يشبه المدح في المواطأة»","url":""}]},{"id":"s9-234","number":234,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة الفاء والفعل ﴿فيحلوا﴾ في قوله: ﴿فيحلوا ما حرم الله﴾؟","answer":"تفيد الفاء أن إحلال ما حرم الله نتيجة مباشرة لتحايلهم على عدة الأشهر؛ فمهما وافقوا العدد ظاهرًا انتهى فعلهم إلى نقض الحرمة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص225، تحت «معنى التعبير بالفاء ودلالة الفعل فيحلوا»","url":""}]},{"id":"s9-235","number":235,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما سر بناء الفعل للمفعول في قوله: ﴿زين لهم سوء أعمالهم﴾؟","answer":"يصرف البناء للمفعول النظر عن المزيِّن إلى أثر التزيين فيهم؛ فقد انقلبت معاييرهم حتى رأوا العمل السيئ حسنًا واطمأنوا إلى التحايل على الشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص226، تحت «سر التعبير بالبناء للمفعول»","url":""}]},{"id":"s9-236","number":236,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"لماذا ختم بـ﴿والله لا يهدي القوم الكافرين﴾؟","answer":"الخاتمة تناسب من زُين له الكفر فأصر عليه؛ فحرمان الهداية جزاء اختيارهم وتبديلهم حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص228، تحت «براعة ختم الآية»","url":""}]},{"id":"s9-237","number":237,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما سرّ توجيه العتاب إلى المؤمنين في قوله تعالى: ﴿ما لكم إذا قيل لكم انفروا... اثاقلتم﴾؟","answer":"الاستفهام ينكر حالهم عند دعوة النفير: أي عذر لكم في التثاقل بعد وضوح الأمر والحاجة؟ وفيه عتاب محرك للهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص233، تحت «بلاغة التعبير بالاستفهام المجازي»","url":""}]},{"id":"s9-238","number":238,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"لماذا اختيرت صيغة ﴿اثاقلتم﴾ الثقيلة صوتيًا؟","answer":"ثقل حروف ﴿اثاقلتم﴾ وتتابعها يحاكي بطء الحركة وثقل النفس، فجاء جرسها مصورًا لمعناها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص236، تحت «غرض التعبير بالمجاز»","url":""}]},{"id":"s9-239","number":239,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما الصورة في قوله: ﴿اثاقلتم إلى الأرض﴾؟","answer":"صوّرهم كأجسام ثقيلة لاصقة بالأرض لا تقوى على الارتفاع؛ وهو تمثيل لتعلقهم بالدنيا وكرههم النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص236–237، تحت «غرض التعبير بالمجاز»","url":""}]},{"id":"s9-240","number":240,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما لطيفة الاستفهام في قوله: ﴿أرضيتم بالحياة الدنيا من الآخرة﴾؟","answer":"الاستفهام إنكاري توبيخي؛ يكشف فساد رضاهم بالدنيا الزائلة عوضًا عن الآخرة، ويحركهم إلى ترك ما صرفهم عن النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص238، تحت «لطيفة الاستفهام المجازي»","url":""}]},{"id":"s9-730","number":730,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما معنى حرف الجر ﴿من﴾ في قوله: ﴿أرضيتم بالحياة الدنيا من الآخرة﴾؟","answer":"تفيد ﴿من﴾ معنى البدل؛ أي أرضيتم بالحياة الدنيا بدل الآخرة، وفي هذا التصوير إبراز لسوء ما اختاروه في هذه المفاضلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص238، تحت «معاني حرف الجر»","url":""}]},{"id":"s9-241","number":241,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما دلالة تنكير ﴿قليل﴾ في وصف متاع الحياة الدنيا؟","answer":"التنكير للتحقير والتقليل؛ فمتاع الدنيا، مهما بدا، ضئيل سريع الزوال إذا قيس بنعيم الآخرة الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص241، تحت «دلالة التنكير»","url":""}]},{"id":"s9-242","number":242,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما بلاغة بناء الوعيد في قوله: ﴿إلا تنفروا يعذبكم عذابًا أليمًا﴾ على جملة الشرط؟","answer":"يربط الشرط الجزاء بالتخلف ربطًا مباشرًا، فيجعل السامع أمام عاقبة اختياره ويقوي التحذير من ترك النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص245، تحت «بلاغة التعبير بجملة الشرط»","url":""}]},{"id":"s9-731","number":731,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما دلالة الوعيد بقوله: ﴿ويستبدل قومًا غيركم﴾؟","answer":"يهددهم بحرمان شرف نصرة الدين وإسناده إلى قوم يقومون به؛ فالدين لا يتوقف عليهم، وإنما يعود وبال التخلف وخسارته إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص246، تحت «بلاغة التعبير بالاستبدال لقوم آخرين»","url":""}]},{"id":"s9-243","number":243,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما دلالة تنكير ﴿شيئًا﴾ في قوله: ﴿ولا تضروه شيئًا﴾؟","answer":"التنكير في سياق النفي يعم كل قدر من الضرر، حتى أقله؛ فتخلفهم لا يضر الله ولا يبطل وعده بنصر رسوله، وإنما يضرهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص250، تحت «لطيفة تنكير المفعول المطلق»","url":""}]},{"id":"s9-244","number":244,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"لماذا ختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة العامة تعلل تنفيذ الوعيد والاستبدال ونصر الدين بغيرهم؛ فلا يتوقف أمره على جماعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص250، تحت «سر الختم بإقرار لله بالقدرة»","url":""}]},{"id":"s9-245","number":245,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا تنصروه فقد نصره الله﴾، فجاء جواب الشرط بحدث ماض؟","answer":"النصر الماضي دليل على النصر الذي يقتضيه الشرط: إن لم تنصروه فالله ناصره، فقد نصره في حال أشد من قبل. فذُكر الدليل المحقق وأغنى عن التصريح بالجواب المقدر، لتقوية اليقين بكفاية الله لرسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص257، تحت «فائدة حذف جواب الشرط»","url":""}]},{"id":"s9-246","number":246,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة وصف النبي ﷺ بقوله: ﴿ثاني اثنين﴾ في مشهد الهجرة؟","answer":"يصور حاله حين لم يكن معه إلا صاحب واحد، فهو أحد اثنين لا ثالث لهما. وإبراز قلة الناصر البشري في ذلك الموقف يؤكد أن الله نصره وهو بهذه الحال، فكيف يُتوهم توقف نصره على كثرة الأنصار؟","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص260، تحت «لطيفة قيد المفعول به بالحال»","url":""}]},{"id":"s9-247","number":247,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا كرر ﴿إذ﴾ ثلاث مرات في قصة الغار؟","answer":"كل ﴿إذ﴾ تستحضر مرحلة من المشهد: الإخراج، والوجود في الغار، وكلامه لصاحبه؛ فتفصل اللقطات وتحييها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص259، تحت «سر تتابع ظرف الزمان ودلالته»","url":""}]},{"id":"s9-248","number":248,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة جمع النبي ﷺ وصاحبه في الضمير ﴿هما﴾ في قوله: ﴿إذ هما في الغار﴾؟","answer":"في الجمع بينهما بضمير واحد تنويه بمنزلة أبي بكر وشرف صحبته للنبي في ذلك الموقف. وهو جمع في الحضور والرفقة، لا تسوية بينهما في الرتبة؛ فالنبي صاحب المقام المقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص261، تحت «نكتة الجمع بين النبي والصديق في ضمير واحد»","url":""}]},{"id":"s9-249","number":249,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"كيف وُجه النهي في قوله ﷺ لصاحبه: ﴿لا تحزن﴾ مع أن الحزن قد يقع بغير اختيار؟","answer":"المقصود ألا يجعل للحزن سبيلًا بالاسترسال مع أسبابه وآثاره؛ فالنهي يرشد إلى ما يمكن اختياره مما يزيله. وقد جاء التعليل ﴿إن الله معنا﴾ بما يبعث الثقة والطمأنينة ويذهب أثر القلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص262–263، تحت «غرض التعبير بمقول القول بجملة إنشائية»","url":""}]},{"id":"s9-250","number":250,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا علل النهي عن الحزن بقوله: ﴿إن الله معنا﴾؟","answer":"المعية الإلهية معية حفظ ونصر وعلم، وهي أقوى سبب لزوال الحزن؛ فمن كان الله معه لا تضره قلة العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص263، تحت «نكتة تعليل النهي بكونهما بمعية الله تعالى»","url":""}]},{"id":"s9-251","number":251,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما بلاغة إسناد إنزال السكينة إلى الله في قوله: ﴿فأنزل الله سكينته عليه﴾؟","answer":"إسناد الإنزال إلى الاسم الجليل وإضافة السكينة إليه يعظمان أثر الطمأنينة والحفظ، ويبينان أن مصدر الثبات في ذلك الموقف هو الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص265، تحت «بلاغة التعبير بالفعل الماضي مسندا إلى الاسم الجليل»","url":""}]},{"id":"s9-732","number":732,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"إلى من يعود الضمير في قوله: ﴿فأنزل الله سكينته عليه﴾، وما دلالته؟","answer":"الجمهور على عوده إلى النبي ﷺ لمراعاة أصل الحديث واتساق ضمائره؛ وقيل إلى أبي بكر لقرب ذكره، وقيل إليهما مع إفراد الضمير لتلازمهما في الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص266، تحت «تنوع مرجع الضمير عليه ودلالته»","url":""}]},{"id":"s9-252","number":252,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة عطف قوله: ﴿وأيده بجنود لم تروها﴾ على إنزال السكينة؟","answer":"يجمع العطف صور التأييد الإلهي للرسول ﷺ؛ فالسكينة تثبيت باطن، والجنود مدد يحفظه ويصرف عنه الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص266، تحت «دلالة عطف الجملة بالواو»","url":""}]},{"id":"s9-733","number":733,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما سر تنكير ﴿جنود﴾ ووصفها بقوله: ﴿لم تروها﴾؟","answer":"يفيد التنكير تعظيم جنود لا يحيط المخاطبون بعددها أو حقيقتها، ويبين وصفها أن تأييد الله قد يجري خفيًا عن الأبصار مع تحقق أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص267، تحت «سر التنكير والوصف بالجملة»","url":""}]},{"id":"s9-253","number":253,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة القصر بتعريف الطرفين في قوله: ﴿وكلمة الله هي العليا﴾؟","answer":"تعريف الطرفين مع ضمير الفصل يقوي اختصاص كلمة الله بالعلو؛ فهي العليا في ذاتها على وجه ثابت، بخلاف كلمة الكفر التي جعلها الله سفلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص269، تحت «سر التعبير بأسلوب القصر بتعريف الطرفين»","url":""}]},{"id":"s9-254","number":254,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما بلاغة التعبير بالفعل الماضي في قوله: ﴿وجعل كلمة الذين كفروا السفلى﴾؟","answer":"يصور الفعل إحداث خفض كلمة الكفر بعد محاولة ارتفاعها، ويعرض النتيجة واقعة متحققة بفعل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص267، تحت «براعة التعبير بعطف النتيجة وبالفعل الماضي»","url":""}]},{"id":"s9-255","number":255,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا ختم بـ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب ينصر رسوله ويخفض الكفر، و﴿حكيم﴾ يدبر ذلك بأسباب ظاهرة وخفية في أوقاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص270، تحت «براعة التذييل وسر الختم بالعزة والحكم»","url":""}]},{"id":"s9-256","number":256,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما بلاغة الاستعارة في قوله: ﴿انفروا خفافًا وثقالًا﴾؟","answer":"استعيرت الخفة والثقل لأحوال النشاط والعوائق، فجمع الضدان أحوال المكلفين: شبابًا وشيوخًا، وغنى وفقرًا، ونشاطًا وثقلًا؛ فلا تكون الحال ذريعة للتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص278، تحت «بلاغة التعبير بالاستعارة»","url":""}]},{"id":"s9-257","number":257,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما المقصود بـ﴿خفافًا وثقالًا﴾، ولماذا تُرك اللفظ محتملًا؟","answer":"يتسع اللفظ لأحوال متعددة من النشاط والفتور، والشباب والشيخوخة، وقلة المال وكثرته، وقلة العيال وكثرتهم. وهذه المعاني كلها صالحة للمراد، فجمعت العبارة الوجيزة تنوع أحوال المستجيبين للنفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص278–279، تحت «بلاغة التعبير بالاستعارة»","url":""}]},{"id":"s9-258","number":258,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس مرة أخرى؟","answer":"من وجوه التقديم أن المال قوام تجهيز الجيش والإنفاق عليه، فظهرت منزلته في إقامة الجهاد. وذكر المصدر أيضًا أن تقديم بذله يواجه تعلق النفس به وخوفها من ضياعه، فيهيئها للبذل والتضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص280–281، تحت «سر تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-259","number":259,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما دلالة موقع قوله: ﴿ذلكم خير لكم﴾ بعد الأمر بالجهاد؟","answer":"تأتي الجملة بعد التكليف لتقرر أن امتثاله هو الخير لهم في ثوابه وعاقبته ونصر جماعتهم، وإن شق في الحال؛ فالعبرة بالمآل لا بالراحة العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص282، تحت «موقع قوله ذلكم خير لكم مما قبله ودلالته»","url":""}]},{"id":"s9-260","number":260,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما سر ختم الآية بقوله: ﴿إن كنتم تعلمون﴾ مع حذف جواب الشرط؟","answer":"حُذف الجواب لدلالة السياق عليه: إن كنتم تعلمون علمًا نافعًا أدركتم خير الجهاد وامتثلتم. وفي الحذف حث على موازنة الخير الباقي بالمشقة العابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص285، تحت «سر ختم الآية بجملة شرط محذوف الجواب»","url":""}]},{"id":"s9-261","number":261,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿لو كان عرضًا قريبًا وسفرًا قاصدًا لاتبعوك﴾؟","answer":"تكشف الجملة معيار المنافقين: لو كانت منفعة سهلة وسفرًا معتدلًا لاتبعوا، لكنهم تخلفوا حين بعدت المسافة وشقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص292، تحت «بلاغة التعبير بأسلوب الشرط لو»","url":""}]},{"id":"s9-262","number":262,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما سر التعبير بخبر ﴿كان﴾ نكرة موصوفة في قوله: ﴿لو كان عرضًا قريبًا﴾؟","answer":"جاء ﴿عرضًا﴾ نكرة ليصدق على أي متاع دنيوي زائل، ووصفه بالقرب يبرز أن الذي يحركهم منفعة سهلة عاجلة لا إخلاص النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص293، تحت «سر التعبير بخبر كان نكرة موصوفة»","url":""}]},{"id":"s9-263","number":263,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما دلالة وصف السفر بقوله: ﴿قاصدًا﴾؟","answer":"القاصد سفر متوسط سهل، لا يبلغ مشقة المسافة البعيدة. فالوصف يكشف تعلق المنافقين بالراحة والدعة، وأن اتباعهم المفترض مشروط بسفر يسهل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص289–290، 293، تحت «شرح المفردات؛ سر العطف على خبر كان»","url":""}]},{"id":"s9-264","number":264,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما بلاغة التعبير بالفعل اللازم في قوله: ﴿ولكن بعدت عليهم الشقة﴾؟","answer":"أُسند البعد إلى الشقة نفسها، فصُوّر الطريق كأنه ينأى عنهم؛ وهو تصوير يفضح نفور نفوسهم وضعف هممهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص296، تحت «بلاغة التعبير بالفعل اللازم بعدت»","url":""}]},{"id":"s9-734","number":734,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما دلالة حرف الجر ﴿على﴾ في قوله: ﴿بعدت عليهم الشقة﴾؟","answer":"يشعر حرف ﴿على﴾ بثقل السفر واستعلاء مشقته عليهم، فيصور الطريق عبئًا ينوءون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص296، تحت «نكتة التعبير بحرف الجر عليهم»","url":""}]},{"id":"s9-265","number":265,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"لماذا أخبر أنهم سيحلفون بالله قبل أن يقع حلفهم؟","answer":"الإخبار السابق يكشفهم ويحقق صدق الوحي، ويهيئ النبي ﷺ والمؤمنين لأعذارهم المصنوعة عند العودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص298، تحت «بلاغة التعبير بالمستقبل»","url":""}]},{"id":"s9-266","number":266,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما نكتة التعبير بالمحلوف عليه في قولهم: ﴿لو استطعنا لخرجنا معكم﴾؟","answer":"علقوا خروجهم على الاستطاعة ليؤكدوا اعتذارهم ويوهموا أن العجز منعهم لا إرادة التخلف؛ فجاء المحلوف عليه مصوغًا لإحكام عذر مصنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص300، تحت «نكتة التعبير بالمحلوف عليه»","url":""}]},{"id":"s9-267","number":267,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما معنى ﴿يهلكون أنفسهم﴾ مع أنهم أرادوا بالحلف النجاة؟","answer":"حلفهم الكاذب يوقعهم في الإثم والنفاق والعقوبة، فوسيلة النجاة الظاهرة صارت سبب هلاك النفس الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص301–302، تحت «موقع قوله يهلكون أنفسهم ودلالته»","url":""}]},{"id":"s9-268","number":268,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما بلاغة ختم كلامهم بقوله: ﴿والله يعلم إنهم لكاذبون﴾؟","answer":"تكشف الجملة أن حلفهم لا يستر الحقيقة، وتجعل علم الله محيطًا بكلامهم حال صدوره؛ فيُسجل كذبهم بحكم من يعلم السرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص302، تحت «بلاغة الختم بالجملة الحالية»","url":""}]},{"id":"s9-735","number":735,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"كيف يتضمن قوله: ﴿والله يعلم إنهم لكاذبون﴾ تعريضًا بالتهديد؟","answer":"إظهار علم الله بكذبهم لا يقتصر على فضحهم، بل يلوح بأنهم واقعون تحت علمه وحسابه وأن هذا الكذب لن يفلت من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص304، تحت «بلاغة التعريض بالتهديد»","url":""}]},{"id":"s9-269","number":269,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"ما دلالة تقديم ﴿عفا الله عنك﴾ على قوله: ﴿لم أذنت لهم﴾؟","answer":"في تقديم العفو إكرام للنبي ﷺ وتلطف في توجيه العتاب، وإيناس قبل بيان الأولى في الإذن. وقد وُجه الافتتاح على الدعاء، ووُجه على الإخبار بالعفو وإن جاء بلفظ الماضي؛ فلا يلزم حصره في الدعاء وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص306، تحت «دلالة موقع الجملة مما قبلها»","url":""}]},{"id":"s9-270","number":270,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿لم أذنت لهم﴾، ولم يصرح بالفعل الذي أذن لهم في تركه؟","answer":"حُذف متعلق الإذن للعلم به من السياق، أي الإذن في التخلف، فركز التعبير على أصل المبادرة بالإذن قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص306–307، تحت «بلاغة التعبير بالاستفهام الإنكاري»","url":""}]},{"id":"s9-271","number":271,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"لماذا قيل: ﴿يتبين لك الذين صدقوا﴾، وقيل: ﴿وتعلم الكاذبين﴾؟","answer":"الصادقون تظهر دلائل صدقهم في الوقائع والأعمال، فناسبهم التبيّن. أما الكاذبون فحقيقتهم مستترة وراء دعواهم، فلا يكفي ظاهر قولهم، بل يحتاج كشفها إلى علم بما وراءه؛ فناسبهم ﴿تعلم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص308–309، تحت «سر التعبير بالفعل يتبين عن الصادقين وتعلم عن الكاذبين»","url":""}]},{"id":"s9-272","number":272,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا نفى عن المؤمنين أن يستأذنوا في الجهاد بأنفسهم وأموالهم؟","answer":"الإيمان الصادق يدفع إلى الجهاد ولا يحمل صاحبه على طلب الإذن في ترك بذل المال والنفس بلا عذر؛ فالاستئذان علامة على خلل الدافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص312، تحت «بلاغة تنوع متعلق الإذن»","url":""}]},{"id":"s9-273","number":273,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا أعاد الإيمان بالله واليوم الآخر هنا؟","answer":"أعيد الإيمان بالبدء والمعاد لأنهما أصل البذل: الثقة بالله والرجاء في جزاء الآخرة يمنعان الاستئذان في التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص313، تحت «دلالة تقييد الإيمان بالله واليوم الآخر»","url":""}]},{"id":"s9-274","number":274,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾؟","answer":"الخاتمة تقرير لصدق حال المؤمنين وشهادة لهم بالتقوى؛ إذ يعلم الله أن مبادرتهم صادرة عنها. وفيها تنويه بفضلهم وإشعار بأنهم أهل لعظيم الثواب، وليست مجرد وصف لفعل ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص314، تحت «سر ختم الآية بعلم الله بالمتقين»","url":""}]},{"id":"s9-275","number":275,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"لماذا حصر الاستئذان في الذين لا يؤمنون وارتابت قلوبهم؟","answer":"يقصر الاستئذان المذموم هنا على المنافقين الذين لا يؤمنون بالله واليوم الآخر وداخل قلوبهم الريب. فيثبت لهم ما نُفي عن المؤمنين، ويكشف أن طلبهم التخلف نابع من فساد باطنهم وكراهتهم الجهاد، لا من عذر صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص317، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s9-276","number":276,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"لماذا أسند الارتياب إلى القلوب؟","answer":"أُسند الارتياب إلى القلوب لأنها محل الاعتقاد واليقين، فدل على أن التردد نابع من أصل باطن لا عارض سلوكي فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص320، تحت «نكتة إسناد الارتياب إلى القلوب»","url":""}]},{"id":"s9-277","number":277,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"ما الصورة في قوله: ﴿فهم في ريبهم يترددون﴾؟","answer":"صُور الريب كحيز يدورون داخله ذهابًا وإيابًا بلا مخرج؛ فالتردد حركة مضطربة لا تنتهي إلى قرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص321، تحت «بلاغة الاستعارة في حرف الجر في»","url":""}]},{"id":"s9-278","number":278,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"كيف كنى قوله: ﴿فهم في ريبهم يترددون﴾ عن رسوخ الحيرة؟","answer":"جعلهم في صورة من يتحرك ذهابًا وإيابًا داخل حيز مغلق؛ فالتردد الحسي كناية تمثيلية عن اضطراب لا يهتدي صاحبه إلى قرار أو مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص321، تحت «سر التعبير بالكناية في ثوب الاستعارة التمثيلية»","url":""}]},{"id":"s9-279","number":279,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"كيف دل جواب الشرط في قوله: ﴿ولو أرادوا الخروج لأعدوا له عدة﴾ على كذب إرادتهم؟","answer":"جعل إعداد العدة لازمًا لصدق الإرادة؛ فلما لم يقع الإعداد مع القدرة انكشف أن دعوى الرغبة في الخروج لا توافق واقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص324، تحت «سر التعبير بالجواب»","url":""}]},{"id":"s9-280","number":280,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"ما دلالة تنكير ﴿عدة﴾ في قوله: ﴿لأعدوا له عدة﴾؟","answer":"يفيد أن المطلوب أصل الاستعداد بحسب القدرة، لا عدة كاملة لا ينقصها شيء. فلو صدقت إرادتهم لظهر منها قدر من الإعداد، ولو قليلًا؛ فالتنكير يكشف انتفاء هذا الدليل على عزمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص325، تحت «سر تنكير المفعول به»","url":""}]},{"id":"s9-281","number":281,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"ما بلاغة التعبير بالفعل الماضي في قوله: ﴿ولكن كره الله انبعاثهم فثبطهم﴾؟","answer":"يعرض الماضي كراهة انبعاثهم وتثبيطهم أمرين متحققين؛ فقد حُرموا التوفيق جزاء نفاقهم، ووافق تخلفهم حماية المؤمنين من إفسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص326، تحت «بلاغة التعبير بالفعل الماضي»","url":""}]},{"id":"s9-282","number":282,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"لماذا عبّر عن خروجهم بـ﴿انبعاثهم﴾؟","answer":"الانبعاث أصل الحركة ومبدؤها، فالتعبير به يبين أن الكراهة تناولت ابتداء حركتهم نحو الخروج، قبل أن يبلغوا تمامه. وفيه تصوير لما آلوا إليه من السكون والتثاقل بدل النهوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص326، تحت «سر التعبير بالانبعاث دون الخروج»","url":""}]},{"id":"s9-283","number":283,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"لماذا بُني ﴿وقيل اقعدوا مع القاعدين﴾ للمجهول؟","answer":"حذف القائل يفتح الدلالة لوجوه متعددة: وسوسة الشيطان، أو تثبيط بعضهم بعضًا، أو الإذن الذي طلبوه، أو التوبيخ الإلهي. والمقصود إبراز نفاذ القعود فيهم وانقيادهم إليه، مع إيجاز يَسَع هذه الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص327، تحت «نكتة التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s9-284","number":284,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"لماذا فُصل قوله: ﴿لو خرجوا فيكم ما زادوكم إلا خبالًا﴾ عما قبله؟","answer":"جاءت الجملة بيانًا مستقلًا لعلة كراهة انبعاثهم وتثبيطهم: لو خرجوا لنشروا الاضطراب وسعوا بالوشاية والفتنة بين الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص331، تحت «علة فصل قوله لو خرجوا عما قبله»","url":""}]},{"id":"s9-285","number":285,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿ما زادوكم إلا خبالًا﴾ بصيغة القصر؟","answer":"القصر ينفي كل زيادة خير منهم؛ فلم يكن أثرهم المتوقع إلا الخبال والفساد، دون نفع يوازن ضررهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص332، تحت «بلاغة التعبير بجواب الشرط في ثوب أسلوب القصر»","url":""}]},{"id":"s9-286","number":286,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما الصورة في قوله: ﴿ولأوضعوا خلالكم﴾؟","answer":"الإيضاع إسراع شديد، و﴿خلالكم﴾ بين صفوفكم؛ فالصورة تعرضهم يسرعون داخل الجيش بالنميمة والتحريض لتفكيكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص333، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s9-287","number":287,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونكم الفتنة﴾، وعدّى البغي إلى المؤمنين؟","answer":"الأصل: يبغون لكم الفتنة؛ فحذف الجار ووصل الفعل بالمفعول مباشرة. وهذا التوجيه يبرز أنهم يقصدون المؤمنين أنفسهم بالسوء ويريدون إيقاع الفتنة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص334، تحت «فائدة حذف حرف الجر من الفعل»","url":""}]},{"id":"s9-288","number":288,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما بلاغة تقديم الخبر في قوله: ﴿وفيكم سماعون لهم﴾؟","answer":"يبرز التقديم أن موضع الخطر داخل جماعة المؤمنين نفسها؛ ففيهم من ينقل للمنافقين أو يستجيب لهم، ولذلك كان خروجهم منفذًا للفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص335، تحت «بلاغة تقديم الخبر على المبتدأ»","url":""}]},{"id":"s9-289","number":289,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"لماذا ختم بـ﴿والله عليم بالظالمين﴾؟","answer":"العلم بالظالمين يحيط بنفاقهم ومن يستجيب لهم، ويهدد بأن تدبيرهم لا يخفى ولا يفلت من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص335، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-290","number":290,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما سر افتتاح خبر سعيهم بالفتنة بحرف التحقيق في قوله: ﴿لقد ابتغوا الفتنة من قبل﴾؟","answer":"يفيد ﴿قد﴾ مع الماضي تحقيق وقوع طلبهم للفتنة، فيقرر أن مكرهم قديم مجرب وأن أعذارهم الجديدة امتداد لسلوك سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص339، تحت «سر الافتتاح بحرف التحقيق قد»","url":""}]},{"id":"s9-291","number":291,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما الصورة في قوله: ﴿وقلبوا لك الأمور﴾؟","answer":"صُور تدبيرهم كمن يقلب وجوه الأمر بحثًا عن حيلة تفسده، فيغير الحقائق ويقدم ويؤخر حتى يحقق غرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص341، تحت «بلاغة الاستعارة أو المجاز»","url":""}]},{"id":"s9-292","number":292,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"لماذا قيل: ﴿حتى جاء الحق﴾ بحرف الغاية، لا «إلى أن جاء الحق»؟","answer":"تصور ﴿حتى﴾ امتداد تقليبهم للأمور إلى غاية حاسمة قطعت مكرهم؛ فجاءت الغاية متصلة بالفعل ومبرزة لانتهائه بظهور الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343، تحت «وجه التعبير بحتى دون إلى»","url":""}]},{"id":"s9-736","number":736,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما علة التعبير عن ظهور الحق بقوله: ﴿جاء الحق﴾؟","answer":"صُور الحق كأنه آتٍ بنفسه بعد انتظار، فلما جاء انكشف الباطل وظهر أمر الله رغم كراهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343، تحت «علة التعبير عن مجيء الحق وظهور أمر الله بجاء»","url":""}]},{"id":"s9-293","number":293,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما دلالة التعبير بفعل المجيء في قوله: ﴿حتى جاء الحق﴾؟","answer":"في المجيء تصوير لوصول الحق وتحققه رغم شدة محاولات المنافقين إبطال الرسالة؛ فكأن سعيهم إلى منعه انتهى بخيبة، وقد ظهر واستقر. ويؤكد التعبير بالماضي تحقق هذا المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343–344، تحت «نكتة التعبير بفعل المجيء جاء دون أتى»","url":""}]},{"id":"s9-294","number":294,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"ما دلالة تعريف ﴿الفتنة﴾ في قول المنافق: ﴿ولا تفتني﴾؟","answer":"عرّف الفتنة التي زعم أنه يخشاها كأنها أمر معلوم متعين، ليجعل الخروج سببًا مباشرًا لها ويقيم من هذا الزعم ذريعة للتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص352، تحت «دلالة تعريف لفظ الفتنة»","url":""}]},{"id":"s9-295","number":295,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا جاء الرد: ﴿ألا في الفتنة سقطوا﴾؟","answer":"الرد يقلب حجته عليه: الفتنة التي فر منها بزعمِه هي عين النفاق والمعصية التي وقع فيها بطلب التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص353، تحت «دلالة استعمال الدليل المستدل به للنقض من باب قلب النكتة»","url":""}]},{"id":"s9-296","number":296,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا عبّر بـ﴿سقطوا﴾ في الفتنة؟","answer":"السقوط يصور الفتنة حفرة هوى فيها من غير قدرة على الخلاص، وهو أبلغ من مجرد الدخول فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص352، تحت «إيثار التعبير بلفظ سقطوا»","url":""}]},{"id":"s9-297","number":297,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا افتتحت الجملة بـ﴿ألا﴾؟","answer":"﴿ألا﴾ أداة تنبيه واستفتاح تلفت السمع إلى الحقيقة المخالفة لدعواه وتحقق وقوعه في الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص350، تحت «فائدة التصدير بألا»","url":""}]},{"id":"s9-298","number":298,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"كيف تُفهم إحاطة جهنم بالكافرين بين الحقيقة والمجاز؟","answer":"إحاطتها بهم يوم القيامة حقيقة محققة لا مهرب منها، ونُزل المستقبل منزلة الحال لشدة اليقين؛ وذُكر وجه مجازي بأن أسبابها وأعمالها المفضية إليها قد أحاطت بهم الآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص353، تحت «نكتة لفظ المحيطة بين المجاز والحقيقة»","url":""}]},{"id":"s9-737","number":737,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"ما دلالة صيغة اسم الفاعل في قوله: ﴿وإن جهنم لمحيطة بالكافرين﴾؟","answer":"تصور صيغة اسم الفاعل الإحاطة وصفًا ثابتًا محققًا، فتجعل الوعيد حاضرًا مستمرًا وتقطع رجاء الإفلات منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص356، تحت «دلالة صيغة اسم الفاعل»","url":""}]},{"id":"s9-299","number":299,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تصبك حسنة تسؤهم وإن تصبك مصيبة يقولوا قد أخذنا أمرنا﴾؟","answer":"تكشف الجملة أن المنافقين يتأذون بما يصيب النبي ﷺ والمؤمنين من خير، ويفرحون بالمصيبة زاعمين أنهم احتاطوا لأنفسهم؛ فهي تصور انقلاب موازينهم وفساد سرائرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص360، تحت «توجيه المقابلة بين جملتي الشرط»","url":""}]},{"id":"s9-300","number":300,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"لماذا اختير ﴿تصبك﴾ للحسنة والمصيبة معًا؟","answer":"تستعمل الإصابة في الخير والشر، وتوحي ببلوغ الأثر وتمكنه ممن وقع عليه. فناسبت الحسنة والمصيبة جميعًا، وأبرزت قوة تأثر المنافقين بما ينال المؤمنين من ظفر أو شدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص359، تحت «إيثار التعبير بلفظ الإصابة دون المس»","url":""}]},{"id":"s9-301","number":301,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"لماذا نكرت ﴿حسنة﴾ و﴿مصيبة﴾؟","answer":"يوجه المصدر التنكير إلى التقليل: حتى أدنى حسنة للمؤمنين تسوء المنافقين، وأدنى مصيبة تصيبهم تفرحهم. فهو يكشف شدة حسدهم وشماتتهم وتأثرهم بأقل ما يقع من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص359–360، تحت «وجه التعبير بلفظي الحسنة والمصيبة وتنكيرهما»","url":""}]},{"id":"s9-302","number":302,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"ما دلالة قولهم: ﴿قد أخذنا أمرنا من قبل﴾؟","answer":"معناه أنهم يزعمون أنهم أخذوا حذرهم ودبروا أمرهم قبل وقوع المصيبة، فلم يخرجوا مع المؤمنين؛ وفيه إظهار عجبهم برأيهم وشماتتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص361، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s9-303","number":303,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"ما سرّ قوله تعالى: ﴿ويتولوا وهم فرحون﴾؟","answer":"يجمع التعبير بين انصرافهم الظاهر وفرحهم الباطن بمصيبة المؤمنين؛ فعُطف التولي على مقالتهم، ثم جاءت الواو للحال والجملة الاسمية لتصور الفرح وصفًا ملازمًا لهم حين ينصرفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص361، تحت «نكتة إيثار لفظ ويتولوا»","url":""}]},{"id":"s9-304","number":304,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا جاء الرد بالأمر: ﴿قل لن يصيبنا إلا ما كتب الله لنا﴾؟","answer":"جاء الأمر بـ﴿قل﴾ لتلقين المؤمنين الرد الذي يبطل شماتة المنافقين: لا يقع شيء خارج تقدير الله، وما قدره لعباده المؤمنين فمآله إلى الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص366، تحت «وجه الافتتاح بفعل الأمر قل»","url":""}]},{"id":"s9-738","number":738,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا قيل: ﴿ما كتب الله لنا﴾ باللام، لا «علينا»؟","answer":"اللام تشعر بأن ما يقدره الله للمؤمنين مآله إلى نفعهم: نصرًا في الدنيا أو أجرًا وشهادة، فلا يرون قضاءه عبئًا محضًا عليهم، بل خيرًا مكتوبًا لهم في العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «سر التعبير بقوله لنا ودلالة اللام»","url":""}]},{"id":"s9-305","number":305,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب الله لنا﴾ لا «علينا» مع احتمال المصيبة؟","answer":"قال ﴿لنا﴾ لأن ما يقدره الله للمؤمنين خير لهم في العاقبة، نصرًا أو شهادة وأجرًا؛ فالمصيبة في ظاهرها تنتهي إلى منفعة إيمانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «سر التعبير بقوله لنا ودلالة اللام»","url":""}]},{"id":"s9-306","number":306,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا وصف الله بأنه ﴿مولانا﴾ في هذا المقام؟","answer":"﴿مولانا﴾ تفيد الولاية والنصرة والتدبير؛ فمن تولاه الله لم يجزع من تقديره ولم يركن إلى احتياط المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «بلاغة الفصل في جملة هو مولانا»","url":""}]},{"id":"s9-308","number":308,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هل تربصون بنا إلا إحدى الحسنيين﴾، فسمّى النصر والشهادة حسنيين؟","answer":"النصر حسن لما فيه من الظفر، والشهادة حسنى لما فيها من الثواب؛ فالمؤمن بين عاقبتين محبوبتين لا موضع فيهما لشماتة المنافق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص379، تحت «بيان وجه الأحسنية بين المصيرين»","url":""}]},{"id":"s9-309","number":309,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا قيل: ﴿إلا إحدى الحسنيين﴾؟","answer":"حصر انتظار المؤمنين في واحدة من عاقبتين كلتاهما حسنى: النصر أو الشهادة. فأفردت ﴿إحدى﴾ لأنها النتيجة الواقعة، وثُنّيت ﴿الحسنيين﴾ لأن الاختيار واقع بين مصيرين كلاهما خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص378، تحت «بلاغة الاستثناء»","url":""}]},{"id":"s9-310","number":310,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا قابل انتظار المؤمنين إحدى الحسنيين بانتظار عذاب المنافقين؟","answer":"المؤمن ينتظر خيرًا في كلتا الحالين، أما المنافق فينتظره عذاب من الله أو عقوبة بأيدي المؤمنين؛ فالمقابلة تقلب التربص على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص378، تحت «علة الإتيان بأداة الحصر مع الحسنيين دون الإصابة»","url":""}]},{"id":"s9-311","number":311,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"ما دلالة قوله: ﴿بعذاب من عنده أو بأيدينا﴾؟","answer":"﴿من عنده﴾ عذاب ينزله الله من غير مباشرة المؤمنين، و﴿بأيدينا﴾ عقوبة يجريها على أيديهم. والعطف بـ﴿أو﴾ يستوعب وجهي العقوبة المحتملين، فيكتمل به التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص382، تحت «توجيه إضافة العذاب إليه تعالى»","url":""}]},{"id":"s9-312","number":312,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا ختم بقوله: ﴿فتربصوا إنا معكم متربصون﴾؟","answer":"الأمر للتهديد لا للإباحة؛ أي استمروا في انتظاركم، فنحن ننتظر لكم إحدى العقوبتين، وستظهر عاقبة كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص383، تحت «دلالة الفاء في فتربصوا»","url":""}]},{"id":"s9-313","number":313,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا أمرهم بالإنفاق طوعًا أو كرهًا ثم حكم بأنه لن يتقبل منهم؟","answer":"الأمر للتسوية والتهديد: أنفقوا مختارين أو مكرهين، فلن ينفعكم الإنفاق؛ لأن فقد الإيمان أفسد أساس القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص388، تحت «توجيه التعبير بالأمر أنفقوا»","url":""}]},{"id":"s9-314","number":314,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿أنفقوا طوعًا أو كرهًا﴾ بصيغة الأمر؟","answer":"صيغة الأمر ليست طلبًا مقصودًا للإنفاق، بل تفيد التسوية بين حالتي الطوع والكره في عدم القبول، وفيها إهانة وقطع لأطماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص388، تحت «توجيه التعبير بالأمر أنفقوا»","url":""}]},{"id":"s9-315","number":315,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا بُني ﴿لن يتقبل منكم﴾ للمجهول؟","answer":"حذف الفاعل لأن المقصود إبراز النتيجة، وهي انتفاء القبول قطعًا، لا بيان مَن يتقبل؛ والفاعل معلوم من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص392، تحت «غرض نفي التقبل والتعبير عنه بالمبني للمجهول»","url":""}]},{"id":"s9-316","number":316,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا علل عدم القبول بقوله: ﴿إنكم كنتم قومًا فاسقين﴾؟","answer":"تفصل الجملة عما قبلها لتقرر علة مستقلة: فالفسق خروج راسخ عن طاعة الله، ولفظ ﴿كنتم﴾ يدل على تمكن هذا الوصف منهم. واختيار ﴿فاسقين﴾ يجمع كفرهم وآثاره العملية من كسل وكراهة للإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص392، تحت «وجه الفصل في جملة الفاصلة»","url":""}]},{"id":"s9-317","number":317,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وما منعهم أن تقبل منهم نفقاتهم إلا أنهم كفروا﴾؟","answer":"يحصر الأسلوب أسباب رد نفقاتهم فيما بينته الآية: الكفر بالله ورسوله، وإتيان الصلاة بكسل، والإنفاق بكراهة. والكفر أصل هذه الحال، ثم يكشف عطف العملين أثره في عبادتهم وافتقاد الإخلاص فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص396، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-318","number":318,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"لماذا أعيد نفي القبول بعد الآية السابقة؟","answer":"جاء النفي الأول حكمًا مجملًا بعدم قبول النفقة، ثم أعيد هنا ليُفصَّل سببه: الكفر، والكسل في الصلاة، والإنفاق مع الكراهة. فالإعادة تعليل بعد إجمال وليست تكرارًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص396، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-319","number":319,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يأتون الصلاة إلا وهم كسالى﴾، دون أن يقال: «لا يصلون إلا بكسل»؟","answer":"اختيار ﴿يأتون الصلاة﴾ يصور مجيئهم إليها بأجسادهم من غير رغبة قلبية، ويستحضر المضارع تجدد المشهد، ثم تجعل الحال الاسمية ﴿وهم كسالى﴾ الكسل هيئة ظاهرة ملازمة لهم كلما أتوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص401، تحت «إيثار لفظ ولا يأتون»","url":""}]},{"id":"s9-320","number":320,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"لماذا جمع بين الكسل في الصلاة وكراهة الإنفاق؟","answer":"جمعهما لأن الصلاة والإنفاق أبرز العبادات البدنية والمالية؛ وكسلهم في الأولى وكراهتهم للثانية يكشفان خلو العمل من الإيمان والإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص400، تحت «دلالة عطف أعمالهم بالواو»","url":""}]},{"id":"s9-321","number":321,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينفقون إلا وهم كارهون﴾ بجملة اسمية حالية؟","answer":"الجملة الاسمية الحالية تصور الكراهة وصفًا ثابتًا مصاحبًا لكل إنفاق منهم، لا خاطرًا عابرًا يقع مرة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص402، تحت «وجه التعبير عن الإنفاق بالمضارع»","url":""}]},{"id":"s9-322","number":322,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعجبك أموالهم ولا أولادهم﴾ مع أن المال والولد نعم؟","answer":"النهي عن الإعجاب ليس لأنهما ليسا نعمة في ذاتهما، بل لأنهما صارا في حق المنافقين وسيلة تعب وعقوبة في الدنيا ثم يموتون على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص406، تحت «دلالة الفاء وأثرها في فلا تعجبك»","url":""}]},{"id":"s9-324","number":324,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما وجه كون أموال المنافقين وأولادهم عذابًا لهم في الحياة الدنيا؟","answer":"عذابهم بهما يكون بما يلاقونه في تحصيلهما وحفظهما والخوف عليهما، وبما يكلفون من الإنفاق مع الكراهة، وبما يصيبهم فيهما من الآفات والأحزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص410، تحت «معنى الباء في بها»","url":""}]},{"id":"s9-739","number":739,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما أثر تقديم قيد ﴿في الحياة الدنيا﴾ في سياق الآية؟","answer":"يحدد القيد أن تعذيبهم بالأموال والأولاد يقع في الدنيا، ثم ينتقل الكلام إلى مآل آخر هو خروج أرواحهم على الكفر؛ فيتميز عذاب الحياة من سوء الخاتمة مع اتصال أحدهما بالآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص411، تحت «نكتة التقديم والتأخير في الحياة الدنيا»","url":""}]},{"id":"s9-325","number":325,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وتزهق أنفسهم﴾، دون أن يقال: «ويموتوا»؟","answer":"الزهوق يصور مفارقة النفس للجسد بشدة وضيق، فيناسب ذكر عذابهم وتعلقهم بأموالهم وأولادهم، وهو أخص في هذا السياق من مجرد الإخبار بالموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص412، تحت «بلاغة الكناية في وتزهق أنفسهم»","url":""}]},{"id":"s9-326","number":326,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"لماذا ختم بـ﴿وهم كافرون﴾؟","answer":"الحال ﴿وهم كافرون﴾ تبين أخطر مآل للعذاب الدنيوي: أن تنتهي حياتهم من غير توبة، فيتصل عذاب الدنيا بعذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص413، تحت «معنى الواو في قوله وهم كافرون»","url":""}]},{"id":"s9-327","number":327,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"لماذا يحلف المنافقون: ﴿إنهم لمنكم﴾ ثم ينفي الله ذلك؟","answer":"يحلفون طلبًا للسلامة واتقاءً لانكشافهم، فنفى الله انتسابهم الحقيقي إلى المؤمنين؛ إذ جمعتهم الظواهر وفرقتهم العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص419، تحت «غرض تتابع المؤكدات في إنهم لمنكم»","url":""}]},{"id":"s9-328","number":328,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكنهم قوم يفرقون﴾، دون أن يقال: «يخافون»؟","answer":"﴿يفرقون﴾ أبلغ من مطلق الخوف؛ فهو خوف شديد مستمر يحملهم على الحلف والتستر والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص420، تحت «نكتة مادة الفرق والمضارعة»","url":""}]},{"id":"s9-329","number":329,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"ما دلالة حذف متعلق الخوف في قوله: ﴿ولكنهم قوم يفرقون﴾؟","answer":"يعمم الحذف حال خوفهم ويجعلها وصفًا يلازمهم، بدل حصرها في مخوف واحد. ومن دواعيها خوف انكشاف نفاقهم وما يترتب عليه، فدفعتهم هذه الحال إلى التستر بالأيمان وإظهار الموافقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص421، تحت «فائدة حذف متعلق يفرقون»","url":""}]},{"id":"s9-330","number":330,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"لماذا عدّد الملجأ والمغارات والمدخل؟","answer":"عُددت لتصوير شدة نفورهم واستقصاء كل مكان يمكن أن يحجبهم: ملجأ يحمي، أو مغارات تستر، أو مدخل ينفذون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص424، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-331","number":331,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"ما الفرق التصويري بين ﴿ملجأ﴾ و﴿مغارات﴾ و﴿مدخلًا﴾؟","answer":"الملجأ مكان يتحصنون به، والمغارات تجاويف الجبال، والمدخل موضع ضيق ينفذون فيه أو سرداب؛ فتتنوع الصورة من الاحتماء إلى الاختباء والانحشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص427، تحت «فائدة الترتيب بين الملاذات الثلاثة»","url":""}]},{"id":"s9-740","number":740,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"لماذا أُفرد ﴿ملجأ﴾ و﴿مدخلًا﴾ وجُمعت ﴿مغارات﴾؟","answer":"جاء ﴿ملجأ﴾ و﴿مدخلًا﴾ بصيغة الجنس، فيصدق كل منهما على الواحد والكثير، أما جمع ﴿مغارات﴾ فيستحضر تعدد تجاويف الجبال التي قد يختبئون فيها؛ فتتنوع صورة فرارهم وتتسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص428، تحت «نكتة إفراد ملجأ ومدخلًا وجمع مغارات»","url":""}]},{"id":"s9-332","number":332,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿لولوا إليه وهم يجمحون﴾؟","answer":"﴿لولوا إليه﴾ تفيد سرعة الانصراف نحوه، و﴿يجمحون﴾ تصور اندفاعًا لا يملكون رده كجموح الدابة؛ مبالغة في فرارهم من المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص428، تحت «معنى اللام في لولوا إليه»","url":""}]},{"id":"s9-333","number":333,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا عبّر عن الطعن في قسمة الصدقات بقوله: ﴿يلمزك﴾؟","answer":"اللمز طعن خفي يعيب صاحبه غيره قولًا أو إشارة، واختيار المضارع ﴿يلمزك﴾ يصور تجدد طعنهم في النبي ﷺ كلما قسمت الصدقات، فيكشف أن اعتراضهم عادة نفعية لا طلبًا للعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص434، تحت «فائدة التعبير بالمضارع في من يلمزك»","url":""}]},{"id":"s9-334","number":334,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا كرر الشرطين: ﴿فإن أعطوا منها رضوا وإن لم يعطوا منها إذا هم يسخطون﴾؟","answer":"فصل الشرطان ميزانهم النفعي: الرضا تابع للأخذ، والسخط تابع للحرمان؛ فلا يحكمهم حق ولا عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص435، تحت «فائدة التعبير بالجملة الشرطية»","url":""}]},{"id":"s9-335","number":335,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا جاءت المفاجأة بـ﴿إذا هم يسخطون﴾؟","answer":"﴿إذا﴾ الفجائية تصور سرعة انقلابهم إلى السخط بمجرد عدم العطاء، من غير تروٍّ أو نظر في حكمة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص438، تحت «معنى إذا الفجائية في إذا هم يسخطون»","url":""}]},{"id":"s9-336","number":336,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿هم يسخطون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية تفيد ثبات السخط واستقراره فيهم عند الحرمان. و﴿هم﴾ مبتدأ، وجملة ﴿يسخطون﴾ خبره؛ فتكرار إسناد السخط إليهم، بالضمير المنفصل ثم ضمير الفعل، يزيد توكيد هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص438، تحت «موقع جملة هم يسخطون في سياق الآية الكريمة»","url":""}]},{"id":"s9-337","number":337,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة عرض الحال المفترضة بقوله: ﴿ولو أنهم رضوا ما آتاهم الله ورسوله﴾؟","answer":"عرضت الآية الحال التي كان ينبغي أن يكونوا عليها: الرضا بالقسمة والتوكل على الله والرغبة إليه، وفي ذلك تقريع على نقيض فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص440، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-338","number":338,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"لماذا نسب الإيتاء إلى الله ورسوله، ثم قال: ﴿وقالوا حسبنا الله﴾؟","answer":"نسب الإيتاء إلى الله ورسوله لأن الله هو المقدِّر والرسول ﷺ هو المباشر للقسمة بأمره، أما الكفاية والفضل فمن الله وحده فقالوا: ﴿حسبنا الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص443، تحت «فائدة عطف لفظ ورسوله على لفظ الجلالة»","url":""}]},{"id":"s9-339","number":339,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"لماذا تكرر ذكر الله في الآية ولم يكتف بالضمائر؟","answer":"يُظهر تكرار الاسم الجليل تعلق الكفاية والفضل والرغبة بالله، ويجدد تعظيمه في كل مقام؛ فذُكر صراحة عند الثقة بكفايته، وإضافة الفضل إليه، وقصر الرغبة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص444، تحت «معنى قوله تعالى وقالوا حسبنا الله»","url":""}]},{"id":"s9-741","number":741,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة تقديم ﴿إلى الله﴾ في قوله: ﴿إنا إلى الله راغبون﴾؟","answer":"تقديم الجار والمجرور يفيد العناية والقصر؛ أي إن رغبتهم متجهة إلى الله وحده، لا إلى العطاء نفسه ولا إلى أحد من الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص447، تحت «غرض تقديم شبه الجملة»","url":""}]},{"id":"s9-340","number":340,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة الجمع بين ﴿حسبنا الله﴾ و﴿إنا إلى الله راغبون﴾؟","answer":"﴿حسبنا الله﴾ إقرار بالكفاية وتفويض وتوكل عليه، و﴿إنا إلى الله راغبون﴾ بيان لتوجه الرغبة إليه وحده. فتجتمع الثقة بفضله مع صدق الطلب منه والرضا بما يقسمه، وهي الحال التي كان ينبغي أن يقولوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص444، تحت «معنى قوله تعالى وقالوا حسبنا الله»","url":""}]},{"id":"s9-341","number":341,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا افتتحت آية المصارف بـ﴿إنما الصدقات﴾؟","answer":"﴿إنما﴾ تقصر الصدقات على الأصناف المذكورة، فترد اعتراض من يطلبها لغير استحقاق وتبين أن قسمتها حكم شرعي لا هوى شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص448، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-342","number":342,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا سُمّيت الزكاة هنا ﴿الصدقات﴾؟","answer":"يذكر المصدر أن تسميتها صدقة تربط بذلها بصدق وعد الله للإنسان حين جعله خليفة في المال؛ فهي مما يؤديه شكرًا لما رزقه الله. والمؤمن يلتزم بها طاعةً، فتسند حاجات غير القادرين إلى ما أعطيه القادرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص451، تحت «نكتة التعبير عن الزكاة بلفظ الصدقات»","url":""}]},{"id":"s9-343","number":343,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا بدأ بالفقراء ثم المساكين؟","answer":"من توجيهات الترتيب تقديم الأهم في حاجة المعونة؛ فالفقراء والمساكين أحق من غيرهم بهذه الصدقات وهم المقصودون أولًا بذاتها. ويعلل المصدر تقديم الفقراء على هذا الوجه بكونهم أشد حاجة، دون جعل ذلك حسمًا لجميع الخلاف في حد الفقير والمسكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص456، تحت «بلاغة الترتيب بين الأصناف الثمانية»","url":""}]},{"id":"s9-344","number":344,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى في الأصناف الأربعة الأولى باللام، ثم قال: ﴿وفي الرقاب والغارمين وفي سبيل الله﴾ بـ﴿في﴾؟","answer":"من وجوهه أن اللام تناسب تمليك الأصناف الأولى ما يعطَون، وأن ﴿في﴾ تناسب صرف المال في الجهات المذكورة بعدها. وفي العدول أيضًا تصوير لشدة استحقاق هذه الجهات حتى كأنها أوعية توضع فيها الصدقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص452، تحت «معنى اللام في للفقراء»","url":""}]},{"id":"s9-345","number":345,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿المؤلفة قلوبهم﴾ بالبناء للمجهول؟","answer":"حذف فاعل التأليف للعلم به في هذا التوجيه؛ فالله هو الذي يؤلف القلوب. ووجه البناء العناية إلى صفة تأليفها واجتماعها، مع الإيجاز وعدم الحاجة إلى إعادة تسمية الفاعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص453، تحت «نكتة بناء والمؤلفة قلوبهم»","url":""}]},{"id":"s9-346","number":346,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا أفرد ﴿ابن السبيل﴾ مع جمع بقية الأصناف؟","answer":"﴿ابن السبيل﴾ اسم جنس يصدق على كل مسافر انقطع به الطريق، وإفراده يرسم شدة ملازمته للسبيل كأنه ابنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص455، تحت «نكتة إفراد ابن السبيل»","url":""}]},{"id":"s9-347","number":347,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا ختم تعداد المصارف بقوله: ﴿فريضة من الله﴾؟","answer":"﴿فريضة من الله﴾ تؤكد أن تحديد المصارف حكم واجب صادر من الله، فلا مدخل فيه لأهواء المعترضين أو اجتهاد في نقلها إلى غير أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص457، تحت «معنى من في من الله»","url":""}]},{"id":"s9-348","number":348,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما نكتة التذييل بـ﴿والله عليم حكيم﴾ بعد بيان مصارف الصدقات؟","answer":"﴿عليم﴾ بأحوال المستحقين وحاجاتهم، و﴿حكيم﴾ في توزيع المال بينهم؛ فالخاتمة تعلل دقة القسمة وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص457، تحت «نكتة التذييل بعليم حكيم»","url":""}]},{"id":"s9-349","number":349,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا عبّر عن إيذاء النبي ﷺ بقوله: ﴿ومنهم الذين يؤذون النبي﴾ دون ذكر نوع الأذى؟","answer":"أُطلق الأذى ليشمل أقوالهم وأفعالهم كلها، وليدل على تجدد أذاهم، ثم خُص من أقوالهم طعنهم فيه بقولهم: ﴿هو أذن﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص461، تحت «نكتة التعبير بالمضارعة في جملة صلة الموصول يؤذون»","url":""}]},{"id":"s9-350","number":350,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا وصفه المنافقون بقولهم: ﴿هو أذن﴾؟","answer":"قصدوا أنه يسمع كل ما يقال ويصدقه، فحولوا خلقه في الحلم وحسن الاستماع إلى مطعن يتهمونه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص462، تحت «بلاغة الكناية والمجاز المرسل في قوله هو أذن»","url":""}]},{"id":"s9-351","number":351,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا جاء الرد: ﴿قل أذن خير لكم﴾، فأبقى اللفظ نفسه؟","answer":"أبقى لفظهم وقيده بالخير، فقلب الذم مدحًا: هو أذن فيما ينفعكم، يسمع الوحي والحق ويقبل منكم ظاهر الاعتذار رحمة وحلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص464، تحت «نكتة الفصل في قل أذن خير لكم»","url":""}]},{"id":"s9-352","number":352,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا أضيفت ﴿أذن﴾ إلى ﴿خير﴾؟","answer":"إضافة ﴿أذن﴾ إلى ﴿خير﴾ تخصص سماعه بما هو خير لهم، وتنفي زعمهم أنه يقبل كل باطل بلا تمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص465، تحت «بلاغة الأسلوب الحكيم في قوله قل أذن خير لكم»","url":""}]},{"id":"s9-353","number":353,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا فرّق بين ﴿يؤمن بالله﴾ و﴿يؤمن للمؤمنين﴾؟","answer":"عُدّي الإيمان بالله بالباء لأنه تصديق جازم به، وعُدّي الإيمان للمؤمنين باللام لأن المراد تصديق أخبارهم والثقة بهم وقبول قولهم؛ فاختلاف الحرفين يميز حقيقة الإيمان بالله من حسن الاستماع للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص465، تحت «نكتة مجيء يؤمن بالله»","url":""}]},{"id":"s9-354","number":354,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمة للذين آمنوا منكم﴾، فقيد الرحمة بالمؤمنين؟","answer":"إن حُمل ﴿الذين آمنوا﴾ على صادقي الإيمان، فالتخصيص لأنهم المنتفعون بهدايته ورحمته. وإن أريد من أظهر الإيمان، فمن رحمته بهم قبول ظاهرهم وعدم كشف أسرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص466، تحت «بلاغة العطف في ورحمة للذين آمنوا منكم»","url":""}]},{"id":"s9-355","number":355,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا أعاد الاسم الموصول: ﴿والذين يؤذون رسول الله﴾ بعد قوله ﴿الذين يؤذون النبي﴾؟","answer":"أعيد الموصول لاستئناف حكم عام في كل من يؤذي الرسول ﷺ، وليترتب عليه الوعيد مستقلًا بعد الرد على مقالتهم الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص468، تحت «بلاغة العطف في والذين يؤذون رسول الله»","url":""}]},{"id":"s9-742","number":742,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا عُدل من وصف ﴿النبي﴾ إلى وصف ﴿رسول الله﴾؟","answer":"وصف الرسالة يبرز أن أذاهم لا يتعلق بشخصه ﷺ وحده، بل بمنصبه في تبليغ أمر الله؛ ولذلك كان الوعيد على إيذائه أشد وأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص469، تحت «نكتة العدول عن وصف النبوة إلى وصف الرسالة»","url":""}]},{"id":"s9-356","number":356,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿لهم عذاب أليم﴾ بدل «سيعذبهم الله»؟","answer":"الجملة الاسمية مع تقديم ﴿لهم﴾ تثبت اختصاصهم بالعذاب واستقراره لهم، ووصفه بالأليم يجانس الأذى الذي ألحقوه بالرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص470، تحت «نكتة التعبير بالجملة الاسمية في فاصلة الآية»","url":""}]},{"id":"s9-357","number":357,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون بالله لكم ليرضوكم﴾، فجعل غاية الحلف رضا المؤمنين؟","answer":"قيد الحلف بقوله ﴿لكم﴾ ثم كشف غايته بقوله ﴿ليرضوكم﴾، فظهر أنهم لا يقصدون الحق، وإنما يسترون نفاقهم بطلب رضا الناس، مع أن رضا الله ورسوله أحق أن يطلبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص479، تحت «سر تقييد الحلف بالجار والمجرور لكم»","url":""}]},{"id":"s9-358","number":358,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿والله ورسوله أحق أن يرضوه﴾، فأفرد الضمير مع ذكر اثنين؟","answer":"من توجيهاته أن رضا الرسول ﷺ لا ينفك عن رضا الله، فإرضاؤه من إرضائه سبحانه، فناسب ذلك توحيد الضمير. وذكر المصدر أوجهًا أخرى في عود الضمير وتقدير المحذوف، وكلها تراعي تعظيم المقام واتصال طاعة الرسول بطاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص482–484، تحت «نكتة حذف المسند الثاني وتوحيد الخبر في السياق الكريم»","url":""}]},{"id":"s9-359","number":359,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما دلالة ذكر الرسول ﷺ مع اسم الله في قوله: ﴿والله ورسوله أحق أن يرضوه﴾؟","answer":"ينبه إلى أن طلب رضا الرسول وطاعته من طلب رضا الله، ويعظم منزلته في مقام تبليغ الرسالة. وفي وقوع ذكره قبل الخبر ﴿أحق﴾ توكيد لوجوب مراعاة حقه وترك ما يؤذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص481–482، تحت «بلاغة عطف اسم الرسول الأكرم على اسم الجلالة الأعظم»","url":""}]},{"id":"s9-360","number":360,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"لماذا استعمل ﴿أحق﴾ مع أن إرضاء الله ورسوله واجب لا مجرد أولى؟","answer":"يوجه المصدر ﴿أحق﴾ هنا بمعنى حقيق وواجب، مع اختصاص الله ورسوله بهذا الحق في المقام؛ فلا يراد مجرد ترجيح يجوز معه تقديم رضا الناس عليهما. فهي تبطل جعل إرضاء المؤمنين بالحلف الكاذب غايةً بدل امتثال ما يرضي الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص484–485، تحت «سر التعبير بمادة التفضيل أحق صيغة ومادة لغوية»","url":""}]},{"id":"s9-361","number":361,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"لماذا خُتم بـ﴿إن كانوا مؤمنين﴾؟","answer":"الشرط يفضح دعوى الإيمان: إن كانوا مؤمنين حقًا لقدموا رضا الله ورسوله، أما صنيعهم فدليل على خلاف ما يظهرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص485، تحت «بلاغة القيد بالشرط في جملة إن كانوا مؤمنين»","url":""}]},{"id":"s9-362","number":362,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا افتتحت الآية بـ﴿ألم يعلموا﴾ مع أن المنافقين يخفون كفرهم؟","answer":"الاستفهام للتوبيخ والتقرير؛ وعلمهم بما توعد الله به من المحادة حجة عليهم، وإن أظهروا الإيمان وأبطنوا الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص491، تحت «بلاغة الفصل ألم يعلموا»","url":""}]},{"id":"s9-363","number":363,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿من يحادد الله ورسوله﴾؟","answer":"المحادة اتخاذ حد وجانب في مقابلة حد الله ورسوله؛ فصورت مخالفتهم عداوة ومشاقة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص493، تحت «سر التعبير بالمحادة في الفعل يحادد»","url":""}]},{"id":"s9-364","number":364,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"إلى من يعود الضمير في ﴿فأن له نار جهنم﴾، وما دلالة إفراده؟","answer":"يعود إلى ﴿مَن﴾ المحادِّ لله ورسوله، وقد روعي لفظها المفرد. وهذا الفرد يراد به كل من تحققت فيه الصفة؛ فلا تتعلق وحدة الضمير بذكر الله ورسوله، بل بمرجعه الذي استحق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص498–500، تحت «بلاغة تقديم الجار والمجرور له؛ نكتة إفراد له وخالدًا»","url":""}]},{"id":"s9-365","number":365,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا جمع بين ﴿خالدًا فيها﴾ و﴿ذلك الخزي العظيم﴾؟","answer":"﴿خالدًا فيها﴾ يبين دوام العذاب، و﴿ذلك الخزي العظيم﴾ يجمع إلى الألم الهوان والفضيحة؛ فاستوفى نوعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص499، تحت «سر القيد بالحال خالدًا فيها»","url":""}]},{"id":"s9-366","number":366,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا أشار إلى العذاب بالبعيد: ﴿ذلك الخزي العظيم﴾؟","answer":"اسم الإشارة للبعيد يفخم شأن الخزي ويهول منزلته، ثم أكده بوصفه ﴿العظيم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص501، تحت «دلالة الإشارة في ذلك الخزي»","url":""}]},{"id":"s9-367","number":367,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"كيف يحذر المنافقون أن تنزل سورة تكشفهم مع أنهم لا يصدقون الوحي؟","answer":"يذكر المصدر أن الحذر قد ينشأ من الشك في أمر الوحي والخشية من أن يكون الرسول ﷺ صادقًا فيكشف الله ما يخفونه. فتظاهرهم بإنكار الوحي لا يمنع اضطرابهم من احتمال الفضيحة، ولا يلزم حمل خوفهم على إيمان ثابت به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص508، تحت «بلاغة الكناية في لفظة يحذر»","url":""}]},{"id":"s9-368","number":368,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿يحذر المنافقون أن تنزل عليهم سورة﴾، مع أن السورة تنزل على النبي؟","answer":"﴿عليهم﴾ لأنها وإن نزلت على النبي ﷺ كانت في شأنهم وكاشفة لأحوالهم، فكان وقعها وضررها عائدًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص512، تحت «بلاغة التعبير بالمجاز المرسل في تنزيل السورة عليهم»","url":""}]},{"id":"s9-369","number":369,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿تنبئهم بما في قلوبهم﴾، فجعل السورة مخبرة للمنافقين أنفسهم؟","answer":"اختير ﴿تنبئهم﴾ لأنها تفيد الإخبار بأمر خفي ذي شأن؛ فتكشف السورة ما في قلوبهم حتى تصير خباياهم معلومة. ونُسب الإنباء إلى السورة لأنها سبب إعلان تلك الأسرار وافتضاح أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص514، تحت «الدقة في اصطفاء كلمة تنبئهم»","url":""}]},{"id":"s9-370","number":370,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"لماذا أُمر النبي أن يقول لهم: ﴿استهزئوا﴾؟","answer":"الأمر للتهديد والتعجيز، لا للإذن؛ أي استمروا في استهزائكم فالله سيظهر ما تخافون ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص517، تحت «بلاغة الأمر بالفعل قل»","url":""}]},{"id":"s9-371","number":371,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله مخرج ما تحذرون﴾، وصوّر السر كشيء يُخرج؟","answer":"صور ما أخفوه في القلوب شيئًا محبوسًا يخرجه الله إلى العلن، وفيه تأكيد أن كتمانهم لا يمنع افتضاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص519، تحت «بلاغة التصوير البياني في الخبر»","url":""}]},{"id":"s9-372","number":372,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"لماذا اختير اسم الفاعل ﴿مخرج﴾ لا الفعل «سيخرج»؟","answer":"اسم الفاعل يدل على ثبوت الوعد وتحققه واستمرار القدرة عليه، فكأن إخراج أسرارهم وصف قائم لا أمر محتمل في المستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص520، تحت «سر التعبير باسم الفاعل مخرج»","url":""}]},{"id":"s9-373","number":373,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿ولئن سألتهم ليقولن إنما كنا نخوض ونلعب﴾؟","answer":"أكد بالقسم ولام الجواب ونونه أنهم سيجيبون بهذا الاعتذار، ثم حصروا فعلهم بإنما في الخوض واللعب ليوهموا أنهم لم يقصدوا الاستهزاء؛ ففضح النظم عذرهم الجاهز.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص525، تحت «بلاغة التعبير بالقسم وجوابه»","url":""}]},{"id":"s9-374","number":374,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"لماذا عبّروا عن استهزائهم بـ﴿نخوض ونلعب﴾؟","answer":"استعاروا الخوض للاندفاع في حديث الباطل كما يخوض المرء في الماء، ثم عطفوا ﴿ونلعب﴾ ليؤكدوا زعمهم أن الكلام عابر غير مقصود. لكن هذا التهوين لا يرفع قبح الاستهزاء ولا تبعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص528، تحت «بلاغة الاستعارة التبعية في لفظة نخوض»","url":""}]},{"id":"s9-375","number":375,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما دلالة الاستفهام في قوله: ﴿أبالله وآياته ورسوله كنتم تستهزئون﴾؟","answer":"الاستفهام إنكاري توبيخي، وقد قُدّم الجار والمجرور لإبراز فظاعة المتعلَّق: فالله وآياته ورسوله لا يصح أن يكونوا محل استهزاء، ولا يصلح ادعاء اللعب عذرًا في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص529، تحت «من بلاغة الاستفهام أبالله في السياق»","url":""}]},{"id":"s9-376","number":376,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما دلالة تقديم ﴿بالله وآياته ورسوله﴾ على ﴿كنتم تستهزئون﴾؟","answer":"قدم متعلق الاستهزاء لأنه الأهم في مقام التوبيخ، ودخلت عليه همزة الإنكار؛ فوجه التقريع إلى اتخاذ الله وآياته ورسوله محلًا لاستهزائهم، بعدما أقروا بالخوض واللعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص530، تحت «بلاغة تقديم الجار والمجرور في السياق»","url":""}]},{"id":"s9-377","number":377,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تعتذروا﴾ مع أنهم قدموا عذر اللعب؟","answer":"نُهوا عن الاعتذار لأن قولهم ﴿إنما كنا نخوض ونلعب﴾ لا يصلح عذرًا، بل هو إقرار بالفعل ومحاولة لتهوين جريمة لا يهونها اللعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص532، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-378","number":378,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"لماذا قيل للمنافقين: ﴿قد كفرتم بعد إيمانكم﴾؟","answer":"سُمّي استهزاؤهم كفرًا لأنه طعن في الله وآياته ورسوله، و﴿بعد﴾ تبين انقلابهم عما أظهروه من الإيمان. وإضافة الإيمان إليهم تراعي دعواهم وحكم ظاهرهم، فلا تشهد بصدق ما أخفوه في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص535، تحت «دلالة وصف الاستهزاء بالكفر»","url":""}]},{"id":"s9-379","number":379,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿إن نعف عن طائفة منكم نعذب طائفة﴾؟","answer":"يفتح الشرط باب الرجاء لمن يتوب، مع إبقاء الوعيد لمن يصر على الإجرام؛ فمن أقلع وتاب ليس كمن استمر في النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص536، تحت «نكتة التقييد بإن»","url":""}]},{"id":"s9-380","number":380,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما دلالة إسناد العفو والعذاب إلى الله في ﴿نعف﴾ و﴿نعذب﴾؟","answer":"في هذا الإسناد تعظيم للعفو وترغيب فيه، وتهويل للعذاب وترهيب منه؛ فأمر الفريقين إلى الله، وهو القادر على إنفاذ العفو والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص538، تحت «نكتة إسناد العفو والعذاب إليه تعالى»","url":""}]},{"id":"s9-381","number":381,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"لماذا علل التعذيب بقوله: ﴿بأنهم كانوا مجرمين﴾ لا «مستهزئين»؟","answer":"الإجرام أعم ويكشف رسوخ الذنب وتعديه؛ فاستهزاؤهم ثم اعتذارهم الكاذب مظهر من حال إجرامية مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص539، تحت «لطيفة في وصف لفظ طائفة الثانية بالإجرام»","url":""}]},{"id":"s9-382","number":382,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿المنافقون والمنافقات بعضهم من بعض﴾، وقال في المؤمنين: ﴿بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم من بعض﴾ تفيد تشابه المنافقين في الكفر وصفات الشر، أما ﴿بعضهم أولياء بعض﴾ فتثبت للمؤمنين رابطة المحبة والنصرة والتعاون؛ فتختلف رابطة الإيمان عن مجرد الاشتراك في النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص548، تحت «دلالة الإطناب في صيغة الخبر»","url":""}]},{"id":"s9-383","number":383,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا صرح بذكر المنافقات مع المنافقين؟","answer":"لإحاطة الحكم بالجنسين وبيان اشتراكهما في صفات النفاق ووعيده؛ فلا يختص الذم بالرجال دون النساء اللاتي يشاركنهم أو يعاونّهم في تلك الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص547، تحت «علة التصريح بذكر والمنافقات»","url":""}]},{"id":"s9-384","number":384,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما سرّ تقديم الأمر بالمنكر على النهي عن المعروف؟","answer":"قدم الأمر بالمنكر لأنه يبين مبادرتهم إلى نشر الشر، ثم ذكر نهيهم عن المعروف؛ فجمعوا الدعوة إلى الفساد والصد عن الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص554، تحت «سر البدء بالأمر بالمنكر على النهي عن المعروف»","url":""}]},{"id":"s9-385","number":385,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما الصورة في قوله: ﴿ويقبضون أيديهم﴾؟","answer":"كناية عن البخل ومنع الإنفاق والمعونة؛ فصوّر أيديهم مقبوضة لا تمتد إلى خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص553–554، تحت «بلاغة الكناية في قبض اليد عن الشح»","url":""}]},{"id":"s9-386","number":386,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما دلالة قوله تعالى: ﴿نسوا الله فنسيهم﴾، وهل يوصف الله بالنسيان؟","answer":"بل تركوا ذكر الله وطاعته، فعاملهم معاملة المنسي بتركهم من رحمته وتوفيقه، جزاءً وفاقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص554، تحت «بلاغة التعبير بالمجاز في نسوا»","url":""}]},{"id":"s9-387","number":387,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا رتب نسيان الله لهم بالفاء على نسيانهم؟","answer":"الفاء تفيد ترتيب الجزاء على العمل وتعقيبه: لما تركوا طاعة الله جازاهم بتركهم من فضله وتوفيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص555، تحت «من بلاغة المجاز والمشاكلة في سياق الآية الكريمة»","url":""}]},{"id":"s9-388","number":388,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا ختم بـ﴿إن المنافقين هم الفاسقون﴾؟","answer":"أكد الحكم بـ﴿إن﴾ وضمير الفصل ﴿هم﴾ وقصر الفسق عليهم للمبالغة؛ لأن النفاق جمع وجوه الخروج عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص556، تحت «دلالة موقع الجملة المؤكدة بإن مما قبلها»","url":""}]},{"id":"s9-389","number":389,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا جمع في الوعيد المنافقين والمنافقات والكفار؟","answer":"جمعهم لاشتراكهم في الكفر والمصير، مع التصريح بالذكور والإناث من المنافقين حتى يعم الوعيد جميع أصنافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص561، تحت «بلاغة الإظهار في مقام الإضمار»","url":""}]},{"id":"s9-390","number":390,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"ما دلالة قوله: ﴿نار جهنم خالدين فيها هي حسبهم ولعنهم الله﴾؟","answer":"﴿خالدين فيها﴾ يقرر دوام العذاب، و﴿هي حسبهم﴾ تبين أن جهنم كافية في جزائهم لشدة نكالها، ثم يزيد ذكر اللعنة معنى الإبعاد من رحمة الله؛ فتتراكم وجوه الوعيد ولا يتعارض بعضها مع بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص563، تحت «دلالة التعبير بالحال خالدين فيها»","url":""}]},{"id":"s9-391","number":391,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا جمع بين النار ولعنة الله والعذاب المقيم؟","answer":"زاد ذكر اللعنة معنى الإبعاد من رحمة الله على وعيد النار، ووصف العذاب بالمقيم يصور ملازمته ودوامه، فيجمع السياق بين ألم العقوبة والحرمان من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص565، تحت «سر عطف جملة ولعنهم الله»","url":""}]},{"id":"s9-392","number":392,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا وصف العذاب بأنه ﴿مقيم﴾ لا «دائم»؟","answer":"﴿مقيم﴾ يصور العذاب ثابتًا ملازمًا لا يبرح صاحبه، فكأنه مقيم معه؛ وهو أبلغ تصويرًا من الإخبار المجرد بالدوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص567، تحت «سر وصف العذاب بمقيم»","url":""}]},{"id":"s9-393","number":393,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا شُبّه المنافقون بمن قبلهم قبل تفصيل أوجه الشبه؟","answer":"قدم التشبيه الإجمالي لاستحضار سنة الأمم قبلهم وتحذيرهم من المصير نفسه، ثم فصل وجوه المشابهة في القوة والمتاع والخوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص569، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-394","number":394,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا عدد القوة وكثرة الأموال والأولاد؟","answer":"عددها لأنها أبرز أسباب اغترار الأمم: قوة الأبدان والسلطان، وسعة المال، وكثرة الأعوان والذرية؛ ولم تمنع عنهم العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص575، تحت «دلالة اعتراضية جملة اعتبارهم أشد منهم قوة»","url":""}]},{"id":"s9-395","number":395,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستمتعوا بخلاقهم فاستمتعتم بخلاقكم﴾؟","answer":"تكرار العبارة يطابق بين فعل السابقين واللاحقين: تمتع كل فريق بنصيبه العاجل حتى شغله عن الآخرة، فاستحقوا مآلًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص579، تحت «دلالة الطلب بالفعل استمتع في السياق»","url":""}]},{"id":"s9-396","number":396,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما معنى ﴿خلاقهم﴾، ولماذا اختير بدل «نصيبهم»؟","answer":"الخلاق نصيب الخير المكتسب أو المستحق، أما النصيب فأعم. وقد استعمل هنا في حظهم من لذات الدنيا التي ألهتهم عن الآخرة، وفيه تهكم بمن استبدل الحظ العاجل بالجزاء الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص582، تحت «سر التعبير بالخلاق»","url":""}]},{"id":"s9-397","number":397,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا كرر ﴿كما استمتع الذين من قبلكم بخلاقهم﴾ بعد وضوح التشبيه؟","answer":"كرر الاستمتاع لتأكيد مماثلة اللاحقين للسابقين في الاغترار بنصيب الدنيا، مع بيان أن من قبلهم كانوا أشد قوة وأكثر مالًا وولدًا فلم تغن عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص580، تحت «نكتة الإطناب في تكرار لفظ الاستمتاع»","url":""}]},{"id":"s9-398","number":398,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وخضتم كالذي خاضوا﴾، فأفرد ﴿الذي﴾؟","answer":"من توجيهات ﴿الذي﴾ أنها مصدرية، أو صفة لمصدر محذوف، أي كالخوض الذي خاضوه؛ فالإفراد على هذين الوجهين باعتبار الفعل لا جماعة الخائضين. وذكر المصدر أوجهًا أخرى لتوجيه الموصول.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص583–584، تحت «بلاغة الإيجاز في التشبيه؛ نكتة التعبير بالاسم الموصول المفرد كالذي»","url":""}]},{"id":"s9-399","number":399,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا جمع بين حبوط الأعمال والخسران؟","answer":"حبوط الأعمال يبين بطلان ما عملوه وذهاب ثمرته، والخسران يبين ما عاد على ذواتهم من فقد الخير واستحقاق العقاب؛ فجمع خسارة العمل والعامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص585، تحت «نكتة فصل قوله أولئك حبطت أعمالهم»","url":""}]},{"id":"s9-400","number":400,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا تكرر اسم الإشارة في قوله: ﴿أولئك حبطت أعمالهم... وأولئك هم الخاسرون﴾؟","answer":"أعيد ﴿أولئك﴾ ليستأنف لكل نتيجة حكم مستقل: حبوط الأعمال أولًا، ثم ثبوت الخسران لأصحابها؛ فيرسخ الوعيدان ولا تبدو الثانية مجرد تابع للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص588، تحت «فائدة إعادة ذكر اسم الإشارة للبعيد»","url":""}]},{"id":"s9-743","number":743,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما وجه البلاغة في القصر بضمير الفصل هم وتعريف طرفي الإسناد؟","answer":"ضمير الفصل ﴿هم﴾ مع تعريف طرفي الإسناد يقوي اختصاصهم بالخسران على سبيل المبالغة؛ فكأنهم استجمعوا حقيقته وبلغوا غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص589، تحت «بلاغة القصر بضمير الفصل هم وتعريف طرفي الإسناد»","url":""}]},{"id":"s9-401","number":401,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا سأل: ﴿ألم يأتهم نبأ الذين من قبلهم﴾ مع معرفتهم بأخبار بعضهم؟","answer":"الاستفهام للتقرير والتوبيخ؛ فالعبرة ليست بمجرد سماع الأخبار، بل بفهم دلالتها، وكأنها لم تأتهم لما لم ينتفعوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص595، تحت «بلاغة الاستفهام في صدر الآية الكريمة»","url":""}]},{"id":"s9-744","number":744,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير بإتيان النبأ في قوله: ﴿ألم يأتهم نبأ الذين من قبلهم﴾؟","answer":"صُوّر الخبر كأنه آتٍ يبلغهم بنفسه؛ لكثرة طرق وصوله ووضوح شواهده، فلا يبقى لهم عذر في الغفلة عنه أو عدم الاعتبار به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص596، تحت «نكتة التعبير بالإتيان دون غيره من الألفاظ»","url":""}]},{"id":"s9-745","number":745,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما فائدة التعبير بالموصول في قوله: ﴿نبأ الذين من قبلهم﴾؟","answer":"يجمع الموصول الأمم السابقة تحت وصف واحد هو تقدمها وسبق مصيرها، ثم يأتي تفصيلها بعد ذلك؛ فيهيئ السامع للعبرة العامة قبل تعداد أمثلتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص597، تحت «نكتة التعبير بالاسم الموصول الذين»","url":""}]},{"id":"s9-403","number":403,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا جمع أممًا متباعدة: قوم نوح وعاد وثمود وقوم إبراهيم وأصحاب مدين والمؤتفكات؟","answer":"خصت هذه الأمم لأن أخبارها معروفة للعرب وآثار بعض ديارها قريبة منهم، ولتنوع ما حل بها من العقوبات مع اشتراكها في تكذيب الرسل؛ فاجتمعت شواهد التحذير والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص599، تحت «نكتة ذكر والمؤتفكات»","url":""}]},{"id":"s9-404","number":404,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا سميت قرى لوط ﴿المؤتفكات﴾؟","answer":"سميت ﴿المؤتفكات﴾ لأنها ائتفكت، أي انقلبت بأهلها؛ فالاسم يستحضر هيئة العقوبة التي صارت علمًا على قراهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص599، تحت «معنى أل للتعريف والعهد في لفظ والمؤتفكات»","url":""}]},{"id":"s9-405","number":405,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما دلالة قوله: ﴿أتتهم رسلهم بالبينات﴾ بعد ذكر الأمم السابقة؟","answer":"ذكر مجيء الرسل بالبينات يقرر تمام الحجة قبل الهلاك، وينفي أن تكون العقوبة بلا إنذار أو بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص600، تحت «نكتة فصل قوله أتتهم رسلهم»","url":""}]},{"id":"s9-406","number":406,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون﴾؟","answer":"نفت الصيغة المؤكدة إمكان الظلم عن الله، ثم أسندت ظلمهم إلى أنفسهم؛ لأنهم باختيار التكذيب جلبوا إليها العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص601، تحت «دلالة الفاء في سياق نفي الظلم»","url":""}]},{"id":"s9-407","number":407,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى في المؤمنين: ﴿بعضهم أولياء بعض﴾ بدل ﴿بعضهم من بعض﴾ الواردة في المنافقين؟","answer":"الولاية تتضمن المحبة والنصرة والتعاون على الخير، وهي رابطة المؤمنين؛ أما ﴿بعضهم من بعض﴾ في المنافقين فمجرد تشابه في الطبع والشر لا ولاء صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص610–611، تحت «نكتة تغاير وصف المؤمنين عن وصف المنافقين»","url":""}]},{"id":"s9-408","number":408,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما دلالة الجمع بين المؤمنين والمؤمنات في وصف الولاية؟","answer":"يبين اشتراك الرجال والنساء في رابطة الإيمان وما تقتضيه من الولاية والتعاون والتكاليف المذكورة؛ فتشمل هذه الصفات والجزاء الجنسين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص611، تحت «دلالة الجمع بين المؤمنين والمؤمنات»","url":""}]},{"id":"s9-409","number":409,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما دلالة تقديم الأمر بالمعروف على النهي عن المنكر، وكيف يقابل ذلك وصف المنافقين؟","answer":"قُدّم الأمر بالمعروف لأنه إيجاد للخير، ثم أتبعه النهي عن المنكر لإزالة الشر. ويقابل ذلك المنافقون فيأمرون بالمنكر وينهون عن المعروف؛ فثبت ترتيب الأمر ثم النهي، وانقلب متعلق كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص612، تحت «فائدة تقديم الأمر على النهي»","url":""}]},{"id":"s9-410","number":410,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"لماذا جمع الصلاة والزكاة بعد الأمر بالمعروف والنهي عن المنكر؟","answer":"الأمر والنهي إصلاح للمجتمع، ثم خص الصلاة والزكاة لأنهما عمادا صلاح الفرد في العبادة البدنية والمالية، ودليل صدق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص614، تحت «فائدة التنصيص على إقامة الصلاة والزكاة»","url":""}]},{"id":"s9-411","number":411,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿ويطيعون الله ورسوله﴾ بعد تفصيل الأعمال؟","answer":"بعد ذكر أعمال ظاهرة مخصوصة جاء الوصف الجامع ﴿يطيعون الله ورسوله﴾ ليدخل فيه سائر الأوامر والنواهي، وليبين أن تلك الأعمال صادرة عن طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص615، تحت «علة استحضار الطاعة بعد ذكر الفرائض السابقة»","url":""}]},{"id":"s9-412","number":412,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك سيرحمهم الله﴾ بالسين؟","answer":"السين تفيد الوعد بالرحمة المستقبلة المتحققة، ولا سيما رحمة الآخرة؛ وفيها بشارة مرتبة على صفاتهم وأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص616، تحت «نكتة دخول السين على الفعل سيرحمهم»","url":""}]},{"id":"s9-413","number":413,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"لماذا ختم بـ﴿إن الله عزيز حكيم﴾ لا «غفور رحيم»؟","answer":"﴿عزيز﴾ قادر على نصر أوليائه وإنفاذ وعده، و﴿حكيم﴾ يضع الرحمة في أهلها؛ فالخاتمة تناسب الوعد بالتمكين والجزاء وفق الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص617، تحت «بلاغة فصل قوله إن الله عزيز حكيم»","url":""}]},{"id":"s9-414","number":414,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"لماذا فصل جزاء المؤمنين بعد إجماله في ﴿سيرحمهم الله﴾؟","answer":"﴿سيرحمهم الله﴾ وعد مجمل، ثم فصلت الآية صور الرحمة من جنات ومساكن ورضوان، لزيادة التشويق وبيان عظم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص619، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-415","number":415,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"لماذا جمع بين الجنات والمساكن الطيبة ورضوان الله؟","answer":"الجنات تجمع نعيم المكان، والمساكن الطيبة راحته واستقراره، والرضوان نعيم القرب والقبول؛ فجمع نعيم الحس والروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص625، تحت «فائدة عطف جملة ومساكن طيبة على الجنات»","url":""}]},{"id":"s9-416","number":416,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ورضوان من الله أكبر﴾ مع عظمة الجنة؟","answer":"عطف الرضوان على نعيم الجنات ليرتقي من نعمة المكان إلى رضا المنعم، و﴿من الله﴾ تشرفه بمصدره. وحُذف متعلق ﴿أكبر﴾ ليعم: فرضوان الله أكبر من كل ما سبق ومن كل نعيم يتصوره الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص627، تحت «فائدة العطف في قوله تعالى ورضوان»","url":""}]},{"id":"s9-418","number":418,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك هو الفوز العظيم﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقوي الحكم ويفيد القصر: هذا الجزاء الجامع للنعيم والرضوان هو الفوز العظيم حقًا، لا متاع الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص629، تحت «بلاغة القصر في فاصلة الآية»","url":""}]},{"id":"s9-419","number":419,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿ورضوان من الله﴾، وقوله تعالى في التوبة: ﴿ورضوان من الله أكبر﴾؟","answer":"في التوبة سبق تفصيل الجنان والمساكن، فناسب التصريح بـ﴿أكبر﴾ ليقرر أن رضوان الله أعظم من ذلك كله. أما الموضع الآخر فاكتفى بذكر الرضوان ضمن الجزاء من غير هذه المقارنة السياقية الصريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص627، تحت «فائدة العطف في قوله تعالى ورضوان»","url":""}]},{"id":"s9-420","number":420,"surah":9,"verses":[72,89,100,111],"references":[{"surah":9,"verses":[72,89,100,111]}],"verseLabel":"التوبة: 72؛ التوبة: 89، 100، 111","question":"ما سرّ اختلاف التعبير في سورة التوبة بين: ﴿ذلك هو الفوز العظيم﴾، و﴿ذلك الفوز العظيم﴾، و﴿وذلك هو الفوز العظيم﴾؟","answer":"في الآية 72 أكد الجزاء الجامع للنعيم والرضوان بضمير الفصل والقصر. وفي 89 جاءت ﴿ذلك الفوز العظيم﴾ بلا واو لشدة اتصالها بما قبلها وتوكيده، وبلا ضمير فصل في خطاب هذه الطائفة المعينة. وفي 100 جاءت الجملة استئنافًا بعد تفصيل حال السابقين وأتباعهم، لتوجيه الانتباه إلى عظم فوزهم. وفي 111 استؤنفت بالواو بعد الأمر بالاستبشار بالبيع، وأكد الفوز بضمير الفصل؛ فلكل موضع صلته بسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص366، تحت «بلاغة التذييل التعليلي في الإشارة إلى الفوز العظيم»","url":""}]},{"id":"s9-421","number":421,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"لماذا جمع النبي ﷺ في أمر واحد بين جهاد الكفار والمنافقين؟","answer":"جمعهما لأن الفريقين يعادون الدعوة، لكن جهاد الكفار يكون بالسلاح والحجة، وجهاد المنافقين بإقامة الحجة وكشف النفاق وإجراء الأحكام والغلظة المناسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص637، تحت «دلالة الحقيقة والمجاز في قوله جاهد»","url":""}]},{"id":"s9-422","number":422,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿واغلظ عليهم﴾ بعد الأمر بالجهاد؟","answer":"الأمر بالغلظة يبين الهيئة التي يقتضيها الجهاد حين لا يصلح اللين: حزم يمنع الكفار والمنافقين من التمادي في الأذى. واستعيرت الغلظة، وهي صفة للأجسام، للشدة في المعاملة والموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص640، تحت «دلالة الأمر بالغلظة بعد الأمر بالجهاد»","url":""}]},{"id":"s9-423","number":423,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"لماذا كانت خاتمة الآية: ﴿ومأواهم جهنم وبئس المصير﴾؟","answer":"يبين السياق بعد الأمر بجهادهم والغلظة عليهم مآلهم في الآخرة: جهنم مستقرهم، وبئس المرجع الذي ينتهون إليه. وفي ذكر المأوى على سبيل التهكم زيادة في التهديد، ثم جاء الذم تقريرًا لسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص641، تحت «دلالة الوصل بالواو في ومأواهم جهنم»","url":""}]},{"id":"s9-424","number":424,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر﴾؟","answer":"قابل حلفهم المؤكد بالنفي بتوكيدين: اللام و﴿قد﴾ في ﴿ولقد قالوا﴾؛ ففضح كذب اليمين وأثبت قولهم ثبوتًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص652، تحت «سر التأكيد في ولقد قالوا كلمة الكفر»","url":""}]},{"id":"s9-425","number":425,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا أبهم القول فقال: ﴿كلمة الكفر﴾ ولم ينقل عبارتهم؟","answer":"ثم سماه ﴿كلمة الكفر﴾ ليصف حقيقته ويثبت بطلان إنكارهم؛ والمراد بالكلمة هنا الكلام الذي قالوه، لا مجرد لفظ مفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص652، تحت «سر حذف متعلق الفعل قالوا»","url":""}]},{"id":"s9-426","number":426,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وكفروا بعد إسلامهم﴾ لا «بعد إيمانهم»؟","answer":"﴿إسلامهم﴾ يدل على الانقياد الظاهر الذي أعلنوه، ولا يشهد لهم بإيمان قلبي؛ ثم أظهرت كلمة الكفر حقيقة باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص655، تحت «بلاغة الاستعارة في وكفروا بعد إسلامهم»","url":""}]},{"id":"s9-427","number":427,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وهموا بما لم ينالوا﴾ ولم يصرح بما هموا به؟","answer":"أبهم الأمر باسم الموصول لشناعة ما هموا به، مع بيان أنهم لم يبلغوه. ويفسره الموضع المعاين بمحاولة قتل الرسول ﷺ، وفي ﴿لم ينالوا﴾ إظهار فشل كيدهم وعصمة الله له من أعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص657، تحت «دلالة التعبير بالفعل الماضي وهموا»","url":""}]},{"id":"s9-428","number":428,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما المفارقة في قوله: ﴿وما نقموا إلا أن أغناهم الله ورسوله من فضله﴾؟","answer":"ذكر الإغناء في موضع ما ينقمونه، مع أنه إحسان يقتضي الشكر؛ فليس لهم سبب صحيح للنقمة. وهذا من تأكيد المدح بما يشبه الذم، وفيه كشف جحودهم إذ قابلوا النعمة بالعداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص659–660، تحت «بلاغة تأكيد المدح بما يشبه الذم»","url":""}]},{"id":"s9-429","number":429,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا نُسب الإغناء إلى الله ورسوله ثم أُفرد الفضل في ﴿من فضله﴾؟","answer":"الإغناء وقع بتقدير الله وعلى يد رسوله ﷺ في القسمة، أما الفضل فمن الله وحده؛ لذلك عاد الضمير مفردًا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص660، تحت «دلالة عطف الرسول على الاسم الأعظم في قوله إلا أن أغناهم الله ورسوله»","url":""}]},{"id":"s9-430","number":430,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا فُتح باب التوبة بعد كل هذه الجرائم: ﴿فإن يتوبوا يك خيرًا لهم﴾؟","answer":"فتح باب التوبة بيان لسعة الرحمة وإقامة للحجة؛ فمع عظم جرائمهم يكون رجوعهم خيرًا لهم من الإصرار الذي يجر عذاب الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص662، تحت «دلالة الفاء في فإن»","url":""}]},{"id":"s9-431","number":431,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يتولوا يعذبهم الله عذابًا أليمًا في الدنيا والآخرة﴾؟","answer":"قابل الشرطان طريقين واضحين: التوبة خير لهم، والتولي يفضي إلى عذاب مؤلم في الدنيا والآخرة؛ فاستوعب المآل العاجل والآجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص663، تحت «نكتة تقديم التوبة على التولي»","url":""}]},{"id":"s9-432","number":432,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا ختم بنفي الولي والنصير في الأرض؟","answer":"نفي الولي والنصير يقطع طمعهم في حماية تنفعهم من عذاب الله؛ فلا قريب يتولى أمرهم ولا معين يدفع عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص667، تحت «نكتة التعبير بلفظ الأرض»","url":""}]},{"id":"s9-433","number":433,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من عاهد الله﴾، فنسب العهد إلى الله مباشرة؟","answer":"العهد مع الله يغلظ مسؤولية الوعد؛ فهم لم يعدوا الناس فقط، بل التزموا لله إن رزقهم أن يتصدقوا ويصلحوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص673–674، تحت «نكتة التعبير بالاسم الأعظم الله»","url":""}]},{"id":"s9-434","number":434,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنصدقن ولنكونن من الصالحين﴾؟","answer":"اللام ونون التوكيد الثقيلة في الفعلين تشددان الوعد وتكشفان عظم إخلافه حين جاءهم الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص674، تحت «دلالة اللام في لئن»","url":""}]},{"id":"s9-435","number":435,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"لماذا جمعوا بين الصدقة والصلاح؟","answer":"الصدقة عمل مالي مخصوص، وكونهم من الصالحين وصف أعم يشمل الوفاء والطاعة؛ فوعدوا ببذل المال وإصلاح الحال كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص670، تحت «مناسبة الآيات لما قبلها»","url":""}]},{"id":"s9-436","number":436,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما آتاهم من فضله بخلوا به﴾؟","answer":"الفاء تفيد التعقيب: ما إن تحقق الإيتاء حتى قابلوه بالبخل، و﴿من فضله﴾ تذكر بأن المال تفضل من الله لا ملك مستقل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص677، تحت «دلالة الفاء في فلما»","url":""}]},{"id":"s9-437","number":437,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿وتولوا وهم معرضون﴾، فجمع بين التولي والإعراض؟","answer":"﴿تولوا﴾ يصور انصرافهم بالفعل بعد أن تحقق لهم الفضل، ثم تكشف الحال ﴿وهم معرضون﴾ أن ذلك الانصراف صادر عن صدود قلبي راسخ؛ فجمع التعبير بين حركة الظاهر وموقف الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص677، تحت «دلالة الفعل المضعف وتولوا»","url":""}]},{"id":"s9-438","number":438,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"لماذا جاءت ﴿وهم معرضون﴾ جملة اسمية؟","answer":"الجملة الاسمية تثبت الإعراض صفة مستقرة فيهم حال توليهم، لا فعلًا طارئًا وقع مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص678، تحت «دلالة التعبير بالجملة الاسمية وهم معرضون»","url":""}]},{"id":"s9-439","number":439,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"ما وجه قوله تعالى: ﴿فأعقبهم نفاقًا في قلوبهم﴾ مع وصفهم قبل ذلك بالنفاق؟","answer":"المعنى أن إخلاف العهد والكذب أورثاهم نفاقًا ثابتًا متزايدًا لازم قلوبهم إلى الموت أو لقاء الله؛ فالجزاء زيادة النفاق ورسوخه، لا ابتداء كل نفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص680، تحت «نكتة تنكير لفظ نفاقًا»","url":""}]},{"id":"s9-440","number":440,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"لماذا أسند إعقاب النفاق إلى الله أو إلى البخل بحسب توجيه الضمير؟","answer":"على عود الضمير إلى الله فالإعقاب جزاء إلهي عادل على البخل والإخلاف، وعلى عوده إلى البخل فالمعنى أن فعلهم صار سببًا ملازمًا للنفاق؛ والنتيجة واحدة في ترتيب الجزاء على الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص679، تحت «دلالة الفاء في فأعقبهم»","url":""}]},{"id":"s9-441","number":441,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يلقونه﴾ بدل «إلى موتهم»؟","answer":"﴿إلى يوم يلقونه﴾ يستحضر الوقوف بين يدي الله وما بعد الموت من حساب، فهو أبلغ في الوعيد من ذكر الموت وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص681، تحت «بلاغة الكناية إلى يوم يلقونه»","url":""}]},{"id":"s9-442","number":442,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"لماذا علل النفاق بإخلاف الوعد والكذب معًا؟","answer":"جمع بين إخلاف الوعد والكذب لبيان تعدد أسباب رسوخ النفاق؛ فذكر الإخلاف ونص على الكذب مع دخوله فيه لتغليظ جرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص681، تحت «دلالة الباء في بما»","url":""}]},{"id":"s9-443","number":443,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"لماذا سأل: ﴿ألم يعلموا أن الله يعلم سرهم ونجواهم﴾؟","answer":"الاستفهام للتقرير والتوبيخ: أي إنهم يعلمون أن الله يحيط بما يسرونه وما يتناجون به، فكيف يخفون إخلافهم وكذبهم؟ وفصل الجملة يستأنف الحجة ويواجههم بها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص686، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-444","number":444,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"ما الفرق بين ﴿سرهم﴾ و﴿نجواهم﴾؟","answer":"السر ما يضمره الإنسان أو يخفيه في نفسه، والنجوى حديث خفي بين اثنين فأكثر؛ فجمع علمه بالباطن الفردي والخفي المتبادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص692، تحت «السر والنجوى»","url":""}]},{"id":"s9-445","number":445,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"لماذا ختم بـ﴿وأن الله علام الغيوب﴾ بصيغة المبالغة؟","answer":"﴿علّام﴾ صيغة مبالغة تدل على سعة العلم وإحاطته بكل غائب وخفي، فلا يخرج عنه سر ولا نجوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص690، تحت «نكتة التأكيد في وأن الله علام الغيوب»","url":""}]},{"id":"s9-446","number":446,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا وصف المنافقين بأنهم ﴿يلمزون المطوعين﴾؟","answer":"اللمز طعن بقصد الانتقاص، والمضارع ﴿يلمزون﴾ يصور تجدد فعلهم واعتيادهم له؛ فهم يعيبون المتصدقين كلما وجدوا سبيلًا، لا لأنهم ينقدون فعلًا معينًا بإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص696، تحت «نكتة التعبير بالفعل المضارع يلمزون»","url":""}]},{"id":"s9-447","number":447,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا جمع بين السخرية من كثير الصدقة وقليلها؟","answer":"جمع الفريقين ليكشف أن غرض المنافقين ليس تقويم الصدقة؛ فكثيرها عندهم رياء وقليلها سخرية، فلا يسلم عندهم صاحب خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص697، تحت «دلالة أل في لفظ المطوعين»","url":""}]},{"id":"s9-448","number":448,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين لا يجدون إلا جهدهم﴾؟","answer":"القصر بـ﴿لا يجدون إلا جهدهم﴾ يبرز أنهم بذلوا غاية ما يملكون مع قلته، فيعظم إخلاصهم وتشتد بشاعة السخرية منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص698، تحت «بلاغة الإطناب»","url":""}]},{"id":"s9-449","number":449,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا جاء الجزاء بلفظ فعلهم: ﴿سخر الله منهم﴾؟","answer":"قوبلت سخريتهم بالمؤمنين بسخرية الله منهم جزاءً من جنس عملهم؛ فيعاملهم بما يهينهم ويكشف خبيئة كفرهم، مع إبقاء أحكام الإسلام الظاهرة عليهم إلى أن يلقوا وعيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص699، تحت «براعة المقابلة»","url":""}]},{"id":"s9-450","number":450,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا ختم بـ﴿ولهم عذاب أليم﴾؟","answer":"العذاب الأليم جزاء يناسب أذاهم للمؤمنين وسخريتهم من الطاعة، والجملة الاسمية تثبت استحقاقه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص700، تحت «نكتة تقديم ما حقه التأخير»","url":""}]},{"id":"s9-451","number":451,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿استغفر لهم أو لا تستغفر لهم﴾ بصيغة التسوية؟","answer":"الأمر للتسوية في انتفاء النتيجة: استغفارك لهم وعدمه سواء ما داموا مصرين على الكفر؛ وليس المقصود طلب أحد الفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص704، تحت «دلالة الأمر في استغفر»","url":""}]},{"id":"s9-452","number":452,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا ذُكر العدد ﴿سبعين مرة﴾؟","answer":"السبعون تجري في أساليب العرب مجرى التكثير والمبالغة، والمعنى أن كثرة الاستغفار لا تنفعهم مع بقاء سبب المنع، لا أن الزيادة تضمن المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص711، تحت «دلالة لفظ سبعين ودلالته»","url":""}]},{"id":"s9-453","number":453,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا علل عدم المغفرة بكفرهم بالله ورسوله؟","answer":"بينت العلة أن المانع ليس قلة الاستغفار، بل كفرهم بالله ورسوله؛ والمغفرة لا تنال مع الإصرار على أصل الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص713، تحت «دلالة اسم الإشارة ذلك»","url":""}]},{"id":"s9-454","number":454,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما دلالة إيراد جملة ﴿والله لا يهدي القوم الفاسقين﴾ اسمية من دون مؤكدات؟","answer":"تفيد الاسمية ثبات انتفاء الهداية واستمراره ما دام الفسق وصفهم، وجاءت من دون مؤكدات لأن سياق أفعالهم شاهد ظاهر يغني عن التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص714، تحت «دلالة إيراد الجملة الاسمية من دون مؤكدات»","url":""}]},{"id":"s9-746","number":746,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما علاقة تذييل الآية بـ﴿والله لا يهدي القوم الفاسقين﴾ بمعناها؟","answer":"الخاتمة تعلل عدم المغفرة بأنهم خرجوا عن الطاعة ورسخ الفسق فيهم، فلا يوفقهم الله للهداية ما داموا مختارين لهذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص715، تحت «علاقة تذييل الآية بمعناها»","url":""}]},{"id":"s9-747","number":747,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا أوثر لفظ ﴿الفاسقين﴾ بدلًا من المنافقين؟","answer":"لأن الفسق هو الوصف الذي يبين علة حرمانهم من الهداية، وهو أعم من اسم المنافقين وأشد اتصالًا بالحكم المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص716، تحت «إيثار لفظ الفاسقين بدلًا من المنافقين»","url":""}]},{"id":"s9-455","number":455,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في التوبة: ﴿استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم﴾، وقوله تعالى في المنافقون: ﴿سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم﴾؟","answer":"جاءت آية التوبة في صورة الأمر والتخيير مع ذكر السبعين، والمراد عند حملها على التسوية انتفاء المغفرة ولو كثر الاستغفار. أما آية المنافقون فصرحت بالتسوية بلفظ ﴿سواء عليهم﴾. ويذكر المصدر وجوهًا للجمع بينهما، منها أن الثانية تبين الأولى وتكشف أن الزيادة على السبعين لا تنفع مع الإصرار على النفاق، ومنها اختلاف الطائفة المخاطب بشأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص716–717، تحت «المتشابه اللفظي»","url":""}]},{"id":"s9-456","number":456,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا سُمّي المتخلفون ﴿المخلفون﴾ بالبناء للمجهول؟","answer":"﴿المخلّفون﴾ يشعر بأنهم تُركوا وراء الخارجين وحرموا شرف صحبتهم، مع أنهم اختاروا التخلف؛ ففي الصيغة ذم وإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص723، تحت «دلالة أل في المخلفون»","url":""}]},{"id":"s9-457","number":457,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما دلالة التعبير بقوله: ﴿بمقعدهم﴾؟","answer":"جعل قعودهم نفسه متعلق فرحهم، فكأن موضع التخلف صار غاية يسرون بها. وإفراد ﴿مقعد﴾ باعتباره مصدرًا أو اسم جنس يجمع قعودهم المتعدد في هيئة واحدة مذمومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص724، تحت «دلالة الجار والمجرور بمقعدهم»","url":""}]},{"id":"s9-748","number":748,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما سرّ اختيار ﴿خلاف رسول الله﴾؟","answer":"تحتمل ﴿خلاف﴾ معنى التخلف وراء الرسول ﷺ ومعنى مخالفته؛ فتجمع الكلمة قعودهم المكاني عن الخروج وصدودهم المعنوي عن أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص725، تحت «فوائد إيثار لفظ خلاف»","url":""}]},{"id":"s9-458","number":458,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿كرهوا أن يجاهدوا بأموالهم وأنفسهم﴾؟","answer":"المصدر المؤول يبين متعلق كراهيتهم: نفس الجهاد بالمال والنفس؛ وهو يكشف أن التخلف لم يكن عذرًا بل نفورًا من التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص726، تحت «عطف جملة وكرهوا على ما قبلها»","url":""}]},{"id":"s9-459","number":459,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما سرّ تقديم الأموال على الأنفس حتى في وصف كراهتهم؟","answer":"قدم الأموال لأن بذلها مقدمة لإعداد القتال، ولأن الحاجة إلى الجهاد بالمال أوسع؛ فالمجاهد بنفسه يحتاج إلى ما يجهزه ويعينه. وناسب ذكرها هنا كشف كراهتهم لما يتطلبه الجهاد من بذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص728، تحت «سر تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-460","number":460,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما دلالة قولهم: ﴿لا تنفروا في الحر﴾؟","answer":"قالوها تثبيطًا لغيرهم واعتذارًا بحر تبوك؛ فجمعوا تخلفهم الشخصي ومحاولة صرف المؤمنين عن النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص731، تحت «وجه العطف في وقالوا»","url":""}]},{"id":"s9-461","number":461,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا جاء الرد: ﴿قل نار جهنم أشد حرًا﴾؟","answer":"رد عليهم من جنس عذرهم: إن فروا من حر يسير مؤقت فقد عرضوا أنفسهم لحر جهنم الأشد، فالموازنة تبطل حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص732، تحت «وجه الرد عليهم»","url":""}]},{"id":"s9-462","number":462,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا ختم بـ﴿لو كانوا يفقهون﴾ لا «يعلمون»؟","answer":"الفقه فهم ينفذ إلى العواقب، لا مجرد معرفة أن النار أشد حرًا؛ فلو فقهوا لآثروا مشقة الساعة على عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص735، تحت «فائدة قوله تعالى لو كانوا يفقهون ودلالته»","url":""}]},{"id":"s9-463","number":463,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿فليضحكوا قليلًا وليبكوا كثيرًا﴾ بصيغة الأمر؟","answer":"الأمران للتهديد والإخبار بالمآل، لا لطلب الضحك والبكاء؛ أي ضحكهم في الدنيا قليل وسيتبعه بكاء كثير في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص741، تحت «دلالة اللام في الفعل فليضحكوا»","url":""}]},{"id":"s9-464","number":464,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"لماذا قابل القليل بالكثير والضحك بالبكاء؟","answer":"قابل الضحك بالبكاء والقليل بالكثير لإظهار التفاوت بين متاعهم العاجل القصير وحسرتهم وعذابهم الطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص743، تحت «بلاغة المقابلة»","url":""}]},{"id":"s9-465","number":465,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿جزاء بما كانوا يكسبون﴾، فاختار الكسب؟","answer":"اختير ﴿يكسبون﴾ لأن الكسب ما يتعمد الإنسان تحصيله لنفسه، فدل على مسؤوليتهم عن النفاق والتثبيط. وصيغة المضارع مع ﴿كانوا﴾ تصور دوام هذا السلوك وتجدد آثاره حتى صار الجزاء من جنس ما اكتسبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص746، تحت «إيثار لفظ يكسبون دون مرادفاته»","url":""}]},{"id":"s9-466","number":466,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن رجعك الله إلى طائفة منهم﴾، دون أن يقال: «إذا رجعت»؟","answer":"اختيرت ﴿إن﴾ لأن الرجوع من السفر، بحسب ما يترقبه المخاطبون، أمر معلق بما يقدره الله لا موعدًا يتصرفون فيه؛ وفي ذلك إبقاء للشرط مع ربط المآل كله بمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص752، تحت «إيثار إن على إذا»","url":""}]},{"id":"s9-749","number":749,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"لماذا صُرّح باسم الله في قوله: ﴿فإن رجعك الله﴾؟","answer":"التصريح باسم الجلالة يقرر أن الرجوع بتقدير الله وحفظه، وأن الحكم اللاحق في المتخلفين صادر عن سلطانه، لا عن رغبة شخصية من الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص753، تحت «دلالة التصريح باسم الجلالة»","url":""}]},{"id":"s9-467","number":467,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى طائفة منهم﴾ لا «إليهم»؟","answer":"قال ﴿طائفة منهم﴾ لأن بعض المتخلفين قد يهلك أو يغيب، ولأن الحكم متعلق بمن بقي ممن استحق هذا التأديب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص754، تحت «دلالة لفظ طائفة»","url":""}]},{"id":"s9-468","number":468,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما دلالة توكيد المنع في قوله: ﴿لن تخرجوا معي أبدًا ولن تقاتلوا معي عدوًا﴾؟","answer":"أكدت ﴿لن﴾ نفي خروجهم وقتالهم في المستقبل، وزاد ﴿أبدًا﴾ المنع استغراقًا، فصار الخبر في قوة النهي والعقوبة: لما رضوا بالتخلف أول مرة حُرموا شرف المشاركة بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص756، تحت «إيثار النفي بلن»","url":""}]},{"id":"s9-469","number":469,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿رضيتم بالقعود أول مرة﴾؟","answer":"﴿رضيتم﴾ يثبت أن القعود كان اختيارًا استحسنوه لا اضطرارًا، و﴿أول مرة﴾ تجعل موقف تبوك أصلًا يترتب عليه حرمانهم اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص760، تحت «نكتة التعبير بالرضا عن القعود»","url":""}]},{"id":"s9-470","number":470,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فاقعدوا مع الخالفين﴾؟","answer":"الأمر للإهانة والتثبيت على الجزاء: الزموا القعود مع من شأنهم التخلف، بعد أن رضيتم لأنفسكم به حين دعاكم الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص761، تحت «دلالة الفاء في فاقعدوا»","url":""}]},{"id":"s9-471","number":471,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا نُهي النبي ﷺ عن الصلاة على أحد منهم مات أبدًا؟","answer":"النهي الدائم يقطع ما في الصلاة عليه من تكريم ودعاء واستغفار؛ لأن موته على الكفر يمنع المغفرة ويكشف حقيقة نفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص767، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-472","number":472,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا جمع بين ﴿ولا تصل على أحد﴾ و﴿ولا تقم على قبره﴾؟","answer":"الصلاة دعاء للميت، والقيام على القبر يشمل شهود دفنه والدعاء له؛ فجمع النهي عن وجهي التكريم بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص770، تحت «فائدة عطف جملة ولا تقم على قبره»","url":""}]},{"id":"s9-473","number":473,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا علل النهي بأنهم كفروا وماتوا وهم فاسقون؟","answer":"الكفر يبين فساد الاعتقاد، والموت على الفسق يبين استمرار الخروج عن الطاعة إلى النهاية؛ فالعبرة بالخاتمة من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص771، تحت «سر فصل جملة إنهم كفروا»","url":""}]},{"id":"s9-474","number":474,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿ماتوا وهم فاسقون﴾، دون أن يقال: «منافقون»؟","answer":"الفسق هو الخروج عن الطاعة، وهو أعم من الكفر والنفاق في الأصل، لكن السياق يجعله هنا وصفًا كاشفًا لاستمرار خروجهم عن الإيمان إلى الموت؛ فناسب مقام بيان سوء الخاتمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص773، تحت «إيثار لفظ فاسقون دون غيره»","url":""}]},{"id":"s9-475","number":475,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"لماذا تكرر النهي: ﴿ولا تعجبك أموالهم وأولادهم﴾ من الآية 55؟","answer":"أعيد النهي لتقرير التحذير وتأكيده مع تجدد السياق وما قد يثير الإعجاب بالأموال والأولاد. ويذكر المصدر وجهًا آخر، وهو اختلاف الطائفتين المقصودتين؛ فلا يحصر سبب التكرار في هذا الوجه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص780–781، تحت «فائدة التكرار في ولا تعجبك»","url":""}]},{"id":"s9-476","number":476,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿أن يعذبهم بها في الدنيا﴾، وقال سابقًا: ﴿في الحياة الدنيا﴾؟","answer":"ذُكرت ﴿الحياة الدنيا﴾ أولًا بتمام الموصوف والصفة، ثم حذف الموصوف هنا اكتفاء بسبق ذكره؛ والدنيا هي الحياة القريبة المقابلة للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص784، تحت «المتشابه اللفظي»","url":""}]},{"id":"s9-477","number":477,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"لماذا أعيدت خاتمة ﴿وتزهق أنفسهم وهم كافرون﴾؟","answer":"تقرر الخاتمة اقتران خروج أرواحهم بالكفر، فتصل ما يعانونه في الدنيا بعاقبتهم بعد الموت. وتكرار هذا الوصف في السورة يكشف حال المنافقين عند قبض أرواحهم ويحذر من الاغترار بظاهر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص786، تحت «دلالة الواو في وتزهق»","url":""}]},{"id":"s9-478","number":478,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما دلالة ﴿أن﴾ في قوله: ﴿أن آمنوا بالله وجاهدوا مع رسوله﴾؟","answer":"تأتي ﴿أن﴾ تفسيرية فتشرح مضمون السورة المنزلة: الأمر بالإيمان والجهاد مع الرسول ﷺ؛ وبذلك ينتقل الكلام من ذكر نزول السورة إلى بيان التكليف الذي فضح موقف المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص797، تحت «دلالة أن في أن آمنوا وأثرها في المعنى»","url":""}]},{"id":"s9-750","number":750,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما سرّ تقديم الأمر بالإيمان على الأمر بالجهاد؟","answer":"قدم الإيمان لأنه أصل الأعمال وشرط قبول الجهاد، ثم عطف الجهاد بوصفه الأثر العملي الذي يمتحن صدق ذلك الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص797، تحت «سر تقديم الأمر بالإيمان على الأمر بالجهاد»","url":""}]},{"id":"s9-479","number":479,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿استأذنك أولو الطول منهم﴾، وخص أهل القدرة؟","answer":"﴿أولو الطول﴾ أصحاب السعة والقدرة، وخصوا لأن استئذان العاجز قد يعذر، أما استئذان القادر فيكشف النفاق وشدة التعلق بالدعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص798، تحت «سر التعبير بأولو الطول»","url":""}]},{"id":"s9-480","number":480,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما دلالة قولهم: ﴿ذرنا نكن مع القاعدين﴾؟","answer":"﴿ذرنا﴾ طلب ترك يحمل معنى التعلل والإصرار، و﴿مع القاعدين﴾ يكشف رضاهم بالانضمام إلى أهل الأعذار ومن لا ينهض للجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص799، تحت «دلالة الأمر في قوله ذرنا ودلالته»","url":""}]},{"id":"s9-481","number":481,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿رضوا بأن يكونوا مع الخوالف﴾، فجعل القعود موضع رضا؟","answer":"جعل القعود موضع رضا لبيان أنهم لم يقعوا فيه كارهين أو معذورين، بل اختاروا منزلة الخوالف واستحبوها على صحبة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص12، تحت «سر العدول إلى الإخبار برضاهم أن يكونوا مع الخوالف»","url":""}]},{"id":"s9-482","number":482,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"لماذا اختيرت ﴿الخوالف﴾ لا «القاعدين»؟","answer":"﴿الخوالف﴾ يغلب في النساء أو من شأنه البقاء خلف الخارجين، فاختيارها أشد إزراء بالرجال القادرين الذين رضوا لأنفسهم هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص14، تحت «سر اصطفاء صيغة الجمع في الخوالف»","url":""}]},{"id":"s9-483","number":483,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما دلالة عطف ﴿وطبع على قلوبهم﴾ على رضاهم بالقعود مع الخوالف؟","answer":"يصل العطف بين اختيارهم القعود وحال قلوبهم؛ فرضاهم بالدعة والصدود عن الجهاد أفضى إلى انغلاقها عن الهدى. ثم جاءت الفاء في ﴿فهم لا يفقهون﴾ لترتب حرمان الفهم النافع على ذلك الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «دلالة الفاء في فهم»","url":""}]},{"id":"s9-484","number":484,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما الصورة في ﴿طبع على قلوبهم﴾؟","answer":"شُبهت قلوبهم بشيء ختم عليه فلا يدخله نور ولا يخرج ما فيه؛ فهي استعارة تصور انغلاقها عن فهم الحق وقبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص16، تحت «الغرض من التعبير بالاستعارة في وطبع»","url":""}]},{"id":"s9-485","number":485,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"لماذا كانت النتيجة: ﴿فهم لا يفقهون﴾ لا «لا يعلمون»؟","answer":"الفقه فهم دقيق يثمر اعتبارًا وعملًا؛ وقد حجب الطبع قلوبهم عن هذا الفهم، وإن أدركوا ظواهر الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «سر التعبير بلفظ لا يفقهون»","url":""}]},{"id":"s9-486","number":486,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"لماذا استدرك بقوله: ﴿لكن الرسول والذين آمنوا معه﴾ بعد وصف المتخلفين؟","answer":"يقابل الاستدراك تخلف المنافقين بجهاد الرسول ﷺ والمؤمنين معه؛ فإن قعد أولئك فقد نهض غيرهم بالنصرة. وفي ذلك بيان الاستغناء عن المتخلفين وإبراز فضل أهل الإيمان وبشارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص24، تحت «دلالة حرف الاستدراك وعلاقته بما قبله»","url":""}]},{"id":"s9-487","number":487,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿الرسول﴾ بالوصف ولم يذكر اسمه؟","answer":"وصف ﴿الرسول﴾ يستحضر موجب اتباعه ونصره؛ فالجهاد معه مقتضى رسالته، والتخلف عنه مخالفة لوظيفته في الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص25، تحت «دلالة أل في لفظ الرسول وأثرها في السياق»","url":""}]},{"id":"s9-488","number":488,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿جاهدوا بأموالهم وأنفسهم﴾، وأعاد الوصف المألوف؟","answer":"إعادة الأموال والأنفس تقابل كراهة المنافقين لهما، وتبين أن المؤمنين بذلوا أعز ما يملكون في الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص28، تحت «الغرض من تقديم الأموال على الأنفس في السياق»","url":""}]},{"id":"s9-489","number":489,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما دلالة التعبير بـ﴿الخيرات﴾ دون تقييدها بنوع واحد؟","answer":"يدل الجمع والتعريف على وفرة الخيرات وشمولها لمنافع الدنيا والآخرة، فيندرج فيها النصر والكرامة والثواب والجنة؛ وجاءت غير مقيدة بنوع لتتسع لهذه البشارات.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص29، تحت «دلالة الجمع في لفظ الخيرات»","url":""}]},{"id":"s9-490","number":490,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"لماذا كرر اسم الإشارة: ﴿وأولئك لهم الخيرات وأولئك هم المفلحون﴾؟","answer":"كرر الإشارة ليجعل لكل بشارة استقلالًا: لهم جميع الخيرات، وهم المفلحون؛ وضمير الفصل يؤكد اختصاصهم بالفلاح الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص30، تحت «فائدة تكرار اسم الإشارة»","url":""}]},{"id":"s9-491","number":491,"surah":9,"verses":[89],"references":[{"surah":9,"verses":[89]}],"verseLabel":"التوبة: 89","question":"لماذا انتقل من ﴿الخيرات﴾ إلى تفصيل الجنات؟","answer":"فصلت الجنات بعد إجمال ﴿الخيرات﴾ لبيان أعظم خيرات الآخرة وتشويق النفس إليها بعد الوعد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص34، تحت «الغرض من كمال الاتصال في الجملة أعد من السياق»","url":""}]},{"id":"s9-493","number":493,"surah":9,"verses":[89],"references":[{"surah":9,"verses":[89]}],"verseLabel":"التوبة: 89","question":"لماذا جمع بين ﴿خالدين فيها﴾ و﴿ذلك الفوز العظيم﴾؟","answer":"﴿خالدين فيها﴾ ينفي انقطاع النعيم، و﴿ذلك الفوز العظيم﴾ يحكم بأن نيل المحبوب الدائم والنجاة من المكروه هو الفوز الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص39، تحت «الغرض من كمال الاتصال ذلك الفوز العظيم»","url":""}]},{"id":"s9-494","number":494,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"لماذا فرّق بين ﴿المعذرون﴾ و﴿الذين كذبوا الله ورسوله﴾؟","answer":"﴿المعذرون﴾ جاؤوا يطلبون الإذن ويظهرون عذرًا، وقد يكون فيهم صادق أو مقصر؛ أما الآخرون فقعدوا بلا اعتذار وكذبوا الله ورسوله، فكان جرمهم أصرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص45، تحت «سر اختيار لفظ المعذرون»","url":""}]},{"id":"s9-495","number":495,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاء المعذرون﴾، بينما قال عن الآخرين: ﴿وقعد الذين كذبوا﴾؟","answer":"المعذرون تحملوا المجيء لعرض أعذارهم، أما المكذبون فقعدوا من غير اكتراث ولا محاولة اعتذار؛ فاختلاف الفعلين يصور تفاوت الحال والجرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص48، تحت «سر التعبير بالجملة الخبرية وجاء المعذرون»","url":""}]},{"id":"s9-496","number":496,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما دلالة قوله: ﴿كذبوا الله ورسوله﴾، وتعدية كذبوا من غير حرف جر؟","answer":"على قراءة التخفيف، معناه أنهم أخبروا الله ورسوله بخلاف ما في قلوبهم، فكانت دعوى إيمانهم أو وعدهم بالنصرة كاذبًا. وذكر المصدر قراءة التشديد بمعنى التكذيب؛ فهذان توجيهان مرتبطان باختلاف القراءة، لا معنى واحد للفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص50، تحت «سر التصريح بمعمول الفعل الله ورسوله»","url":""}]},{"id":"s9-497","number":497,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾، فأدخل ﴿منهم﴾؟","answer":"من أوجه ﴿منهم﴾ التبعيض؛ فالوعيد متعلق بمن ثبت كفره، ولا يعمم على كل الأعراب أو كل من عرض عذرًا. ويذكر المصدر اختلاف مرجع الضمير بين الأعراب والمذكورين من المنافقين والمعذرين، مع احتمال توبة بعضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص52–53، تحت «سر التعبير بالجار والمجرور منهم»","url":""}]},{"id":"s9-498","number":498,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا جمع الضعفاء والمرضى ومن لا يجدون ما ينفقون؟","answer":"جمعت الآية أصحاب الأعذار التي تمنع الجهاد: ضعف البدن، والمرض، وفقد النفقة؛ فاستوعبت العجز الخِلقي والعارض والمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص61، تحت «سر اصطفاء صيغة الجمع الضعفاء»","url":""}]},{"id":"s9-499","number":499,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا اشترط لرفع الحرج: ﴿إذا نصحوا لله ورسوله﴾؟","answer":"رفع الحرج مشروط ببقاء صدقهم وإخلاصهم: ينصحون لله ورسوله ولا يثبطون ولا يخونون، ويؤدون ما قدروا عليه من وجوه الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص65، تحت «دلالة التعبير بالظرف المتضمن معنى الشرط في إذا»","url":""}]},{"id":"s9-500","number":500,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿ما على المحسنين من سبيل﴾، فنفى كل سبيل؟","answer":"﴿من﴾ الزائدة في سياق النفي تفيد الاستغراق: لا طريق إلى لوم المحسنين أو عقابهم من أي وجه ما دام العذر صحيحًا والنصح قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص67، تحت «موقع جملة ما على المحسنين ودلالته»","url":""}]},{"id":"s9-501","number":501,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا وصف أصحاب الأعذار بـ﴿المحسنين﴾؟","answer":"وصفوا بالمحسنين لأنهم مع عجزهم صدقوا النية ونصحوا وبذلوا ما استطاعوا؛ فالإحسان بحسب القدرة لا بمجرد المشاركة البدنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص68، تحت «سر اصطفاء لفظ المحسنين في السياق»","url":""}]},{"id":"s9-502","number":502,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا ختمت آية أصحاب الأعذار (التوبة: 91) بـ﴿والله غفور رحيم﴾؟","answer":"تؤكد الخاتمة رفع الحرج عن أصحاب الأعذار؛ فمن رحمته ألا يكلفهم ما يشق عليهم، ومن مغفرته ألا يؤاخذهم بالتخلف المعذور.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص70، تحت «دلالة تذييل الآية بقوله والله غفور رحيم»","url":""}]},{"id":"s9-751","number":751,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"ما فائدة حذف متعلق صفتي المغفرة والرحمة؟","answer":"يفيد الحذف الإطلاق والعموم، فتتسع المغفرة للذنوب والرحمة لأحوال العباد من غير تقييد بمتعلق معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص71، تحت «فائدة حذف متعلق صفتي المغفرة والرحمة»","url":""}]},{"id":"s9-503","number":503,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا أفرد بالذكر الذين جاؤوا ليُحملوا بعد إدخالهم فيمن لا يجدون ما ينفقون؟","answer":"أفردوا لأن حالهم أبلغ: لم يكتفوا بالرغبة، بل جاؤوا يطلبون ما يحملهم، ثم بكوا حين لم يجدوا؛ فاستحق إخلاصهم تنويهًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص76، تحت «دلالة عطف قوله ولا على الذين على ما قبله»","url":""}]},{"id":"s9-504","number":504,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما دلالة قوله: ﴿قلت لا أجد ما أحملكم عليه﴾ في تصوير حال الرسول ﷺ وطالبي الخروج؟","answer":"يبين أنه ﷺ لم يجد وقتئذ ما يهيئه لحملهم، مع صدق رغبتهم في الخروج. واكتفى أولئك بتصريحه بعدم الوجدان، فصدقوه وانصرفوا حزنى؛ فعبارة الآية تصور العجز عن التجهيز والثقة بقوله معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص79، تحت «موقع جملة قلت ودلالتها»","url":""}]},{"id":"s9-505","number":505,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا عبّر بقوله تعالى: ﴿تولوا﴾ عن رجوع طالبي الخروج؟","answer":"يصوّر التولي رجوعهم عن رسول الله ﷺ مكرهين بعد أن تعلقت نفوسهم بالخروج؛ فالكلمة ترسم انصراف الجسد مع بقاء الرغبة والحزن في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص81، تحت «إيثار لفظ تولوا»","url":""}]},{"id":"s9-752","number":752,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما الصورة في قوله تعالى: ﴿وأعينهم تفيض من الدمع﴾؟","answer":"بالغ التصوير حتى جعل العين نفسها كأنها تفيض، لا الدمع وحده؛ وفي ذلك إشعار بكثرة بكائهم وصدق حزنهم على فوات الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص82، تحت «الغرض من التعبير بالاستعارة في الفعل تفيض»","url":""}]},{"id":"s9-506","number":506,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿حزنًا ألا يجدوا ما ينفقون﴾، دون أن يقال: حزنًا على عدم الخروج؟","answer":"ذكر فقد النفقة لأنه العائق المباشر عن الخروج، وفيه أنهم كانوا يملكون الرغبة والقوة ولم يحبسهم إلا عدم وسيلة الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص84، تحت «الغرض من التعبير بقوله ألا يجدوا ما ينفقون»","url":""}]},{"id":"s9-507","number":507,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا أوثر لفظ ﴿تولوا﴾ في وصف أصحاب الأعذار الصادقين؟","answer":"يصور اللفظ انصرافهم بعد أن توجهت رغبتهم إلى الخروج، فكان رجوعهم اضطرارًا لا إعراضًا عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص81، تحت «إيثار لفظ تولوا»","url":""}]},{"id":"s9-753","number":753,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما الغرض من التعبير بالاستعارة في الفعل ﴿تفيض﴾؟","answer":"صور كثرة الدمع حتى كأن العين إناء يفيض، مبالغة في صدق حزنهم على فوات المشاركة في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص82، تحت «الغرض من التعبير بالاستعارة في الفعل تفيض»","url":""}]},{"id":"s9-754","number":754,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما دلالة كلمة ﴿حزنًا﴾ في سياق فيض أعينهم من الدمع؟","answer":"تكشف أن الدمع ناشئ من حزن صادق على العجز عن النفقة والخروج، لا من تظاهر أو ضعف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص83، تحت «موقع كلمة حزنًا ودلالته»","url":""}]},{"id":"s9-755","number":755,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما سر العدول عن الإخبار إلى الإنشاء في ﴿فليضحكوا قليلًا وليبكوا كثيرًا﴾؟","answer":"جاء الخبر في صورة الأمر للتهكم والوعيد، حتى يبدو الجزاء واقعًا محققًا لا مجرد خبر ينتظر تحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص742، تحت «سر العدول عن الإخبار إلى الإنشاء»","url":""}]},{"id":"s9-756","number":756,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما بلاغة المقابلة بين ﴿فليضحكوا قليلًا﴾ و﴿وليبكوا كثيرًا﴾؟","answer":"قوبل الضحك بالبكاء والقلة بالكثرة، فبرز قصر فرحهم في الدنيا وطول حزنهم في الآخرة في صورة شديدة التأثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص743، تحت «بلاغة المقابلة»","url":""}]},{"id":"s9-508","number":508,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا حصر المؤاخذة بقوله: ﴿إنما السبيل على الذين يستأذنونك وهم أغنياء﴾؟","answer":"﴿إنما﴾ تقصر اللوم والعقوبة على القادرين الذين يستأذنون في القعود، بعد رفع الحرج عن أصحاب الأعذار الصادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص90، تحت «سر اختيار إنما طريقًا لأسلوب القصر في السياق»","url":""}]},{"id":"s9-509","number":509,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا وصفهم بالغنى بدل القوة أو الصحة؟","answer":"الغنى يدل على امتلاك النفقة والوسيلة، وهو موضع العذر السابق؛ فإذا كانوا أغنياء انتفى عذر العجز المالي وظهر اختيارهم للقعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص92، تحت «سر التقييد بالجملة الحالية وهم أغنياء وأثرها في المعنى»","url":""}]},{"id":"s9-510","number":510,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا كرر: ﴿رضوا بأن يكونوا مع الخوالف﴾؟","answer":"كرر وصف رضاهم بمعية الخوالف لتأكيد قبح اختيارهم القعود واستسلامهم لهذه المنزلة مع قدرتهم على الخروج. فالتكرار يثبت ما انطوت عليه نفوسهم من الإعراض وما آل إليه حال قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص93، تحت «دلالة الاستئناف في رضوا»","url":""}]},{"id":"s9-511","number":511,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿وطبع الله على قلوبهم﴾ هنا بإظهار اسم الله، وقال في الآية 87: ﴿وطبع على قلوبهم﴾؟","answer":"في الآية 87 سبق البناء للمجهول في ﴿أنزلت﴾ فناسبه ﴿طبع﴾، وهنا تكرر اسم الله في السياق فصرح به: ﴿وطبع الله﴾؛ وفي الحالين الطبع جزاء إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص94، تحت «سر بناء الفعل للمفعول وطبع وللفاعل وطبع»","url":""}]},{"id":"s9-512","number":512,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا ختم بـ﴿فهم لا يعلمون﴾، بينما ختمت الآية 87 بـ﴿فهم لا يفقهون﴾؟","answer":"يربط المصدر بين الفقه والتفكر والتأمل، وهو من صفات المخلوقين، وبين العلم الذي يوصف به الله. فعلى هذا التوجيه ناسب ﴿لا يفقهون﴾ عدم التصريح بالفاعل في الموضع الأول، وناسب ﴿لا يعلمون﴾ التصريح باسم الله في الثاني؛ وفي حذف المفعول تعميم لنفي العلم النافع عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص96، تحت «دلالة حذف المفعول به من الفعل يعلمون»","url":""}]},{"id":"s9-513","number":513,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا أخبر أنهم سيعتذرون ﴿إذا رجعتم إليهم﴾ قبل وقوع الاعتذار؟","answer":"الإخبار قبل وقوعه دليل على صدق الوحي وكشف لما أضمروه، ويهيئ المؤمنين لئلا يخدعوا بأعذار مصنوعة عند الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص102، تحت «دلالة التعبير بالماضي رجعتم»","url":""}]},{"id":"s9-514","number":514,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا جاء الرد: ﴿قل لا تعتذروا لن نؤمن لكم﴾؟","answer":"نُهوا عن الاعتذار لأن الله كشف أخبارهم، و﴿لن نؤمن لكم﴾ أي لن نصدقكم؛ فانتفى أثر كلامهم بعد ظهور كذبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص104، تحت «دلالة الفصل لن نؤمن لكم»","url":""}]},{"id":"s9-515","number":515,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير بقوله تعالى: ﴿قد نبأنا الله﴾؟","answer":"النبأ خبر عظيم الشأن؛ فاختياره يدل على خطورة ما كشفه الله من أحوال المنافقين، وأنه خبر يقيني يبطل أعذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص106، تحت «سر التعبير بنبأنا»","url":""}]},{"id":"s9-757","number":757,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من أخباركم﴾؟","answer":"تحتمل التبعيض؛ أي أطلع الله رسوله ﷺ على قدر من أخبارهم يكفي لكشف كذبهم، وتحتمل بيان الجنس، وكلا الوجهين يقطع أثر اعتذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص107، تحت «سر التعبير بمن»","url":""}]}]);
